function apiRequestPathname(path = '') {
  try {
    return new URL(String(path || ''), location.origin).pathname;
  } catch {
    return String(path || '').split('?')[0] || '';
  }
}

function frontendAssetBlockBypass(path = '') {
  const pathname = apiRequestPathname(path);
  return pathname === '/api/state'
    || pathname === '/api/session'
    || pathname === '/api/health'
    || pathname === '/api/digest-cancel'
    || pathname === '/api/digest-batch-finish'
    || pathname === '/api/digest-batch-heartbeat';
}

function markFrontendAssetReloadRequired(version = '') {
  _frontendAssetReloadRequired = true;
  const cleanVersion = String(version || '').trim();
  if (cleanVersion) _deferredAssetReloadVersion = cleanVersion;
}

function clearFrontendAssetReloadRequired() {
  _frontendAssetReloadRequired = false;
  _deferredAssetReloadVersion = '';
}

function frontendAssetBlockedError(path = '') {
  if (frontendAssetBlockBypass(path)) return null;
  if (_serviceRestartRequired || _activeSourceAssetVersion) {
    return reloadControlError('SERVICE_RESTART_REQUIRED', '本地代码已更新，但当前服务仍在运行旧代码；请重启本地服务后刷新页面再操作。', 409);
  }
  if (_frontendAssetReloadRequired || _deferredAssetReloadVersion) {
    return reloadControlError('STALE_FRONTEND_RELOAD_CANCELLED', '本地页面版本已更新；请先处理未保存更改后刷新页面。', 409);
  }
  return null;
}

function frontendAssetBusinessRequestsBlocked() {
  return !!(_serviceRestartRequired || _activeSourceAssetVersion || _frontendAssetReloadRequired || _deferredAssetReloadVersion);
}

function assertFrontendAssetNotBlocked(path = '') {
  const err = frontendAssetBlockedError(path);
  if (!err) return;
  if (err.code === 'SERVICE_RESTART_REQUIRED') showAssetReloadNotice(_activeSourceAssetVersion, { reason: 'source_changed' });
  else showAssetReloadNotice(_deferredAssetReloadVersion, { reason: 'api_rejected' });
  throw err;
}

const DEFAULT_API_TIMEOUT_MS = 90_000;
const SETTINGS_SAVE_WAIT_TIMEOUT_MS = 25_000;
const SESSION_BOOTSTRAP_TIMEOUT_MS = 10_000;
const DIGEST_SSE_CONNECT_TIMEOUT_MS = 90_000;
const DIGEST_SSE_IDLE_TIMEOUT_MS = 90_000;
const DIGEST_RESULT_RECOVERY_FALLBACK_MAX_WAIT_MS = 27 * 60 * 1000 + 30_000;
const DIGEST_RESULT_RECOVERY_SERVER_GRACE_MS = 30_000;
const DIGEST_RESULT_RECOVERY_REQUEST_TIMEOUT_MS = 10_000;
const DIGEST_RESULT_RECOVERY_MISSING_CONFIRMATIONS = 3;
const DIGEST_ERROR_RESPONSE_MAX_BYTES = 256 * 1024;
const DIGEST_SSE_RESPONSE_MAX_BYTES = 16 * 1024 * 1024;
const SAVE_RENDER_HTTP_TIMEOUT_MS = 190_000;
const BROWSER_PNG_OPERATION_TIMEOUT_MS = 120_000;
const HISTORY_RERENDER_PREVIEW_HTTP_TIMEOUT_MS = 150_000;
const MARKDOWN_EXPORT_HTTP_TIMEOUT_MS = 180_000;
let _sessionBootstrapPromise = null;

function compactLocalActionExpectedTarget(value = {}) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const aliases = {
    expected_file_version: 'file_version',
    expected_digest_file_version: 'digest_file_version',
  };
  const allowed = ['digest_id', 'history_item_key', 'relative_path', 'file_version', 'digest_file_version', 'output_dir_identity', 'settings_revision'];
  const target = {};
  for (const [rawKey, rawValue] of Object.entries(value)) {
    const key = aliases[rawKey] || rawKey;
    if (!allowed.includes(key)) continue;
    const clean = String(rawValue || '').trim();
    if (clean) target[key] = clean;
  }
  return Object.keys(target).length ? target : null;
}

function localActionKindFromRequest(path = '', actionId = '') {
  const cleanPath = String(path || '').split('?')[0];
  if (cleanPath === '/api/reveal' || cleanPath === '/api/reveal-output') return 'reveal';
  if (cleanPath === '/api/open-output') return 'open_output';
  if (cleanPath === '/api/save-render') return 'save_render';
  if (cleanPath === '/api/export-preview') return 'export_preview';
  if (cleanPath === '/api/history-copy-current-output') return 'history_copy_current_output';
  if (cleanPath.includes('rerender')) return 'history_rerender';
  if (cleanPath === '/api/copy-text' || cleanPath === '/api/copy-path') return 'text_clipboard_copy';
  if (cleanPath.includes('preview') && cleanPath.includes('clipboard')) return 'preview_clipboard_copy';
  if (cleanPath.includes('copy-image') || cleanPath.includes('clipboard')) return 'clipboard_copy';
  const prefix = String(actionId || '').split('_')[0].replace(/-/g, '_');
  return ['reveal', 'open_output', 'save_render', 'export_preview', 'history_rerender', 'history_copy_current_output'].includes(prefix) ? prefix : '';
}

function pendingLocalActionStorageKey(actionId = '') {
  const cleanId = String(actionId || '').trim();
  return /^[a-z0-9][a-z0-9_-]{5,80}$/i.test(cleanId) ? `${LOCAL_ACTION_PENDING_STORAGE_PREFIX}${cleanId}` : '';
}

function normalizePendingLocalActionRecord(value = {}, now = Date.now()) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const actionId = String(value.action_id || '').trim();
  const kind = String(value.kind || '').trim();
  const at = Number(value.at || 0) || 0;
  if (!pendingLocalActionStorageKey(actionId)
    || !LOCAL_ACTION_PENDING_KINDS.has(kind)
    || !at
    || at > now + 60_000
    || now - at > LOCAL_ACTION_EXPECTED_TARGET_TTL_MS) return null;
  return {
    action_id: actionId,
    kind,
    target: compactLocalActionExpectedTarget(value.target || {}),
    at,
  };
}

function localActionRecoveryStorageUnavailableError(error = null) {
  const out = new Error('浏览器无法保存本地操作恢复记录，操作尚未发送；请允许本站使用本地存储后重试。');
  out.status = 503;
  out.code = 'local_action_recovery_storage_unavailable';
  out.userMessage = out.message;
  out.cause = error instanceof Error ? error : undefined;
  return out;
}

function pendingLocalActionStorageKeys() {
  const keys = [];
  for (let index = 0; index < localStorage.length; index += 1) {
    const key = String(localStorage.key(index) || '');
    if (key.startsWith(LOCAL_ACTION_PENDING_STORAGE_PREFIX)) keys.push(key);
  }
  return keys;
}

function persistPendingLocalActionRecord(actionId = '', entry = {}) {
  const record = normalizePendingLocalActionRecord({ action_id: actionId, ...entry });
  const key = record ? pendingLocalActionStorageKey(record.action_id) : '';
  if (!record || !key) throw localActionRecoveryStorageUnavailableError(new Error('本地操作恢复记录格式无效'));
  const serialized = JSON.stringify(record);
  if (serialized.length > LOCAL_ACTION_PENDING_RECORD_MAX_CHARS) {
    throw localActionRecoveryStorageUnavailableError(new Error('本地操作恢复记录过大'));
  }
  try {
    localStorage.setItem(key, serialized);
    if (localStorage.getItem(key) !== serialized) throw new Error('本地存储写入后校验失败');
    return record;
  } catch (error) {
    try { localStorage.removeItem(key); } catch {}
    throw localActionRecoveryStorageUnavailableError(error);
  }
}

function cleanupPendingLocalActionStorage(now = Date.now()) {
  const records = [];
  for (const key of pendingLocalActionStorageKeys()) {
    let record = null;
    try {
      record = normalizePendingLocalActionRecord(JSON.parse(localStorage.getItem(key) || 'null'), now);
    } catch {}
    if (!record || key !== pendingLocalActionStorageKey(record.action_id)) {
      const actionId = key.slice(LOCAL_ACTION_PENDING_STORAGE_PREFIX.length);
      LOCAL_ACTION_EXPECTED_TARGETS.delete(actionId);
      try { localStorage.removeItem(key); } catch {}
      continue;
    }
    records.push(record);
  }
  records.sort((left, right) => left.at - right.at);
  return records;
}

function pendingLocalWindowActionEntries(excludeActionId = '', now = Date.now()) {
  const excluded = String(excludeActionId || '').trim();
  return cleanupPendingLocalActionStorage(now).filter(record =>
    LOCAL_WINDOW_ACTION_KINDS.has(String(record?.kind || '').trim())
    && String(record?.action_id || '').trim() !== excluded
    && Number(now || 0) - Number(record?.at || 0) <= LOCAL_ACTION_RECOVERY_TIMEOUT_MS,
  );
}

function localWindowActionInFlight(excludeActionId = '', now = Date.now()) {
  try {
    return pendingLocalWindowActionEntries(excludeActionId, now).length > 0;
  } catch {
    return false;
  }
}

function localWindowActionConflictError() {
  const error = new Error('已有文件管理器操作正在等待最终确认；为避免重复打开或抢夺窗口焦点，请等当前操作完成后再试。最长约 38 秒，之后恢复记录仍会保留，但不会继续阻止你核对任务栏后重新点击。');
  error.status = 409;
  error.code = 'local_window_action_in_progress';
  error.userMessage = error.message;
  return error;
}

function pendingLocalActionCapacityError(count = LOCAL_ACTION_PENDING_STORAGE_LIMIT) {
  const currentCount = Math.max(LOCAL_ACTION_PENDING_STORAGE_LIMIT, Number(count || 0) || 0);
  const error = new Error(`已有 ${currentCount} 个本地操作等待确认，已暂停发送新操作，避免丢失恢复记录。请等待当前操作完成，或刷新页面恢复状态后重试。`);
  error.status = 429;
  error.code = 'local_action_recovery_capacity_reached';
  error.userMessage = error.message;
  return error;
}

function assertPendingLocalActionCapacity(actionId = '', records = [], { recordAlreadyPersisted = false } = {}) {
  const cleanId = String(actionId || '').trim();
  const validRecords = Array.isArray(records) ? records : [];
  const alreadyRecorded = !!cleanId && validRecords.some(record => record?.action_id === cleanId);
  const capacityReached = recordAlreadyPersisted
    ? validRecords.length > LOCAL_ACTION_PENDING_STORAGE_LIMIT
    : !alreadyRecorded && validRecords.length >= LOCAL_ACTION_PENDING_STORAGE_LIMIT;
  if (capacityReached) throw pendingLocalActionCapacityError(validRecords.length);
  return validRecords;
}

function restorePendingLocalActions() {
  const now = Date.now();
  try {
    const legacyRaw = localStorage.getItem(LOCAL_ACTION_PENDING_STORAGE_KEY)
      || sessionStorage.getItem(LOCAL_ACTION_PENDING_STORAGE_KEY);
    if (legacyRaw) {
      try {
        const legacyEntries = JSON.parse(legacyRaw);
        for (const item of Array.isArray(legacyEntries) ? legacyEntries : []) {
          const record = normalizePendingLocalActionRecord(item, now);
          if (!record) continue;
          persistPendingLocalActionRecord(record.action_id, record);
        }
      } catch {}
      try { localStorage.removeItem(LOCAL_ACTION_PENDING_STORAGE_KEY); } catch {}
      try { sessionStorage.removeItem(LOCAL_ACTION_PENDING_STORAGE_KEY); } catch {}
    }
  } catch {}
  try {
    for (const record of cleanupPendingLocalActionStorage(now)) {
      LOCAL_ACTION_EXPECTED_TARGETS.set(record.action_id, {
        kind: record.kind,
        target: record.target,
        at: record.at,
      });
    }
  } catch {}
}

function pendingLocalActionEntryStillCurrent(actionId = '', entry = null) {
  const cleanId = String(actionId || '').trim();
  const current = cleanId ? LOCAL_ACTION_EXPECTED_TARGETS.get(cleanId) : null;
  if (!current || !entry) return false;
  return String(current.kind || '').trim() === String(entry.kind || '').trim()
    && Number(current.at || 0) === Number(entry.at || 0);
}

function cancelScheduledPendingLocalActionRecovery(actionId = '') {
  const cleanId = String(actionId || '').trim();
  const timer = cleanId ? LOCAL_ACTION_RECOVERY_TIMERS.get(cleanId) : null;
  if (!timer) return false;
  clearTimeout(timer);
  LOCAL_ACTION_RECOVERY_TIMERS.delete(cleanId);
  return true;
}

function pendingLocalActionLabel(kind = '') {
  return ({
    reveal: '显示文件',
    open_output: '打开输出目录',
    save_render: '保存长图',
    export_preview: '保存 MD',
    history_rerender: '历史重渲染保存',
    history_copy_current_output: '复制旧 PNG',
    clipboard_copy: '复制图片',
    preview_clipboard_copy: '复制预览图片',
    text_clipboard_copy: '复制文本',
  })[String(kind || '').trim()] || '本地操作';
}

function showCrossTabLocalActionRecovery(entry = {}, recovered = null, recoveryState = '') {
  const label = pendingLocalActionLabel(entry.kind);
  if (recoveryState === 'verified') {
    showLocalActionNotice({
      title: `另一页面的${label}已确认`,
      message: `已从本地服务确认另一页面发起的${label}结果。`,
      tone: 'ok',
    });
    return;
  }
  if (recoveryState === 'committed_unverified') {
    showLocalActionNotice({
      title: `另一页面的${label}已提交`,
      message: `${label}已经提交，但系统未完成最终确认；请核对文件、历史记录或剪贴板后再决定是否重试。`,
      tone: 'warn',
    });
    return;
  }
  const failed = localActionRecoveryFailed(recovered);
  showLocalActionNotice({
    title: `另一页面的${label}${failed ? '状态未确认' : '仍在处理中'}`,
    message: failed
      ? localActionRecoveryUnconfirmedText(label, recovered)
      : `${label}尚未取得最终证据；恢复记录会继续保留，刷新页面后仍可再次核对。`,
    tone: 'warn',
  });
}

async function recoverPendingLocalActionEntry(actionId = '', entry = {}, { notify = false } = {}) {
  const cleanId = String(actionId || '').trim();
  if (!cleanId || !entry?.kind) return { skipped: true };
  cancelScheduledPendingLocalActionRecovery(cleanId);
  const outcome = await LOCAL_ACTION_RECOVERY_RUNNER.run(cleanId, async () => {
    const current = LOCAL_ACTION_EXPECTED_TARGETS.get(cleanId);
    const recovered = await recoverLocalActionAfterAbort(current.kind, cleanId, { expectedTarget: current.target });
    const recoveryState = classifyLocalActionRecovery(recovered);
    if (recoveryState === 'failed' && localActionRecoveryFailureIsTerminal(recovered)) {
      forgetPendingLocalAction(cleanId);
    }
    return { actionId: cleanId, entry: current, recovered, recoveryState };
  }, {
    shouldRun: () => pendingLocalActionEntryStillCurrent(cleanId, entry),
  });
  if (!outcome.ran) return { skipped: true, coordinated: outcome.coordinated };
  const result = outcome.value;
  if (notify) showCrossTabLocalActionRecovery(result.entry, result.recovered, result.recoveryState);
  return { ...result, skipped: false, coordinated: outcome.coordinated };
}

function schedulePendingLocalActionRecovery(actionId = '', entry = {}, { delayMs = LOCAL_ACTION_CROSS_TAB_RECOVERY_DELAY_MS } = {}) {
  const cleanId = String(actionId || '').trim();
  if (!_localActionRecoveryBootstrapReady || !pendingLocalActionEntryStillCurrent(cleanId, entry)) return false;
  if (LOCAL_ACTION_RECOVERY_TIMERS.has(cleanId) || LOCAL_ACTION_RECOVERY_RUNNER.has(cleanId)) return true;
  const timer = setTimeout(() => {
    LOCAL_ACTION_RECOVERY_TIMERS.delete(cleanId);
    if (LOCAL_ACTION_RECOVERY_RUNNER.has(cleanId)) return;
    void recoverPendingLocalActionEntry(cleanId, entry, { notify: true }).catch(error => {
      showLocalActionNotice({
        title: `另一页面的${pendingLocalActionLabel(entry.kind)}恢复未完成`,
        message: `核对另一页面操作时发生异常：${compactErrorSummary(error?.message || '未知错误')}；页面没有重放该操作。`,
        tone: 'warn',
      });
    });
  }, Math.max(0, Number(delayMs || 0) || 0));
  LOCAL_ACTION_RECOVERY_TIMERS.set(cleanId, timer);
  return true;
}

function scheduleAllPendingLocalActionRecoveries({ delayMs = LOCAL_ACTION_CROSS_TAB_RECOVERY_DELAY_MS } = {}) {
  for (const [actionId, entry] of LOCAL_ACTION_EXPECTED_TARGETS.entries()) {
    schedulePendingLocalActionRecovery(actionId, entry, { delayMs });
  }
}

function setupPendingLocalActionStorageSync() {
  window.addEventListener('storage', event => {
    const key = String(event?.key || '');
    if (key === INTERRUPTED_DIGEST_BATCH_STORAGE_KEY) {
      handleInterruptedDigestBatchStorageChange();
      return;
    }
    if (key === LOCAL_ACTION_PENDING_STORAGE_KEY) {
      restorePendingLocalActions();
      scheduleAllPendingLocalActionRecoveries();
      return;
    }
    if (!key.startsWith(LOCAL_ACTION_PENDING_STORAGE_PREFIX)) return;
    const actionId = key.slice(LOCAL_ACTION_PENDING_STORAGE_PREFIX.length);
    if (!event.newValue) {
      cancelScheduledPendingLocalActionRecovery(actionId);
      LOCAL_ACTION_EXPECTED_TARGETS.delete(actionId);
      return;
    }
    try {
      const record = normalizePendingLocalActionRecord(JSON.parse(event.newValue));
      if (!record || record.action_id !== actionId) return;
      const entry = { kind: record.kind, target: record.target, at: record.at };
      LOCAL_ACTION_EXPECTED_TARGETS.set(actionId, entry);
      schedulePendingLocalActionRecovery(actionId, entry);
    } catch {}
  });
}

function forgetPendingLocalAction(actionId = '') {
  const cleanId = String(actionId || '').trim();
  if (!cleanId) return;
  cancelScheduledPendingLocalActionRecovery(cleanId);
  LOCAL_ACTION_EXPECTED_TARGETS.delete(cleanId);
  const key = pendingLocalActionStorageKey(cleanId);
  if (!key) return;
  try {
    localStorage.removeItem(key);
  } catch {}
}

function completePendingLocalActionAfterResponse(actionId = '', response = null) {
  const cleanId = String(actionId || '').trim();
  const entry = cleanId ? LOCAL_ACTION_EXPECTED_TARGETS.get(cleanId) : null;
  const evidencePersisted = response?.evidence_persisted ?? response?.evidence?.evidence_persisted;
  if (!entry
    || response?.ok === false
    || evidencePersisted === false
    || String(response?.phase || response?.evidence?.browser_clipboard_phase || '').trim() === 'prepared'
    || ['reveal', 'open_output'].includes(String(entry.kind || '').trim())) return;
  forgetPendingLocalAction(cleanId);
}

function rememberLocalActionExpectedTargetFromRequestBody(path = '', body = {}) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) return;
  const actionId = String(body.local_action_id || body.action_id || '').trim();
  if (!actionId) return;
  const cleanPath = String(path || '').split('?')[0];
  const nestedDigest = body.digest && typeof body.digest === 'object' && !Array.isArray(body.digest) ? body.digest : {};
  const nestedHistory = body.history && typeof body.history === 'object' && !Array.isArray(body.history) ? body.history : {};
  const targetSource = { ...nestedDigest, ...nestedHistory, ...body };
  const targetInput = {
    digest_id: targetSource.digest_id || '',
    history_item_key: targetSource.history_item_key || '',
    relative_path: targetSource.relative_path || '',
    expected_file_version: targetSource.expected_file_version || targetSource.file_version || '',
    expected_digest_file_version: targetSource.expected_digest_file_version || targetSource.digest_file_version || '',
    output_dir_identity: targetSource.expected_output_dir_identity || targetSource.output_dir_identity || '',
    settings_revision: targetSource.expected_settings_revision || targetSource.settings_revision || '',
  };
  if (cleanPath === '/api/open-output') {
    targetInput.relative_path = '';
    targetInput.output_dir_identity = body.expected_output_dir_identity || '';
  }
  if (cleanPath === '/api/reveal-output') {
    targetInput.output_dir_identity = body.expected_output_dir_identity || '';
    targetInput.settings_revision = body.expected_settings_revision || body.settings_revision || '';
  }
  if (cleanPath === '/api/history-copy-current-output') {
    targetInput.output_dir_identity = body.expected_current_output_dir_identity || '';
  }
  const target = compactLocalActionExpectedTarget(targetInput);
  const kind = cleanPath === '/api/browser-clipboard-action'
    ? String(body.kind || '').trim()
    : localActionKindFromRequest(cleanPath, actionId);
  if (!LOCAL_ACTION_PENDING_KINDS.has(kind)) {
    const error = new Error('本地操作恢复记录缺少可识别的动作类型，操作尚未发送；请刷新页面后重试。');
    error.status = 500;
    error.code = 'local_action_recovery_binding_invalid';
    throw error;
  }
  if (LOCAL_WINDOW_ACTION_KINDS.has(kind)) {
    let pendingWindowActions;
    try {
      pendingWindowActions = pendingLocalWindowActionEntries(actionId);
    } catch (error) {
      throw localActionRecoveryStorageUnavailableError(error);
    }
    // Explorer 前台状态是全局资源，即使目标目录不同也不能并发抢焦点。
    if (pendingWindowActions.length) throw localWindowActionConflictError();
  }
  try {
    assertPendingLocalActionCapacity(actionId, cleanupPendingLocalActionStorage());
  } catch (error) {
    if (error?.code === 'local_action_recovery_capacity_reached') throw error;
    throw localActionRecoveryStorageUnavailableError(error);
  }
  const record = persistPendingLocalActionRecord(actionId, { kind, target, at: Date.now() });
  LOCAL_ACTION_EXPECTED_TARGETS.set(actionId, { kind: record.kind, target: record.target, at: record.at });
  try {
    assertPendingLocalActionCapacity(actionId, cleanupPendingLocalActionStorage(), { recordAlreadyPersisted: true });
    if (localStorage.getItem(pendingLocalActionStorageKey(actionId)) === null) {
      throw new Error('当前本地操作恢复记录在容量整理后丢失');
    }
  } catch (error) {
    LOCAL_ACTION_EXPECTED_TARGETS.delete(actionId);
    try { localStorage.removeItem(pendingLocalActionStorageKey(actionId)); } catch {}
    if (error?.code === 'local_action_recovery_capacity_reached') throw error;
    throw localActionRecoveryStorageUnavailableError(error);
  }
  return true;
}

function localActionExpectedTargetForKind(kind = '', value = null) {
  const compact = compactLocalActionExpectedTarget(value || {});
  if (String(kind || '').trim() === 'open_output') {
    return compactLocalActionExpectedTarget({ output_dir_identity: compact?.output_dir_identity || '' });
  }
  return compact;
}

function localActionExpectedTargetFor(actionId = '', explicitTarget = null, kind = '') {
  const cleanId = String(actionId || '').trim();
  const entry = cleanId ? LOCAL_ACTION_EXPECTED_TARGETS.get(cleanId) : null;
  const cleanKind = String(kind || entry?.kind || '').trim();
  const explicit = localActionExpectedTargetForKind(cleanKind, explicitTarget);
  if (explicit) return explicit;
  if (!entry) return null;
  if (Date.now() - Number(entry.at || 0) > LOCAL_ACTION_EXPECTED_TARGET_TTL_MS) {
    forgetPendingLocalAction(cleanId);
    return null;
  }
  return localActionExpectedTargetForKind(cleanKind, entry.target);
}

function localActionEvidenceQuery(kind = '', actionId = '', expectedTarget = null) {
  const params = new URLSearchParams({
    kind: String(kind || '').trim(),
    action_id: String(actionId || '').trim(),
  });
  const target = compactLocalActionExpectedTarget(expectedTarget || {});
  if (target) {
    for (const [key, value] of Object.entries(target)) {
      if (value) params.set(key, value);
    }
  }
  return `/api/local-action-evidence?${params.toString()}`;
}

function storedSessionToken() {
  try {
    return String(sessionStorage.getItem(SESSION_TOKEN_STORAGE_KEY) || '').trim();
  } catch {
    return '';
  }
}

function normalizeServiceInstanceId(value = '') {
  const id = String(value || '').trim();
  return /^[a-zA-Z0-9_-]{16,128}$/.test(id) ? id : '';
}

function storedServiceInstanceId() {
  try {
    return normalizeServiceInstanceId(sessionStorage.getItem(SERVICE_INSTANCE_STORAGE_KEY) || '');
  } catch {
    return '';
  }
}

function rememberServiceInstanceId(value = '') {
  const clean = normalizeServiceInstanceId(value);
  SERVICE_INSTANCE_ID = clean;
  try {
    if (clean) sessionStorage.setItem(SERVICE_INSTANCE_STORAGE_KEY, clean);
    else sessionStorage.removeItem(SERVICE_INSTANCE_STORAGE_KEY);
  } catch {}
  if (clean) {
    queueMicrotask(() => {
      const previewInstance = normalizeServiceInstanceId(_state_digest?.lastTextBatchServiceInstanceId || '');
      if (previewInstance && previewInstance !== clean) {
        markTextPreviewServerSnapshotUnavailable('本地服务已重启；当前文本仍可复制，但旧服务中的导出快照已经失效。请重新生成后再导出 MD。');
      }
    });
  }
  return clean;
}

function rememberSessionToken(token = '') {
  const clean = String(token || '').trim();
  TOKEN = clean;
  try {
    if (clean) sessionStorage.setItem(SESSION_TOKEN_STORAGE_KEY, clean);
    else sessionStorage.removeItem(SESSION_TOKEN_STORAGE_KEY);
  } catch {}
}

function clearSessionToken() {
  rememberSessionToken('');
  rememberServiceInstanceId('');
}

function storedBootstrapToken() {
  try {
    return String(sessionStorage.getItem(BOOTSTRAP_TOKEN_STORAGE_KEY) || '').trim();
  } catch {
    return '';
  }
}

function rememberBootstrapToken(token = '') {
  const clean = String(token || '').trim();
  try {
    if (clean) sessionStorage.setItem(BOOTSTRAP_TOKEN_STORAGE_KEY, clean);
    else sessionStorage.removeItem(BOOTSTRAP_TOKEN_STORAGE_KEY);
  } catch {}
}

function clearBootstrapToken() {
  rememberBootstrapToken('');
}

function bootstrapTokenFromLocation() {
  try {
    return String(new URL(location.href).searchParams.get('bootstrap') || '').trim();
  } catch {
    return '';
  }
}

function removeBootstrapTokenFromLocation() {
  try {
    const next = new URL(location.href);
    if (!next.searchParams.has('bootstrap')) return;
    next.searchParams.delete('bootstrap');
    history.replaceState(history.state, document.title, `${next.pathname}${next.search}${next.hash}`);
  } catch {}
}

function waitForPromiseWithSignal(promise, signal = null, fallback = '请求已取消') {
  if (!signal) return promise;
  if (signal.aborted) return Promise.reject(abortErrorForSignal(signal, fallback));
  return new Promise((resolve, reject) => {
    const onAbort = () => {
      cleanup();
      reject(abortErrorForSignal(signal, fallback));
    };
    const cleanup = () => signal.removeEventListener?.('abort', onAbort);
    signal.addEventListener?.('abort', onAbort, { once: true });
    promise.then(
      value => {
        cleanup();
        resolve(value);
      },
      error => {
        cleanup();
        reject(error);
      },
    );
  });
}

async function ensureSessionToken({ signal = null } = {}) {
  if (TOKEN) return TOKEN;
  const locationBootstrapToken = bootstrapTokenFromLocation();
  if (locationBootstrapToken) rememberBootstrapToken(locationBootstrapToken);
  const bootstrapToken = locationBootstrapToken || storedBootstrapToken();
  if (!locationBootstrapToken) {
    const stored = storedSessionToken();
    if (stored) {
      TOKEN = stored;
      SERVICE_INSTANCE_ID = storedServiceInstanceId() || SERVICE_INSTANCE_ID;
      return TOKEN;
    }
  }
  if (!_sessionBootstrapPromise) {
    _sessionBootstrapPromise = (async () => {
      const sessionPath = bootstrapToken ? `/api/session?bootstrap=${encodeURIComponent(bootstrapToken)}` : '/api/session';
      const bootstrapRequest = fetchSignalWithTimeout(null, SESSION_BOOTSTRAP_TIMEOUT_MS, '/api/session');
      try {
        const response = await fetch(sessionPath, {
          headers: ASSET_VERSION ? { 'X-WX-Asset-Version': ASSET_VERSION } : {},
          cache: 'no-store',
          signal: bootstrapRequest.signal,
        });
        if (!response.ok) {
          const text = await readResponseTextLimited(response, responseLimitOptions(
            '本地会话错误详情',
            API_ERROR_RESPONSE_MAX_BYTES,
            'session_error_response_too_large',
            bootstrapRequest.signal,
          ));
          const code = parseHttpErrorCode(text);
          clearSessionToken();
          if (code === 'invalid_bootstrap_token') {
            clearBootstrapToken();
            removeBootstrapTokenFromLocation();
          }
          throw reloadControlError('SESSION_BOOTSTRAP_FAILED', parseHttpErrorMessage(text, response.status) || '启动会话凭据无效，请从本地启动器重新打开页面。', response.status || 403);
        }
        let data;
        try {
          const text = await readResponseTextLimited(response, responseLimitOptions(
            '本地会话 JSON 响应',
            API_ERROR_RESPONSE_MAX_BYTES,
            'session_json_response_too_large',
            bootstrapRequest.signal,
          ));
          data = JSON.parse(text);
        } catch (e) {
          if (e?.code === 'session_json_response_too_large') throw e;
          throw reloadControlError('SESSION_BOOTSTRAP_FAILED', '本地服务返回的会话数据无法解析，请重启本地服务后再试。', 502);
        }
        const token = String(data?.token || '').trim();
        const serviceInstanceId = normalizeServiceInstanceId(data?.service_instance_id || '');
        if (!token || !serviceInstanceId) throw reloadControlError('SESSION_BOOTSTRAP_FAILED', '本地服务没有返回完整会话信息，请重启服务后再试。', 403);
        rememberSessionToken(token);
        rememberServiceInstanceId(serviceInstanceId);
        removeBootstrapTokenFromLocation();
        return TOKEN;
      } catch (error) {
        if (bootstrapRequest.timedOut()) {
          const timeoutError = bootstrapRequest.timeoutError() || apiTimeoutError('/api/session', SESSION_BOOTSTRAP_TIMEOUT_MS);
          timeoutError.code = 'session_bootstrap_timeout';
          timeoutError.message = '建立本地服务会话超过 10 秒，已停止等待。请确认本地服务仍在运行后重试。';
          throw timeoutError;
        }
        throw error;
      } finally {
        bootstrapRequest.done();
      }
    })().finally(() => {
      _sessionBootstrapPromise = null;
    });
  }
  return waitForPromiseWithSignal(_sessionBootstrapPromise, signal, '建立本地服务会话已取消');
}

async function renewSessionTokenAfterRejection(rejectedToken = '', { signal = null } = {}) {
  const rejected = String(rejectedToken || '').trim();
  if (!TOKEN || TOKEN === rejected) clearSessionToken();
  try {
    await ensureSessionToken({ signal });
    return !!TOKEN && TOKEN !== rejected;
  } catch (error) {
    if (signal?.aborted || error?.name === 'AbortError' || error?.status === 499) throw error;
    return false;
  }
}

function apiTimeoutError(path = '', timeoutMs = DEFAULT_API_TIMEOUT_MS) {
  const seconds = Math.max(1, Math.round((Number(timeoutMs || 0) || DEFAULT_API_TIMEOUT_MS) / 1000));
  const err = new Error(`本地服务请求超过 ${seconds} 秒没有返回：${path || 'API 请求'}。请稍后重试；如果仍失败，请查看最近日志或重启本地服务。`);
  err.name = 'TimeoutError';
  err.status = 504;
  err.code = 'api_timeout';
  return err;
}

function abortErrorForSignal(signal = null, fallback = '请求已取消') {
  if (signal?.reason instanceof Error) return signal.reason;
  const err = new Error(typeof signal?.reason === 'string' && signal.reason ? signal.reason : fallback);
  err.name = 'AbortError';
  return err;
}

function fetchSignalWithTimeout(signal = null, timeoutMs = DEFAULT_API_TIMEOUT_MS, path = '') {
  const timeout = Math.max(0, Number(timeoutMs || 0) || 0);
  if (!timeout) return { signal, done() {}, timedOut: () => false, timeoutError: () => null };
  const controller = new AbortController();
  let completed = false;
  let timedOut = false;
  let timeoutError = null;
  const abortFromSignal = () => {
    if (completed || controller.signal.aborted) return;
    controller.abort(abortErrorForSignal(signal));
  };
  const timer = setTimeout(() => {
    if (completed || controller.signal.aborted) return;
    timedOut = true;
    timeoutError = apiTimeoutError(path, timeout);
    controller.abort(timeoutError);
  }, timeout);
  signal?.addEventListener?.('abort', abortFromSignal, { once: true });
  if (signal?.aborted) abortFromSignal();
  return {
    signal: controller.signal,
    timedOut: () => timedOut,
    timeoutError: () => timeoutError,
    done() {
      completed = true;
      clearTimeout(timer);
      signal?.removeEventListener?.('abort', abortFromSignal);
    },
  };
}

function responsePayloadTooLargeError(label = '本地服务响应', maxBytes = API_ERROR_RESPONSE_MAX_BYTES, code = 'response_payload_too_large') {
  const error = new Error(`${label}超过安全读取上限 ${formatByteSize(maxBytes)}，页面已停止读取。`);
  error.status = 502;
  error.code = code;
  return error;
}

function responseLimitOptions(label, maxBytes, code, signal = null) {
  return {
    maxBytes,
    signal,
    errorFactory: () => responsePayloadTooLargeError(label, maxBytes, code),
  };
}

function apiMutationOutcomeUnknown({ mutation = false, requestStarted = false, outcomeConfirmed = false, error = null } = {}) {
  return mutation === true
    && requestStarted === true
    && outcomeConfirmed !== true
    && !!error
    && typeof error === 'object';
}

async function api(path, opts = {}) {
  assertFrontendAssetNotBlocked(path);
  const { onRequestStarted, timeoutMs = DEFAULT_API_TIMEOUT_MS, localActionBody: explicitLocalActionBody = null, ...fetchOpts } = opts;
  const requestSignal = fetchSignalWithTimeout(fetchOpts.signal, timeoutMs, path);
  const requestMethod = String(fetchOpts.method || 'GET').toUpperCase();
  const mutation = !['GET', 'HEAD'].includes(requestMethod);
  let requestStartedNotified = false;
  let mutationRequestStarted = false;
  let mutationOutcomeConfirmed = false;
  try {
    const method = requestMethod;
    const body = fetchOpts.body;
    const rawFetchBody = (typeof Blob !== 'undefined' && body instanceof Blob)
      || (typeof FormData !== 'undefined' && body instanceof FormData)
      || (typeof URLSearchParams !== 'undefined' && body instanceof URLSearchParams)
      || (typeof ArrayBuffer !== 'undefined' && (body instanceof ArrayBuffer || ArrayBuffer.isView(body)));
    const serializeJsonBody = !!body && typeof body !== 'string' && !rawFetchBody;
    const localActionBody = explicitLocalActionBody || (serializeJsonBody ? body : null);
    const localActionId = localActionBody && typeof localActionBody === 'object' && !Array.isArray(localActionBody)
      ? String(localActionBody.local_action_id || localActionBody.action_id || '').trim()
      : '';
    if (serializeJsonBody) {
      fetchOpts.body = JSON.stringify(fetchOpts.body);
    }
    let sessionRetryAvailable = true;
    while (true) {
      await ensureSessionToken({ signal: requestSignal.signal });
      const requestToken = TOKEN;
      const headers = { 'X-WX-Token': requestToken, ...(fetchOpts.headers || {}) };
      if (ASSET_VERSION) headers['X-WX-Asset-Version'] = ASSET_VERSION;
      if (serializeJsonBody) headers['Content-Type'] = 'application/json';
      if (localActionId) rememberLocalActionExpectedTargetFromRequestBody(path, localActionBody);
      mutationRequestStarted = false;
      mutationOutcomeConfirmed = false;
      const request = fetch(path, { ...fetchOpts, headers, signal: requestSignal.signal });
      mutationRequestStarted = mutation;
      if (!requestStartedNotified) {
        requestStartedNotified = true;
        try { onRequestStarted?.(); } catch {}
      }
      const r = await request;
      if (!r.ok) {
        const text = await readResponseTextLimited(r, responseLimitOptions(
          '本地服务错误详情',
          API_ERROR_RESPONSE_MAX_BYTES,
          'api_error_response_too_large',
          requestSignal.signal,
        ));
        mutationOutcomeConfirmed = true;
        const code = parseHttpErrorCode(text);
        if (isInvalidTokenResponse(r.status, code, text)) {
          forgetPendingLocalAction(localActionId);
          if (sessionRetryAvailable && await renewSessionTokenAfterRejection(requestToken, { signal: requestSignal.signal })) {
            sessionRetryAvailable = false;
            continue;
          }
          clearSessionToken();
          if (await guardedReload('重新载入本地服务会话')) {
            throw reloadControlError('SESSION_RELOAD_REQUIRED', '本地服务会话已失效，保存未提交；正在重新载入本地服务会话。', 403);
          }
          showAssetReloadNotice('', { reason: 'session_rejected' });
          throw reloadControlError('SESSION_RELOAD_CANCELLED', '本地服务会话已失效，保存未提交；请先处理未保存更改后刷新页面。', 403);
        }
        if (r.status === 409 && code === 'service_restart_required') {
          forgetPendingLocalAction(localActionId);
          _serviceRestartRequired = true;
          showAssetReloadNotice('', { reason: 'source_changed' });
          throw reloadControlError('SERVICE_RESTART_REQUIRED', '本地代码已更新，但当前服务仍在运行旧代码；请重启本地服务后刷新页面再操作。', 409);
        }
        if (r.status === 409 && code === 'stale_frontend_asset') {
          forgetPendingLocalAction(localActionId);
          markFrontendAssetReloadRequired();
          if (await guardedReload('重新载入最新本地页面')) {
            throw reloadControlError('STALE_FRONTEND_RELOAD_REQUIRED', '本地页面版本已更新，保存未提交；正在重新载入最新本地页面。', 409);
          }
          showAssetReloadNotice('', { reason: 'api_rejected' });
          throw reloadControlError('STALE_FRONTEND_RELOAD_CANCELLED', '本地页面版本已更新，保存未提交；请先处理未保存更改后刷新页面。', 409);
        }
        if (!['local_action_already_completed', 'local_action_in_progress', 'local_action_outcome_unknown', 'browser_clipboard_evidence_unavailable'].includes(code)) {
          forgetPendingLocalAction(localActionId);
        }
        const err = new Error(parseHttpErrorMessage(text, r.status));
        err.status = r.status;
        err.code = code;
        err.responseText = text;
        const attachedError = attachHttpErrorPayload(err, text);
        if (attachedError.local_action_capability_invalidated === true) {
          scheduleLocalActionCapabilityRefreshAfterFailure();
        }
        throw attachedError;
      }
      let data;
      try {
        const text = await readResponseTextLimited(r, responseLimitOptions(
          '本地服务 JSON 响应',
          API_JSON_RESPONSE_MAX_BYTES,
          'api_json_response_too_large',
          requestSignal.signal,
        ));
        data = JSON.parse(text);
      } catch (e) {
        if (e?.code === 'api_json_response_too_large') throw e;
        throw apiResponseJsonParseError(path, method, e);
      }
      validateKnownApiResponse(path, method, data);
      if (data?.local_action_capability_invalidated === true) {
        scheduleLocalActionCapabilityRefreshAfterFailure();
      }
      if (localActionId && !localActionResponseMatchesId(data, localActionId)) {
        throw localActionResponseMismatchError('本地操作');
      }
      mutationOutcomeConfirmed = true;
      rememberSettingsRevisionFromPayload(data);
      completePendingLocalActionAfterResponse(localActionId, data);
      if (data && typeof data === 'object' && await reloadIfAssetVersionChanged(data)) {
        throw reloadControlError('STALE_FRONTEND_RELOAD_AFTER_RESPONSE', '本地页面版本已更新；本次操作已收到本地服务响应，页面正在重新载入最新版本。', 409);
      }
      return data;
    }
  } catch (e) {
    const error = requestSignal.timedOut()
      ? (requestSignal.timeoutError() || apiTimeoutError(path, timeoutMs))
      : e;
    if (apiMutationOutcomeUnknown({
      mutation,
      requestStarted: mutationRequestStarted,
      outcomeConfirmed: mutationOutcomeConfirmed,
      error,
    })) {
      error.mutation_outcome_unknown = true;
    }
    throw error;
  } finally {
    requestSignal.done();
  }
}

function syncAppStateDependentControls(updateDetail = {}) {
  try {
    if (normalizeAppHash(location.hash || '#/digest') === '#/digest') {
      updateDigestPreviewActionLock();
      syncTextPreviewDownloadButton();
      syncTextPreviewRevealButton();
    }
  } catch {}
  try {
    window.dispatchEvent(new CustomEvent(APP_STATE_UPDATED_EVENT, { detail: { state: _appState, ...updateDetail } }));
  } catch {}
}

function currentAppStateAccountId() {
  return canonicalAccountIdForValue(selectedAccountId());
}

function appStateForCurrentAccount(accountId = selectedAccountId()) {
  if (!_appState) return null;
  const current = canonicalAccountIdForValue(accountId);
  const bound = canonicalAccountIdForValue(_appStateAccountId);
  if (!current && !bound) return _appState;
  return accountsReferToSameAccount(current, bound) ? _appState : null;
}

function invalidateAppStateForAccountChange() {
  _appState = null;
  _appStateAccountId = '';
  _lastAppStateRefreshFailure = null;
}

function beginAppStateRequest({ refresh = false, accountId = selectedAccountId() } = {}) {
  const seq = ++_appStateRequestSeq;
  if (refresh) _latestForcedAppStateRequestSeq = Math.max(_latestForcedAppStateRequestSeq, seq);
  return {
    seq,
    account_id: canonicalAccountIdForValue(accountId),
    account_switch_generation: _accountSwitchGeneration,
    account_data_generation: _accountDataGeneration,
  };
}

function appStateResponseMayApply(requestMeta = 0) {
  const meta = typeof requestMeta === 'object' && requestMeta ? requestMeta : { seq: requestMeta };
  const seq = Number(meta.seq || 0) || 0;
  if (seq && seq < _latestForcedAppStateRequestSeq) return false;
  if (seq && seq < _latestAppliedAppStateRequestSeq) return false;
  if (Number(meta.account_switch_generation || 0) !== _accountSwitchGeneration) return false;
  if (Number(meta.account_data_generation || 0) !== _accountDataGeneration) return false;
  const requestAccountId = String(meta.account_id || '').trim();
  const currentAccountId = currentAppStateAccountId();
  if (requestAccountId || currentAccountId) return accountsReferToSameAccount(requestAccountId, currentAccountId);
  return true;
}

function beginAccountListRequest({ force = false } = {}) {
  const seq = ++_accountListRequestSeq;
  if (force) _latestForcedAccountListRequestSeq = Math.max(_latestForcedAccountListRequestSeq, seq);
  return {
    seq,
    account_switch_generation: _accountSwitchGeneration,
    account_data_generation: _accountDataGeneration,
  };
}

function accountListResponseMayApply(requestMeta = {}) {
  const seq = Number(requestMeta?.seq || 0) || 0;
  if (seq && seq < _latestForcedAccountListRequestSeq) return false;
  if (seq && seq < _latestAppliedAccountListRequestSeq) return false;
  if (Number(requestMeta?.account_switch_generation || 0) !== _accountSwitchGeneration) return false;
  if (Number(requestMeta?.account_data_generation || 0) !== _accountDataGeneration) return false;
  return true;
}

function markAccountListResponseApplied(requestMeta = {}) {
  const seq = Number(requestMeta?.seq || 0) || 0;
  _latestAppliedAccountListRequestSeq = Math.max(_latestAppliedAccountListRequestSeq, seq);
}

function applyAccountsSnapshot(accounts = []) {
  if (!Array.isArray(accounts)) {
    throw invalidApiResponseError(
      '账号列表格式异常，已保留当前账号；请刷新页面或重启本地服务后重试。',
      'account_list_response_invalid',
    );
  }
  const previousAccounts = _appAccounts;
  const previousAccountsSignature = accountListIdentitySignature(previousAccounts);
  const previousAccountDataSignature = accountListDataSignature(previousAccounts);
  const nextAccounts = sortAccountsByFreshness(accounts || []);
  const accountsChanged = previousAccountsSignature !== accountListIdentitySignature(nextAccounts);
  const accountDataChanged = previousAccountDataSignature !== accountListDataSignature(nextAccounts);
  _appAccounts = nextAccounts;
  if (accountDataChanged) _accountDataGeneration++;
  return {
    accounts: nextAccounts,
    previousAccounts,
    previousAccountsSignature,
    accountsChanged,
    accountDataChanged,
    accountDataGeneration: _accountDataGeneration,
  };
}

function accountSelectionValueIfAvailable(value = '', accounts = _appAccounts) {
  const account = accountForSelectionValue(accounts, value);
  return account ? accountOptionValue(account) : '';
}

function confirmedAccountSelectionValue(accounts = _appAccounts) {
  const remembered = String(_confirmedAccountValue || readConfirmedAccountValue() || '').trim();
  return accountSelectionValueIfAvailable(remembered, accounts);
}

function stableAccountSelectionValue(select = null) {
  const pending = _pendingAccountSwitchIntent;
  if (pending && pending.intent_seq === _accountSwitchIntentSeq) {
    return accountSelectionValueIfAvailable(pending.confirmed_value);
  }
  const liveValue = String(select?.value || '').trim();
  if (liveValue) return accountSelectionValueIfAvailable(liveValue);
  if (select?.dataset.bound === '1') return '';
  return String(readConfirmedAccountValue() || '').trim();
}

async function fetchAppState({ refresh = false, signal = null } = {}) {
  for (let attempt = 0; attempt < 2; attempt += 1) {
    const requestAccountId = selectedAccountId();
    const requestMeta = beginAppStateRequest({ refresh, accountId: requestAccountId });
    const query = new URLSearchParams();
    if (refresh) query.set('refresh', 'true');
    if (requestAccountId) query.set('account', requestAccountId);
    const path = query.toString() ? `/api/state?${query.toString()}` : '/api/state';
    const state = await api(path, { signal });
    const applied = setAppState(state, { requestMeta });
    if (applied) return applied;
    if (signal?.aborted) throw signal.reason instanceof Error ? signal.reason : Object.assign(new Error('本地状态读取已取消。'), { name: 'AbortError', status: 499 });
  }
  throw Object.assign(new Error('读取本地状态期间微信账号连续变化，请按当前右上角账号重试。'), {
    name: 'AbortError',
    status: 499,
    code: 'app_state_superseded',
  });
}

function setAppState(state, { sync = true, requestSeq = 0, requestMeta = null } = {}) {
  let updateDetail = {};
  if (state && typeof state === 'object') {
    const meta = requestMeta || requestSeq;
    if (!appStateResponseMayApply(meta)) return null;
    const seq = Number((typeof meta === 'object' && meta ? meta.seq : meta) || 0) || 0;
    const requestAccountId = String(typeof meta === 'object' && meta ? meta.account_id || '' : '').trim();
    const previousOutputDirIdentity = outputDirIdentityFromPayload(_appState);
    const nextOutputDirIdentity = outputDirIdentityFromPayload(state);
    const previousExportPolicyRevision = exportPolicyRevisionFromPayload(_appState);
    const nextExportPolicyRevision = exportPolicyRevisionFromPayload(state);
    updateDetail = {
      previous_output_dir_identity: previousOutputDirIdentity,
      output_dir_identity: nextOutputDirIdentity,
      output_dir_identity_changed: !!previousOutputDirIdentity
        && !!nextOutputDirIdentity
        && previousOutputDirIdentity !== nextOutputDirIdentity,
      previous_export_policy_revision: previousExportPolicyRevision,
      export_policy_revision: nextExportPolicyRevision,
      export_policy_revision_changed: !!previousExportPolicyRevision
        && !!nextExportPolicyRevision
        && previousExportPolicyRevision !== nextExportPolicyRevision,
    };
    _latestAppliedAppStateRequestSeq = Math.max(_latestAppliedAppStateRequestSeq, seq);
    const deferAccountListSync = appStateAccountListSyncDeferred();
    if (!deferAccountListSync) syncAccountsFromAppState(state);
    _appState = deferAccountListSync && Array.isArray(state?.wechat?.accounts)
      ? {
        ...state,
        wechat: {
          ...state.wechat,
          accounts: _appAccounts.map(account => ({ ...account })),
        },
      }
      : state;
    _appStateAccountId = canonicalAccountIdForValue(requestAccountId) || currentAppStateAccountId();
    if (!appStateForCurrentAccount()) {
      invalidateAppStateForAccountChange();
      return null;
    }
    _lastAppStateRefreshFailure = null;
  }
  if (sync) queueMicrotask(() => syncAppStateDependentControls(updateDetail));
  return _appState;
}

function appStateAccountListSyncDeferred() {
  return globalSettingsWriteBusy() || globalSettingsValidationBusy();
}

function accountSelectionNeedsStableContextForStateSync() {
  const route = normalizeAppHash(location.hash || '#/digest');
  return route === '#/settings'
    || route === '#/setup'
    || !!document.querySelector('.page-settings')
    || !!document.getElementById('setup-body');
}

function accountFingerprintContextChanged(previous = '', next = '') {
  const previousFingerprint = String(previous || '').trim().toLowerCase();
  const nextFingerprint = String(next || '').trim().toLowerCase();
  return !!(previousFingerprint || nextFingerprint) && previousFingerprint !== nextFingerprint;
}

function syncAccountsFromAppState(state = {}) {
  if (!Array.isArray(state?.wechat?.accounts)) return false;
  const sel = document.getElementById('account-switcher');
  const previousAccounts = _appAccounts;
  const previousGroupCacheAccounts = digestGroupCacheAccountsSignature(previousAccounts);
  const previousValue = stableAccountSelectionValue(sel);
  const previousAliases = accountAliasesForValue(previousValue, previousAccounts);
  const previousAccountFingerprint = accountFingerprintForValue(previousValue, previousAccounts);
  const { accounts, accountsChanged } = applyAccountsSnapshot(state.wechat.accounts);
  const groupCacheAccountsChanged = previousGroupCacheAccounts !== digestGroupCacheAccountsSignature(accounts);
  const stableSelectionContext = accountSelectionNeedsStableContextForStateSync();
  if (!sel) {
    if (accountsChanged) {
      if (groupCacheAccountsChanged) clearDigestGroupCache('微信账号缓存上下文已变化');
      dispatchAccountListUpdated({ accounts, previousValue: '', selectedValue: '', selectionChanged: false, selectionLost: false, accountsChanged, source: 'state' });
    }
    return accountsChanged;
  }
  const preserveEmptySelection = sel.dataset.bound === '1' && !previousValue;
  sel.innerHTML = renderAccountOptions(accounts, previousValue, { previousAliases, preserveMissingSelection: true, preserveEmptySelection });
  restoreAccountSelection(sel, accounts, previousValue, { previousAliases, preserveMissingSelection: true, preserveEmptySelection });
  const selectedValue = sel.value || '';
  const previousAccount = accountForSelectionValue(accounts, previousValue, { previousAliases });
  const previousStale = previousAccount ? accountStaleInfoForAccount(previousAccount, accounts) : null;
  const staleAutoSwitchSuppressed = stableSelectionContext
    && !!previousStale
    && !staleAccountConfirmed(previousStale);
  const selectionLost = !!previousValue && !selectedValue;
  const selectionChanged = !!previousValue && !!selectedValue && previousValue !== selectedValue;
  const selectedAccountFingerprint = accountFingerprintForValue(selectedValue, accounts);
  const accountContextChanged = !!previousValue
    && !!selectedValue
    && !selectionChanged
    && accountFingerprintContextChanged(previousAccountFingerprint, selectedAccountFingerprint);
  if (previousValue && (selectionLost || selectionChanged || accountContextChanged)) resetDigestAccountState();
  if (groupCacheAccountsChanged) clearDigestGroupCache('微信账号缓存上下文已变化');
  _confirmedAccountValue = selectedValue;
  sel.disabled = !accounts.length;
  delete sel.dataset.accountError;
  sel.title = '';
  syncAccountSwitcherDigestLock();
  if (sel.dataset.bound !== '1') {
    sel.addEventListener('change', handleAccountSwitch);
    sel.dataset.bound = '1';
  }
  if (accountsChanged || selectionLost || selectionChanged || accountContextChanged || staleAutoSwitchSuppressed) {
    dispatchAccountListUpdated({ accounts, previousValue, selectedValue, selectionChanged, selectionLost, accountsChanged, accountContextChanged, staleAutoSwitchSuppressed, source: 'state' });
  }
  return accountsChanged || selectionLost || selectionChanged || accountContextChanged || staleAutoSwitchSuppressed;
}

function syncAppStateFromSettingsSave(result = {}, { account_id = null } = {}) {
  const currentRevision = String(_appState?.settings_revision || '').trim();
  const responseRevision = settingsRevisionFromPayload(result);
  const baseRevision = String(result?.base_settings_revision || '').trim();
  const staleLateResponse = result?.superseded !== true
    && currentRevision
    && baseRevision
    && currentRevision !== baseRevision
    && currentRevision !== responseRevision;
  if (staleLateResponse) return false;
  if (result?.settings) rememberSettingsRevisionFromPayload(result);
  if (!result?.settings) return false;
  const accountId = account_id === null ? selectedAccountId() : String(account_id || '').trim();
  const accountScopedResponse = !!accountId;
  if (!_appState) {
    void refreshAppStateSilently();
    return false;
  }
  // Global settings saves intentionally omit an account; their key/setup flags cannot describe the selected account.
  const stateAccountId = accountScopedResponse ? accountId : selectedAccountId();
  const requestMeta = beginAppStateRequest({ refresh: true, accountId: stateAccountId });
  const nextWechat = { ...(_appState.wechat || {}) };
  if (result.settings.wechat && typeof result.settings.wechat === 'object') {
    const manualKeyAnyConfigured = Math.max(0, Number(result.settings.wechat.manual_key_account_count || 0) || 0) > 0;
    const legacyManualKeyConfigured = manualKeyLegacyUnscoped(result.settings.wechat);
    nextWechat.manual_key_any_configured = manualKeyAnyConfigured;
    nextWechat.manual_key_legacy_configured = legacyManualKeyConfigured;
    nextWechat.manual_key_legacy_candidate_available = legacyManualKeyConfigured;
  }
  if (accountScopedResponse && result.settings.wechat && typeof result.settings.wechat === 'object') {
    const responseManualKeyState = settingsResponseManualKeyAccountState(result, accountId);
    const manualKeyConfigured = responseManualKeyState?.has_configured
      ? responseManualKeyState.configured
      : manualKeySavedForAccount(result.settings.wechat, accountId);
    const legacyManualKeyConfigured = manualKeyLegacyUnscoped(result.settings.wechat);
    const manualKeyVerified = responseManualKeyState?.has_verified
      ? responseManualKeyState.verified
      : manualKeyVerifiedForAccount(result.settings.wechat, accountId);
    nextWechat.manual_key_configured = manualKeyConfigured;
    nextWechat.manual_key_verified = manualKeyVerified;
    const autoState = String(nextWechat.key_auto_scan_state || '').trim();
    const autoCanAttempt = nextWechat.key_auto_scan_can_attempt === true
      || nextWechat.key_auto_scan_can_try === true;
    const autoConfigurationSatisfied = autoCanAttempt
      || nextWechat.key_auto_scan_verified_for_account === true
      || nextWechat.key_auto_scan_supported === true
      || autoState === 'unknown';
    const responseSaysManualKeyRequired = result.need_setup_reason === 'wechat_manual_key_required';
    const responseSaysAutoKeyRecoveryRequired = result.need_setup_reason === 'wechat_auto_key_scan_failed';
    const responseSaysSetupComplete = Object.hasOwn(result, 'need_setup') && result.need_setup === false;
    nextWechat.manual_key_required = responseSaysManualKeyRequired
      ? true
      : (responseSaysSetupComplete ? false : (!autoConfigurationSatisfied && !manualKeyVerified && !legacyManualKeyConfigured));
    nextWechat.key_setup_recovery_required = responseSaysAutoKeyRecoveryRequired
      || (!responseSaysSetupComplete && nextWechat.key_setup_recovery_required === true);
  }
  if (_state_digest && result.settings && typeof result.settings === 'object') {
    _state_digest.settings = result.settings;
  }
  setAppState({
    ..._appState,
    wechat: nextWechat,
    settings_revision: settingsRevisionFromPayload(result) || _appState.settings_revision || '',
    scheduler_runtime_revision: schedulerRuntimeRevisionFromPayload(result) || _appState.scheduler_runtime_revision || '',
    export_policy_revision: exportPolicyRevisionFromPayload(result) || _appState.export_policy_revision || '',
    output_dir_identity: outputDirIdentityFromPayload(result) || _appState.output_dir_identity || '',
    settings_invalid: result.settings._settings_invalid || null,
    secrets_invalid: result.settings._secrets_invalid,
    secrets_invalid_info: result.settings._secrets_invalid_info || null,
    need_setup: accountScopedResponse && Object.hasOwn(result, 'need_setup') ? result.need_setup : _appState.need_setup,
    need_setup_reason: accountScopedResponse && Object.hasOwn(result, 'need_setup_reason') ? (result.need_setup_reason || '') : (_appState.need_setup_reason || ''),
  }, { requestMeta });
  if (!accountScopedResponse) void refreshAppStateSilently();
  return true;
}

function rememberAppStateRefreshFailure(error = null) {
  _lastAppStateRefreshFailure = {
    at: Date.now(),
    message: compactErrorSummary(error?.message || String(error || '本地状态刷新失败')),
  };
}

function recentAppStateRefreshFailureText() {
  const failure = _lastAppStateRefreshFailure;
  if (!failure || Date.now() - Number(failure.at || 0) > APP_STATE_REFRESH_FAILURE_VISIBLE_MS) return '';
  return failure.message || '本地状态刷新失败';
}

function visibleAppStateRefreshWarning(signal = null, { target = '页面状态' } = {}) {
  if (signal?.aborted) return '';
  const detail = recentAppStateRefreshFailureText();
  return detail
    ? `；${target}刷新失败：${detail}，请刷新页面后核对最新状态`
    : `；${target}刷新失败，请刷新页面后核对最新状态`;
}

async function refreshAppStateForVisibleAction({ refresh = false, signal = null, target = '页面状态' } = {}) {
  const nextState = await refreshAppStateSilently({ refresh, signal });
  if (nextState || signal?.aborted) return '';
  return visibleAppStateRefreshWarning(signal, { target });
}

async function ensureFreshDigestFrontend({ signal = null } = {}) {
  try {
    const state = await fetchAppState({ signal });
    const serverVersion = String(state?.asset_version || '').trim();
    const sourceVersion = String(state?.source_asset_version || '').trim();
    if (serverVersion && sourceVersion && sourceVersion !== serverVersion) {
      _serviceRestartRequired = true;
      _activeSourceAssetVersion = sourceVersion;
      showAssetReloadNotice(sourceVersion, { reason: 'source_changed', runningVersion: serverVersion });
      _state_digest.frontendAssetStaleMessage = '本地代码已更新，但当前服务仍在运行旧代码；请先重启本地服务，再刷新页面后生成。';
      return {
        ok: false,
        reason: 'source_asset_changed',
        message: '本地代码已更新，但当前服务仍在运行旧代码；请先重启本地服务，再刷新页面后生成。',
        serverVersion,
        sourceVersion,
      };
    }
    if (!ASSET_VERSION || !serverVersion || serverVersion === ASSET_VERSION) {
      _serviceRestartRequired = false;
      _activeSourceAssetVersion = '';
      clearFrontendAssetReloadRequired();
      _state_digest.frontendAssetStaleMessage = '';
      return { ok: true };
    }
    markFrontendAssetReloadRequired(serverVersion);
    showAssetReloadNotice(serverVersion, { reason: 'digest_preflight' });
    _state_digest.frontendAssetStaleMessage = '本地页面版本已更新，请刷新页面后再生成。';
    return {
      ok: false,
      reason: 'stale_frontend',
      message: '本地页面版本已更新，请刷新页面后再生成；这不是数据库、本地数据或 key 错误。',
      serverVersion,
    };
  } catch (e) {
    if (e?.name === 'AbortError') throw e;
    const reloadMessage = reloadRequiredErrorMessage(e);
    if (reloadMessage) {
      _state_digest.frontendAssetStaleMessage = reloadMessage;
      return {
        ok: false,
        reason: String(e?.code || '').startsWith('STALE_FRONTEND_') ? 'stale_frontend' : 'session_reload',
        message: reloadMessage,
      };
    }
    const detail = compactErrorSummary(e?.message || String(e || '本地状态检查失败'));
    const code = String(e?.code || '').trim();
    const status = Number(e?.status || 0) || 0;
    return {
      ok: false,
      reason: 'state_error',
      code,
      status,
      message: detail
        ? `本地状态检查失败：${detail}。请刷新页面，或确认本地服务仍在运行。`
        : '本地状态检查失败；请刷新页面，或确认本地服务仍在运行。',
    };
  }
}

async function checkFrontendAssetFreshness({ force = false, signal = null } = {}) {
  if (!ASSET_VERSION) return true;
  const now = Date.now();
  if (!force && now - _lastFrontendAssetFreshnessCheckAt < FRONTEND_ASSET_FRESHNESS_CHECK_MS) return true;
  if (_frontendAssetFreshnessCheckPromise) return _frontendAssetFreshnessCheckPromise;
  _lastFrontendAssetFreshnessCheckAt = now;
  const request = fetchAppState({ signal })
    .then(() => !frontendAssetBusinessRequestsBlocked())
    .catch(e => {
      if (e?.name === 'AbortError') return false;
      if (reloadRequiredErrorMessage(e)) return false;
      return false;
    })
    .finally(() => {
      if (_frontendAssetFreshnessCheckPromise === request) _frontendAssetFreshnessCheckPromise = null;
    });
  _frontendAssetFreshnessCheckPromise = request;
  return request;
}

function setupFrontendAssetFreshnessWatchers() {
  if (!ASSET_VERSION) return;
  let timer = null;
  const schedule = ({ force = false } = {}) => {
    if (document.visibilityState === 'hidden') return;
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      void checkFrontendAssetFreshness({ force });
    }, 120);
  };
  window.addEventListener('focus', () => schedule());
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') schedule({ force: true });
  });
  const pollingTimer = setInterval(() => {
    if (document.visibilityState === 'visible') void checkFrontendAssetFreshness();
  }, FRONTEND_ASSET_FRESHNESS_CHECK_MS);
  window.addEventListener('beforeunload', () => clearInterval(pollingTimer), { once: true });
}

async function withAuthResponse(path, opts = {}, consumeResponse = null) {
  assertFrontendAssetNotBlocked(path);
  if (typeof consumeResponse !== 'function') throw new TypeError('withAuthResponse 需要响应消费回调');
  const { timeoutMs = DEFAULT_API_TIMEOUT_MS, ...fetchOpts } = opts;
  const requestSignal = fetchSignalWithTimeout(fetchOpts.signal, timeoutMs, path);
  try {
    let sessionRetryAvailable = true;
    while (true) {
      await ensureSessionToken({ signal: requestSignal.signal });
      const requestToken = TOKEN;
      const headers = { 'X-WX-Token': requestToken, ...(fetchOpts.headers || {}) };
      if (ASSET_VERSION) headers['X-WX-Asset-Version'] = ASSET_VERSION;
      const r = await fetch(path, { ...fetchOpts, headers, signal: requestSignal.signal });
      if (!r.ok) {
        const text = await readResponseTextLimited(r, responseLimitOptions(
          '本地文件接口错误详情',
          API_ERROR_RESPONSE_MAX_BYTES,
          'auth_error_response_too_large',
          requestSignal.signal,
        ));
        const code = parseHttpErrorCode(text);
        if (isInvalidTokenResponse(r.status, code, text)) {
          if (sessionRetryAvailable && await renewSessionTokenAfterRejection(requestToken, { signal: requestSignal.signal })) {
            sessionRetryAvailable = false;
            continue;
          }
          clearSessionToken();
          if (await guardedReload('重新载入本地服务会话')) {
            throw reloadControlError('SESSION_RELOAD_REQUIRED', '本地服务会话已失效；正在重新载入本地服务会话。', 403);
          }
          showAssetReloadNotice('', { reason: 'session_rejected' });
          throw reloadControlError('SESSION_RELOAD_CANCELLED', '本地服务会话已失效；请先处理未保存更改后刷新页面。', 403);
        }
        if (r.status === 409 && code === 'service_restart_required') {
          _serviceRestartRequired = true;
          showAssetReloadNotice('', { reason: 'source_changed' });
          throw reloadControlError('SERVICE_RESTART_REQUIRED', '本地代码已更新，但当前服务仍在运行旧代码；请重启本地服务后刷新页面再操作。', 409);
        }
        if (r.status === 409 && code === 'stale_frontend_asset') {
          markFrontendAssetReloadRequired();
          if (await guardedReload('重新载入最新本地页面')) {
            throw reloadControlError('STALE_FRONTEND_RELOAD_REQUIRED', '本地页面版本已更新；正在重新载入最新本地页面。', 409);
          }
          showAssetReloadNotice('', { reason: 'auth_fetch_rejected' });
          throw reloadControlError('STALE_FRONTEND_RELOAD_CANCELLED', '本地页面版本已更新；请先处理未保存更改后刷新页面。', 409);
        }
        const error = new Error(parseHttpErrorMessage(text, r.status));
        error.status = r.status;
        error.code = code;
        error.responseText = text;
        error.retryAfterMs = httpRetryAfterMs(r.headers.get('Retry-After'));
        throw attachHttpErrorPayload(error, text);
      }
      try {
        return await consumeResponse(r, requestSignal.signal);
      } finally {
        await cancelResponseBody(r);
      }
    }
  } catch (e) {
    if (requestSignal.timedOut()) throw requestSignal.timeoutError() || apiTimeoutError(path, timeoutMs);
    throw e;
  } finally {
    requestSignal.done();
  }
}

async function postCommitApi(path, opts = {}, { actionLabel = '本地操作' } = {}) {
  try {
    return await api(path, opts);
  } catch (e) {
    if (e?.name === 'AbortError' || e?.status === 499) throw e;
    const reloadMessage = reloadRequiredErrorMessage(e);
    if (reloadMessage) {
      return {
        ok: false,
        status: Number(e?.status || 0) || 0,
        code: String(e?.code || '').trim(),
        error: reloadMessage,
        post_commit_reload_required: true,
        post_commit_action: actionLabel,
      };
    }
    return {
      ok: false,
      status: Number(e?.status || 0) || 0,
      code: String(e?.code || '').trim(),
      error: compactErrorSummary(e?.message || String(e || `${actionLabel}失败`)) || `${actionLabel}失败`,
    };
  }
}

function trackObjectUrl(url) {
  if (url) _trackedObjectUrls.add(url);
  return url;
}

function revokeObjectUrl(url) {
  if (!url) return;
  _trackedObjectUrls.delete(url);
  try { URL.revokeObjectURL(url); } catch {}
}

function revokeTrackedObjectUrls() {
  for (const url of [..._trackedObjectUrls]) revokeObjectUrl(url);
}

// ---------- 主题 ----------
function normalizeAppThemePreference(value = '') {
  return ['auto', 'light', 'dark'].includes(value) ? value : 'auto';
}

function readStoredAppTheme() {
  try {
    return normalizeAppThemePreference(localStorage.getItem(APP_THEME_STORAGE_KEY) || document.documentElement.dataset.theme || 'auto');
  } catch {
    return normalizeAppThemePreference(document.documentElement.dataset.theme || 'auto');
  }
}

function setAppThemePreference(theme = 'auto') {
  const next = normalizeAppThemePreference(theme);
  document.documentElement.dataset.theme = next;
  try {
    localStorage.setItem(APP_THEME_STORAGE_KEY, next);
  } catch {}
  return next;
}

function appThemeMediaQuery() {
  if (typeof window.matchMedia !== 'function') return null;
  try {
    return window.matchMedia('(prefers-color-scheme: dark)');
  } catch {
    return null;
  }
}

const APP_THEME_MEDIA_QUERY = appThemeMediaQuery();

function effectiveAppTheme() {
  const selected = normalizeAppThemePreference(document.documentElement.dataset.theme || readStoredAppTheme());
  if (selected === 'dark' || selected === 'light') return selected;
  const media = APP_THEME_MEDIA_QUERY;
  return media?.matches === true ? 'dark' : 'light';
}

function paintThemeToggle() {
  const btn = document.getElementById('theme-toggle');
  if (!btn) return;
  const dark = effectiveAppTheme() === 'dark';
  btn.textContent = dark ? '🌙' : '☀';
  btn.setAttribute('aria-label', dark ? '切换到浅色主题' : '切换到深色主题');
  btn.title = dark ? '切换到浅色主题' : '切换到深色主题';
}

function applyAppTheme() {
  const isDark = effectiveAppTheme() === 'dark';
  const changed = document.body.classList.contains('is-dark') !== isDark;
  document.body.classList.toggle('is-dark', isDark);
  paintThemeToggle();
  if (changed) {
    queueMicrotask(() => {
      try {
        window.dispatchEvent(new CustomEvent(APP_THEME_CHANGED_EVENT, { detail: { theme: isDark ? 'dark' : 'light' } }));
      } catch {}
    });
  }
}

function bindAppThemeSystemListener(media = APP_THEME_MEDIA_QUERY) {
  if (!media) return;
  try {
    if (typeof media.addEventListener === 'function') {
      media.addEventListener('change', applyAppTheme);
    } else if (typeof media.addListener === 'function') {
      media.addListener(applyAppTheme);
    }
  } catch {}
}
setAppThemePreference(readStoredAppTheme());
bindAppThemeSystemListener();
applyAppTheme();

document.getElementById('theme-toggle')?.addEventListener('click', () => {
  setAppThemePreference(effectiveAppTheme() === 'dark' ? 'light' : 'dark');
  applyAppTheme();
});

function normalizeAppHash(value = location.hash || '#/digest') {
  const raw = String(value || '#/digest');
  const hash = raw.startsWith('#') ? raw : `#${raw}`;
  let path = hash.replace(/^#/, '').split('?')[0] || '/digest';
  if (path && !path.startsWith('/')) path = `/${path}`;
  return `#${path}`;
}

function hashFromUrl(value = '') {
  try {
    return normalizeAppHash(new URL(value).hash || '#/digest');
  } catch {
    return normalizeAppHash(value || '#/digest');
  }
}

function routeHistoryIndexFromState(state = null) {
  if (!state || typeof state !== 'object') return NaN;
  const value = Number(state[ROUTE_HISTORY_INDEX_STATE_KEY]);
  return Number.isFinite(value) ? value : NaN;
}

function routeHistoryStateWithIndex(index = _routeHistoryIndex) {
  const base = history.state && typeof history.state === 'object' ? { ...history.state } : {};
  base[ROUTE_HISTORY_INDEX_STATE_KEY] = Number.isFinite(Number(index)) ? Number(index) : 0;
  return base;
}

function replaceRouteHistoryState(hash = location.hash || '#/digest', index = _routeHistoryIndex) {
  try {
    history.replaceState(
      routeHistoryStateWithIndex(index),
      '',
      `${location.pathname}${location.search}${normalizeAppHash(hash)}`,
    );
    return true;
  } catch {
    return false;
  }
}

function routeHistoryRepairFallback(token, previousHash, previousIndex) {
  window.setTimeout(() => {
    if (!_routeHistoryRepair || _routeHistoryRepair.token !== token) return;
    _routeHistoryRepair = null;
    replaceRouteHistoryState(previousHash, previousIndex);
  }, 500);
}

function restoreRejectedRouteNavigation(previousHash = '#/digest', { historyDelta = 0 } = {}) {
  const previous = normalizeAppHash(previousHash || _currentRouteHash || '#/digest');
  const previousIndex = _routeHistoryIndex;
  const delta = Number(historyDelta);
  if (Number.isFinite(delta) && delta !== 0) {
    const token = Symbol('route-history-repair');
    _routeHistoryRepair = { token, expectedHash: previous, expectedIndex: previousIndex };
    try {
      history.go(-delta);
      routeHistoryRepairFallback(token, previous, previousIndex);
      return;
    } catch {
      _routeHistoryRepair = null;
    }
  }
  replaceRouteHistoryState(previous, previousIndex);
}

function setActiveDirtyProvider(provider = null) {
  _activeDirtyProvider = typeof provider === 'function' ? provider : null;
}

function clearActiveDirtyProvider(provider = null) {
  if (!provider || _activeDirtyProvider === provider) _activeDirtyProvider = null;
}

function dispatchGlobalSettingsPendingWorkChanged() {
  window.dispatchEvent(new CustomEvent(SETTINGS_PENDING_WORK_EVENT, { detail: { ..._globalSettingsPendingWork } }));
}

function beginGlobalSettingsPendingWork(kind = 'settings_save') {
  const key = Object.hasOwn(_globalSettingsPendingWork, kind) ? kind : 'settings_save';
  _globalSettingsPendingWork[key] += 1;
  dispatchGlobalSettingsPendingWorkChanged();
  let done = false;
  return () => {
    if (done) return;
    done = true;
    _globalSettingsPendingWork[key] = Math.max(0, _globalSettingsPendingWork[key] - 1);
    dispatchGlobalSettingsPendingWorkChanged();
  };
}

function globalSettingsWriteBusy() {
  return _globalSettingsPendingWork.settings_save > 0
    || _globalSettingsPendingWork.settings_reconcile > 0
    || _globalSettingsPendingWork.settings_unknown_reconcile > 0
    || _globalSettingsPendingWork.setup_save > 0
    || _globalSettingsPendingWork.setup_reconcile > 0;
}

function globalSettingsSchedulerMutationBusy() {
  return _globalSettingsPendingWork.scheduler_mutation > 0;
}

function globalSettingsSchedulerRunBusy() {
  return _globalSettingsPendingWork.scheduler_run > 0;
}

function globalSettingsValidationBusy() {
  return _globalSettingsPendingWork.settings_validation > 0;
}

function globalSettingsWriteReconcileBusy() {
  return _globalSettingsPendingWork.settings_reconcile > 0
    || _globalSettingsPendingWork.settings_unknown_reconcile > 0
    || _globalSettingsPendingWork.setup_reconcile > 0;
}

function globalSettingsWriteBusyMessage(context = 'settings') {
  if (globalSettingsWriteReconcileBusy()) {
    return context === 'setup'
      ? '设置已写入，正在刷新账号和本机状态，请等待复核完成后再操作。'
      : '设置已写入，正在刷新账号和本机状态，请等复核完成后再保存。';
  }
  return context === 'setup'
    ? '设置页或首次设置向导已有保存请求仍在进行中，请等待完成后再操作。'
    : '另一个设置页或首次设置向导保存请求正在进行，请等它完成后再保存。';
}

function settingsCrossTabWriteBusyError() {
  return Object.assign(new Error('另一个浏览器标签页正在保存设置；请等它完成并刷新当前页面后再保存。'), {
    status: 409,
    code: 'settings_cross_tab_write_in_progress',
    public_code: 'settings_cross_tab_write_in_progress',
  });
}

async function runCrossTabSettingsWrite(action) {
  const outcome = await SETTINGS_WRITE_RUNNER.run('mutation', action, { ifAvailable: true });
  if (outcome?.busy === true) throw settingsCrossTabWriteBusyError();
  if (outcome?.ran !== true) throw settingsCrossTabWriteBusyError();
  return outcome.value;
}

function globalSettingsPendingWorkState() {
  const total = Object.values(_globalSettingsPendingWork).reduce((sum, value) => sum + Math.max(0, Number(value || 0) || 0), 0);
  if (!total) return { dirty: false, message: '', onDiscard: null };
  const reconciling = _globalSettingsPendingWork.settings_reconcile > 0
    || _globalSettingsPendingWork.settings_unknown_reconcile > 0
    || _globalSettingsPendingWork.setup_reconcile > 0;
  const settingsWriting = _globalSettingsPendingWork.settings_save > 0 || _globalSettingsPendingWork.setup_save > 0 || reconciling;
  const settingsValidating = globalSettingsValidationBusy()
    && !settingsWriting;
  const schedulerMutating = globalSettingsSchedulerMutationBusy();
  const schedulerRunning = _globalSettingsPendingWork.scheduler_run > 0
    && !_globalSettingsPendingWork.settings_save
    && !_globalSettingsPendingWork.setup_save
    && !reconciling
    && !schedulerMutating;
  if (settingsValidating) {
    return {
      dirty: true,
      message: '手动密钥验证请求仍在进行中；确认离开或刷新会取消当前页面请求，但验证记录或旧版密钥迁移可能已经写入本机设置，请重新进入设置页核对。确定继续吗？',
      title: '密钥验证仍在进行',
      confirmText: '继续离开',
      onDiscard: null,
    };
  }
  if (!settingsWriting && schedulerMutating) {
    return {
      dirty: true,
      message: '清理旧游标请求仍在进行中；确认离开或刷新会取消当前页面请求，清理可能已部分提交，请重新进入设置页核对调度状态。确定继续吗？',
      title: '清理旧游标仍在进行',
      confirmText: '继续离开',
      onDiscard: null,
    };
  }
  if (schedulerRunning) {
    return {
      dirty: true,
      message: '手动检查请求仍在进行中；确认离开或刷新会取消当前页面请求，如果服务端已经写入部分结果，请重新进入设置页核对调度状态。确定继续吗？',
      title: '本地请求仍在进行',
      confirmText: '继续离开',
      onDiscard: null,
    };
  }
  return {
    dirty: true,
    message: reconciling
      ? '设置已写入，正在刷新账号和本机状态；请等复核完成后再离开、刷新或切换账号。'
      : '设置保存请求仍在进行中；请等保存完成后再离开、刷新或切换账号，避免把后台写入结果和当前页面状态拆开。',
    title: reconciling ? '设置已写入，正在复核' : '设置保存仍在进行',
    confirmText: '知道了',
    blocking: true,
    onDiscard: null,
  };
}

function registerRouteCleanup(handler) {
  if (typeof handler !== 'function') return () => {};
  _routeCleanupHandlers.add(handler);
  return () => _routeCleanupHandlers.delete(handler);
}

function runRouteCleanups(reason = 'route_change') {
  for (const handler of [..._routeCleanupHandlers]) {
    _routeCleanupHandlers.delete(handler);
    try { handler(reason); } catch {}
  }
}

function currentDirtyState() {
  const globalPending = globalSettingsPendingWorkState();
  if (typeof _activeDirtyProvider !== 'function') return globalPending;
  try {
    const result = _activeDirtyProvider();
    if (result === true) return { dirty: true, message: '', onDiscard: null };
    if (!result) return globalPending;
    const local = {
      dirty: !!result.dirty,
      message: String(result.message || ''),
      title: String(result.title || ''),
      confirmText: String(result.confirmText || ''),
      blocking: result.blocking === true,
      onDiscard: typeof result.onDiscard === 'function' ? result.onDiscard : null,
    };
    if (local.dirty) return local;
    return globalPending;
  } catch {
    return globalPending;
  }
}

function hasUnsavedChanges() {
  return !!currentDirtyState().dirty;
}

function hasActiveDigestGeneration() {
  return (!!_state_digest?.generating && !!_state_digest?.abortController)
    || (_digestBatchRecoveryPending && !!_digestBatchRecoveryAbortController && !_digestBatchRecoveryAbortController.signal.aborted);
}

function textPreviewExportPending() {
  return !!_state_digest?.textExportInFlight;
}

function activeDigestReloadMessage(action = '离开页面') {
  if (!_state_digest?.generating && _digestBatchRecoveryPending) {
    return `正在确认刷新前的摘要任务已安全收尾。${action}不会释放旧批次；切换页面后会继续后台确认，刷新后会从恢复记录继续。确认前不能开始新批次。确定继续吗？`;
  }
  if (digestBatchSettlementPending()) {
    return `本批结果已经生成，正在确认本地服务任务全部退出。${action}不会释放旧批次；切换页面后会继续后台确认，刷新后会从恢复记录继续。确认前不能开始新批次。确定继续吗？`;
  }
  const current = _state_digest?.progress ? digestProgressCurrentState(_state_digest.progress) : null;
  const detail = current?.text
    ? current.text.replace(/^(正在|最近完成|失败|已取消)：/, '')
    : '正在生成摘要';
  const commitStage = !!_state_digest?.stopAfterCurrentSave || digestProgressCommitSensitiveStage() === 'saving';
  if (commitStage) {
    return `${detail}。当前 PNG 正在保存，${action}会停止后续群，但不能撤回已经开始的 PNG 和历史记录写入；当前保存仍可能完成。确定继续吗？`;
  }
  return `${detail}。${action}会中断正在生成的长图/文本预览；已保存到历史的结果会保留，未完成的群会停止。确定继续吗？`;
}

async function confirmActiveDigestReload(action = '离开页面') {
  if (!hasActiveDigestGeneration()) return true;
  const recovering = !_state_digest?.generating && _digestBatchRecoveryPending;
  const settling = digestBatchSettlementPending();
  const commitStage = !!_state_digest?.stopAfterCurrentSave || digestProgressCommitSensitiveStage() === 'saving';
  return showAppConfirmDialog({
    title: recovering ? '正在确认刷新前任务' : (settling ? '正在确认本批收尾' : '当前生成仍在进行'),
    messages: [activeDigestReloadMessage(action)],
    confirmText: recovering || settling ? '继续并转后台确认' : (commitStage ? '继续离开，停止后续' : '继续并停止生成'),
    cancelText: '留在当前页面',
    tone: 'warn',
  });
}

function abortActiveDigestForRouteCleanup(reason = '已离开总结页，生成已取消') {
  const controller = _state_digest?.abortController;
  if (!_state_digest?.generating || !controller || controller.signal?.aborted) return false;
  return cancelDigestGeneration(reason);
}

async function confirmDiscardDirtyChanges(action = '离开当前页面') {
  if (_dirtyConfirmFlight) return _dirtyConfirmFlight;
  const state = currentDirtyState();
  if (!state.dirty) return true;
  const flight = (async () => {
    const message = state.message || `当前页面有未保存更改，${action}会丢失这些更改。确定继续吗？`;
    if (state.blocking) {
      await showAppConfirmDialog({
        title: state.title || '请求仍在进行',
        messages: [message],
        confirmText: state.confirmText || '知道了',
        cancelText: '',
        tone: 'warn',
        hideCancel: true,
      });
      return false;
    }
    const confirmed = await showAppConfirmDialog({
      title: state.title || '有未保存更改',
      messages: [message],
      confirmText: state.confirmText || '放弃更改',
      cancelText: '继续编辑',
      tone: 'warn',
    });
    if (confirmed) {
      try { state.onDiscard?.(); } catch {}
    }
    return confirmed;
  })();
  _dirtyConfirmFlight = flight;
  try {
    return await flight;
  } finally {
    if (_dirtyConfirmFlight === flight) _dirtyConfirmFlight = null;
  }
}

async function guardedReload(action = '刷新页面', { delay = 0 } = {}) {
  if (!await confirmDiscardDirtyChanges(action)) return false;
  if (!await confirmActiveDigestReload(action)) return false;
  if (hasActiveDigestGeneration()) cancelDigestGeneration(action);
  clearActiveDirtyProvider();
  if (delay > 0) setTimeout(() => location.reload(), delay);
  else location.reload();
  return true;
}

async function navigateTo(hash, { bypassDirty = false, routeIfSame = false } = {}) {
  const nextHash = canonicalRouteHash(hash);
  const currentRawHash = location.hash;
  const currentHash = canonicalRouteHash(currentRawHash || '#/digest');
  if (currentHash === nextHash && !routeIfSame) {
    if (!currentRawHash || currentRawHash !== nextHash) replaceRouteHistoryState(nextHash, _routeHistoryIndex);
    return true;
  }
  const routeIntentSeq = ++_routeIntentSeq;
  const routeIntentStillCurrent = () => routeIntentSeq === _routeIntentSeq;
  const routeWillCleanup = currentHash !== nextHash || routeIfSame;
  let preconfirmedDirty = false;
  if (!bypassDirty && routeWillCleanup && hasUnsavedChanges()) {
    const confirmed = await confirmDiscardDirtyChanges('切换页面');
    if (!routeIntentStillCurrent()) return false;
    if (!confirmed) return false;
    preconfirmedDirty = true;
  }
  if (!bypassDirty && routeWillCleanup && hasActiveDigestGeneration()) {
    const confirmed = await confirmActiveDigestReload('切换页面');
    if (!routeIntentStillCurrent()) return false;
    if (!confirmed) return false;
    cancelDigestGeneration('切换页面');
    preconfirmedDirty = true;
  }
  if (!routeIntentStillCurrent()) return false;
  if (bypassDirty || preconfirmedDirty) _pendingDirtyBypassHash = nextHash;
  if (currentHash === nextHash) {
    if (!currentRawHash || currentRawHash !== nextHash) {
      replaceRouteHistoryState(nextHash, _routeHistoryIndex);
      return true;
    }
    if (routeIfSame) await route({ bypassDirty: bypassDirty || _pendingDirtyBypassHash === nextHash, intentSeq: routeIntentSeq });
    return true;
  }
  _pendingRouteHistoryIndex = _routeHistoryIndex + 1;
  _pendingRouteIntent = { hash: nextHash, seq: routeIntentSeq };
  location.hash = nextHash;
  return true;
}

const SETTINGS_SECTION_KEYS = Object.freeze(['ai', 'scheduler', 'render', 'privacy', 'acceptance', 'about']);
const SETTINGS_SECTION_ACTIVATED_EVENT = 'wx-summary:settings-section-activated';

function normalizeSettingsSectionKey(section = '') {
  const key = String(section || '').trim();
  return SETTINGS_SECTION_KEYS.includes(key) ? key : 'ai';
}

function settingsSectionElement(section = '') {
  const key = String(section || '').trim();
  if (!key) return document.querySelector('.page-settings');
  return [...document.querySelectorAll('[data-settings-section]')]
    .find(el => String(el.dataset.settingsSection || '') === key) || null;
}

function settingsSectionTabElement(section = '') {
  const key = String(section || '').trim();
  return [...document.querySelectorAll('[data-settings-tab]')]
    .find(el => String(el.dataset.settingsTab || '') === key) || null;
}

function settingsSectionIsActive(section = '') {
  const key = normalizeSettingsSectionKey(section);
  const panel = settingsSectionElement(key);
  return _activeSettingsSection === key && !!panel && panel.hidden !== true;
}

function settingsSectionLabel(section = '') {
  const tab = settingsSectionTabElement(normalizeSettingsSectionKey(section));
  return tab?.dataset?.settingsLabel || String(tab?.textContent || '').trim() || '对应设置';
}

function scrollSettingsTabIntoView(tab, { behavior = preferredScrollBehavior() } = {}) {
  const container = tab?.closest?.('.settings-section-tabs');
  if (!container) return;
  const containerRect = container.getBoundingClientRect();
  const tabRect = tab.getBoundingClientRect();
  const inset = 8;
  let delta = 0;
  if (tabRect.left < containerRect.left + inset) delta = tabRect.left - containerRect.left - inset;
  else if (tabRect.right > containerRect.right - inset) delta = tabRect.right - containerRect.right + inset;
  if (!delta) return;
  container.scrollTo({ left: container.scrollLeft + delta, behavior });
}

function syncSettingsSectionDirtyIndicator(section = '', dirty = false) {
  const tab = settingsSectionTabElement(section);
  if (!tab) return;
  const label = tab.dataset.settingsLabel || String(tab.textContent || '').trim();
  if (!tab.dataset.settingsLabel) tab.dataset.settingsLabel = label;
  tab.dataset.dirty = dirty ? '1' : '0';
  tab.setAttribute('aria-label', dirty ? `${label}，有未保存更改` : label);
}

function activateSettingsSection(section = '', { focusTab = false, scrollPanel = false } = {}) {
  const page = document.querySelector('.page-settings');
  if (!page) return false;
  const key = normalizeSettingsSectionKey(section || _activeSettingsSection);
  const panel = settingsSectionElement(key);
  const tab = settingsSectionTabElement(key);
  if (!panel || !tab) return false;
  _activeSettingsSection = key;
  for (const item of page.querySelectorAll('[data-settings-section]')) {
    item.hidden = String(item.dataset.settingsSection || '') !== key;
  }
  for (const item of page.querySelectorAll('[data-settings-tab]')) {
    const selected = String(item.dataset.settingsTab || '') === key;
    item.setAttribute('aria-selected', selected ? 'true' : 'false');
    item.tabIndex = selected ? 0 : -1;
  }
  if (focusTab) {
    try { tab.focus({ preventScroll: true }); } catch { tab.focus?.(); }
  }
  scrollSettingsTabIntoView(tab, { behavior: focusTab || scrollPanel ? preferredScrollBehavior() : 'auto' });
  if (scrollPanel) {
    try { panel.scrollIntoView({ behavior: preferredScrollBehavior(), block: 'start' }); } catch {}
  }
  window.dispatchEvent(new CustomEvent(SETTINGS_SECTION_ACTIVATED_EVENT, { detail: { section: key } }));
  return true;
}

function bindSettingsSectionNavigation() {
  const tabs = [...document.querySelectorAll('[data-settings-tab]')];
  if (!tabs.length) return;
  for (const tab of tabs) {
    syncSettingsSectionDirtyIndicator(tab.dataset.settingsTab, false);
    tab.addEventListener('click', () => {
      activateSettingsSection(tab.dataset.settingsTab, { scrollPanel: true });
    });
    tab.addEventListener('keydown', event => {
      if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
      event.preventDefault();
      const index = tabs.indexOf(tab);
      const nextIndex = event.key === 'Home'
        ? 0
        : event.key === 'End'
          ? tabs.length - 1
          : (index + (event.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length;
      activateSettingsSection(tabs[nextIndex].dataset.settingsTab, { focusTab: true, scrollPanel: true });
    });
  }
  activateSettingsSection(_activeSettingsSection);
}

function visibleElement(el) {
  return !!el
    && el.offsetParent !== null
    && el.disabled !== true
    && el.getAttribute?.('aria-disabled') !== 'true'
    && !el.closest?.('[inert]');
}

function focusSettingsSection(section = '', { focusSelector = '' } = {}) {
  const requestedSection = String(section || '').trim();
  if (requestedSection) activateSettingsSection(requestedSection);
  const card = requestedSection
    ? settingsSectionElement(normalizeSettingsSectionKey(requestedSection))
    : document.querySelector('.page-settings');
  if (!card) return false;
  const fallbackTarget = card.querySelector('h3') || card;
  const target = focusSelector
    ? ([...card.querySelectorAll(focusSelector)].find(visibleElement) || fallbackTarget)
    : fallbackTarget;
  card.scrollIntoView({ behavior: preferredScrollBehavior(), block: 'start' });
  card.classList.add('setting-card-focus');
  window.setTimeout(() => card.classList.remove('setting-card-focus'), 1800);
  const focusTarget = target || card;
  const naturallyFocusable = /^(A|BUTTON|INPUT|SELECT|TEXTAREA)$/i.test(focusTarget.tagName || '')
    || focusTarget.hasAttribute?.('tabindex');
  if (!naturallyFocusable) focusTarget.setAttribute?.('tabindex', '-1');
  try {
    focusTarget.focus?.({ preventScroll: true });
  } catch {
    try { focusTarget.focus?.(); } catch {}
  }
  if (document.activeElement !== focusTarget && focusTarget !== fallbackTarget) {
    const fallbackFocusable = /^(A|BUTTON|INPUT|SELECT|TEXTAREA)$/i.test(fallbackTarget.tagName || '')
      || fallbackTarget.hasAttribute?.('tabindex');
    if (!fallbackFocusable) fallbackTarget.setAttribute?.('tabindex', '-1');
    try {
      fallbackTarget.focus?.({ preventScroll: true });
    } catch {
      try { fallbackTarget.focus?.(); } catch {}
    }
    return document.activeElement === fallbackTarget;
  }
  return document.activeElement === focusTarget;
}

async function openSettingsSection(section = '', { focusSelector = '' } = {}) {
  const settingsHash = '#/settings';
  const currentHash = normalizeAppHash(location.hash || '#/digest');
  const alreadySettings = currentHash === settingsHash && !!document.querySelector('.page-settings');
  if (!alreadySettings) {
    const intent = {
      section: String(section || '').trim(),
      focusSelector: String(focusSelector || '').trim(),
      route_intent_seq: _routeIntentSeq + 1,
    };
    _pendingSettingsSectionFocus = intent;
    const ok = await navigateTo(settingsHash, { routeIfSame: true });
    if (!ok) {
      if (_pendingSettingsSectionFocus === intent) _pendingSettingsSectionFocus = null;
      return false;
    }
    return true;
  }
  return focusSettingsSection(section, { focusSelector });
}

window.addEventListener('beforeunload', e => {
  if (!hasUnsavedChanges() && !hasActiveDigestGeneration() && !textPreviewExportPending() && !_state_digest?.rerenderSaving && _historyRerenderSavingCount <= 0 && !digestDraftPersistenceRisk()) return;
  e.preventDefault();
  e.returnValue = '';
});

window.addEventListener('pagehide', event => {
  if (event.persisted === true) return;
  preserveInterruptedDigestBatchForUnload();
});

window.addEventListener('pageshow', event => {
  if (event.persisted !== true) return;
  syncDigestGenerateButtons();
  void refreshAppStateSilently().catch(() => {});
});

// ---------- 路由 ----------
const routes = {
  '/digest': renderDigest,
  '/history': renderHistory,
  '/settings': renderSettings,
  '/setup': renderSetup,
};

function canonicalRouteHash(value = location.hash || '#/digest') {
  const normalized = normalizeAppHash(value);
  const path = normalized.replace(/^#/, '') || '/digest';
  return Object.hasOwn(routes, path) ? normalized : '#/digest';
}

const APP_DOCUMENT_TITLE = '微信消息总结';
const ROUTE_DOCUMENT_TITLES = {
  '#/digest': '总结',
  '#/history': '历史摘要',
  '#/settings': '设置',
  '#/setup': '初始设置',
};

function setRouteDocumentTitle(targetHash = '#/digest', prefix = '') {
  const cleanPrefix = String(prefix || ROUTE_DOCUMENT_TITLES[normalizeAppHash(targetHash)] || '总结').trim();
  const baseTitle = cleanPrefix ? `${cleanPrefix} - ${APP_DOCUMENT_TITLE}` : APP_DOCUMENT_TITLE;
  document.title = _launchFocusTitleActive
    ? `${baseTitle} · wx-focus-${LAUNCH_FOCUS_TOKEN}`
    : baseTitle;
}

if (LAUNCH_FOCUS_TOKEN) {
  window.setTimeout(() => {
    _launchFocusTitleActive = false;
    try {
      const next = new URL(location.href);
      next.searchParams.delete('focus');
      history.replaceState(history.state, document.title, `${next.pathname}${next.search}${next.hash}`);
    } catch {}
    setRouteDocumentTitle(canonicalRouteHash(location.hash || '#/digest'));
  }, LAUNCH_FOCUS_TITLE_TTL_MS);
}

function resetRouteScrollPosition() {
  const roots = [document.scrollingElement, document.documentElement, document.body, document.querySelector('main')];
  for (const root of roots) {
    if (!root) continue;
    root.scrollTop = 0;
    root.scrollLeft = 0;
  }
  try { window.scrollTo({ top: 0, left: 0, behavior: 'auto' }); } catch {}
}

function currentPageScrollY() {
  const roots = [document.scrollingElement, document.documentElement, document.body, document.querySelector('main')];
  return Math.max(0, ...roots.map(root => Math.max(0, Number(root?.scrollTop || 0) || 0)), Number(window.scrollY || 0) || 0);
}

function restorePageScrollY(value = 0) {
  const top = Math.max(0, Number(value || 0) || 0);
  const roots = [document.scrollingElement, document.documentElement, document.body, document.querySelector('main')];
  for (const root of roots) {
    if (!root) continue;
    root.scrollTop = top;
  }
  try { window.scrollTo({ top, left: 0, behavior: 'auto' }); } catch {}
}

async function route({ bypassDirty = false, previousHash = '', historyDelta = 0, intentSeq = 0 } = {}) {
  const routeIntentSeq = Number.isInteger(intentSeq) && intentSeq > 0 ? intentSeq : ++_routeIntentSeq;
  if (routeIntentSeq !== _routeIntentSeq) return false;
  const targetHash = canonicalRouteHash(location.hash || '#/digest');
  if (targetHash !== '#/settings') _pendingSettingsSectionFocus = null;
  if (targetHash !== '#/history') _pendingHistoryFocus = null;
  const routeIntentStillCurrent = () => routeIntentSeq === _routeIntentSeq
    && canonicalRouteHash(location.hash || '#/digest') === targetHash;
  const pendingHistoryIndex = _pendingRouteHistoryIndex;
  _pendingRouteHistoryIndex = null;
  const stateHistoryIndex = routeHistoryIndexFromState(history.state);
  const targetHistoryIndex = Number.isFinite(pendingHistoryIndex)
    ? pendingHistoryIndex
    : (Number.isFinite(stateHistoryIndex) ? stateHistoryIndex : _routeHistoryIndex);
  if (location.hash && location.hash !== targetHash) {
    replaceRouteHistoryState(targetHash, targetHistoryIndex);
  }
  const previous = _currentRouteHash || (previousHash ? normalizeAppHash(previousHash) : '#/digest');
  const hasBypass = bypassDirty || _pendingDirtyBypassHash === targetHash;
  if (_pendingDirtyBypassHash === targetHash) _pendingDirtyBypassHash = '';
  if (!hasBypass && targetHash !== _currentRouteHash) {
    const confirmed = await confirmDiscardDirtyChanges('切换页面');
    if (!routeIntentStillCurrent()) return false;
    if (!confirmed) {
      restoreRejectedRouteNavigation(previous, { historyDelta });
      return false;
    }
  }
  if (!hasBypass && targetHash !== _currentRouteHash && hasActiveDigestGeneration()) {
    const confirmed = await confirmActiveDigestReload('切换页面');
    if (!routeIntentStillCurrent()) return false;
    if (!confirmed) {
      restoreRejectedRouteNavigation(previous, { historyDelta });
      return false;
    }
    cancelDigestGeneration('切换页面');
  }
  if (!routeIntentStillCurrent()) return false;
  if (!closeTransientOverlays()) {
    restoreRejectedRouteNavigation(previous, { historyDelta });
    return false;
  }
  runRouteCleanups('route_change');
  clearActiveDirtyProvider();
  _currentRouteHash = targetHash;
  _routeHistoryIndex = targetHistoryIndex;
  replaceRouteHistoryState(targetHash, _routeHistoryIndex);
  const routeSeq = ++_routeSeq;
  const rawHash = targetHash.replace(/^#/, '') || '/digest';
  const hash = rawHash.split('?')[0] || '/digest';
  const fn = routes[hash] || renderDigest;
  revokeHistoryObjectUrls($app);
  // 设置导航 active
  document.querySelectorAll('.nav a').forEach(a => {
    const active = a.getAttribute('href') === '#' + hash;
    a.classList.toggle('active', active);
    if (active) a.setAttribute('aria-current', 'page');
    else a.removeAttribute('aria-current');
  });
  $app.innerHTML = '';
  resetRouteScrollPosition();
  setRouteDocumentTitle(targetHash);
  let routeFocusApplied = false;
  const applyDefaultRouteFocus = () => {
    if (routeFocusApplied || routeSeq !== _routeSeq || !routeIntentStillCurrent()) return false;
    if (targetHash === '#/history' && _historyRouteFocusRestorePending) return false;
    const focusClaimedByRenderedPage = document.activeElement
      && document.activeElement !== document.body
      && $app.contains(document.activeElement);
    if (focusClaimedByRenderedPage) return false;
    routeFocusApplied = focusRouteHeading();
    return routeFocusApplied;
  };
  try {
    const renderPromise = fn();
    const hasDeferredSettingsFocus = targetHash === '#/settings' && !!_pendingSettingsSectionFocus;
    if (!hasDeferredSettingsFocus) requestAnimationFrame(applyDefaultRouteFocus);
    await renderPromise;
    if (routeSeq === _routeSeq && routeIntentStillCurrent()) {
      let focusedByIntent = false;
      if (targetHash === '#/settings'
        && _pendingSettingsSectionFocus
        && Number(_pendingSettingsSectionFocus.route_intent_seq || 0) === routeIntentSeq) {
        const intent = _pendingSettingsSectionFocus;
        _pendingSettingsSectionFocus = null;
        focusedByIntent = focusSettingsSection(intent.section, { focusSelector: intent.focusSelector });
      } else if (targetHash === '#/settings' && _pendingSettingsSectionFocus) {
        _pendingSettingsSectionFocus = null;
      }
      const focusClaimedByRenderedPage = document.activeElement
        && document.activeElement !== document.body
        && $app.contains(document.activeElement);
      if (!focusedByIntent && !focusClaimedByRenderedPage) {
        // Async pages can replace a focused loading heading with their final DOM.
        routeFocusApplied = false;
        applyDefaultRouteFocus();
      }
    }
  } catch (e) {
    if (targetHash === '#/settings' && routeIntentStillCurrent()) _pendingSettingsSectionFocus = null;
    if (targetHash === '#/history' && routeIntentStillCurrent()) _historyRouteFocusRestorePending = false;
    if (routeSeq === _routeSeq && routeIntentStillCurrent()) {
      runRouteCleanups('route_render_error');
      renderRouteError(e);
    }
  }
  return routeIntentStillCurrent();
}

function focusRouteHeading() {
  const target = $app.querySelector('#digest-page-title')
    || $app.querySelector('h1, h2, #setup-title, .page-head h2');
  if (!target) return false;
  target.classList.add('route-focus-target');
  target.setAttribute('tabindex', '-1');
  target.focus?.({ preventScroll: true });
  return document.activeElement === target;
}

const modalPageScrollLocks = new Set();
const modalLayerStack = [];
const modalIsolationSnapshots = new Map();

function restoreModalIsolationElement(element, snapshot) {
  if (!element || !snapshot) return;
  element.inert = snapshot.inert;
  if (snapshot.ariaHidden === null) element.removeAttribute('aria-hidden');
  else element.setAttribute('aria-hidden', snapshot.ariaHidden);
}

function setModalIsolationElement(element, isolated) {
  if (!element) return;
  let snapshot = modalIsolationSnapshots.get(element);
  if (!snapshot) {
    snapshot = { inert: element.inert === true, ariaHidden: element.getAttribute('aria-hidden') };
    modalIsolationSnapshots.set(element, snapshot);
  }
  if (isolated) {
    element.inert = true;
    element.setAttribute('aria-hidden', 'true');
  } else {
    restoreModalIsolationElement(element, snapshot);
  }
}

function syncModalLayerIsolation() {
  for (let i = modalLayerStack.length - 1; i >= 0; i -= 1) {
    if (!modalLayerStack[i]?.isConnected) modalLayerStack.splice(i, 1);
  }
  const top = modalLayerStack.at(-1) || null;
  if (!top) {
    for (const [element, snapshot] of modalIsolationSnapshots) restoreModalIsolationElement(element, snapshot);
    modalIsolationSnapshots.clear();
    return;
  }
  for (const child of [...document.body.children]) setModalIsolationElement(child, child !== top);
}

function assetReloadNoticeHost() {
  const activeModal = modalLayerStack.at(-1);
  const modalSurface = activeModal?.isConnected
    ? activeModal.querySelector('.image-modal')
    : null;
  return modalSurface || document.body;
}

function syncAssetReloadNotice() {
  const notice = document.getElementById('asset-reload-notice');
  if (!notice) return null;
  const snapshot = modalIsolationSnapshots.get(notice);
  if (snapshot) {
    restoreModalIsolationElement(notice, snapshot);
    modalIsolationSnapshots.delete(notice);
  }
  const host = assetReloadNoticeHost();
  const inline = host !== document.body;
  notice.classList.toggle('asset-reload-notice-inline', inline);
  if (notice.parentElement !== host) host.appendChild(notice);
  if (inline) {
    const head = host.querySelector('.modal-head');
    if (head && notice.previousElementSibling !== head) head.after(notice);
  }
  return notice;
}

function registerModalLayer(modal) {
  if (!modal) return () => {};
  modalLayerStack.push(modal);
  syncModalLayerIsolation();
  syncFloatingNoticeStack();
  syncAssetReloadNotice();
  let released = false;
  return () => {
    if (released) return;
    released = true;
    const index = modalLayerStack.lastIndexOf(modal);
    if (index >= 0) modalLayerStack.splice(index, 1);
    syncModalLayerIsolation();
    syncFloatingNoticeStack();
    syncAssetReloadNotice();
  };
}

new MutationObserver(() => {
  if (modalLayerStack.length) syncModalLayerIsolation();
}).observe(document.body, { childList: true });

function syncModalPageScrollLock() {
  const locked = modalPageScrollLocks.size > 0;
  document.documentElement.classList.toggle('modal-open', locked);
  document.body.classList.toggle('modal-open', locked);
}

function lockPageScrollForModal(modal = null) {
  const token = Symbol('modal-scroll-lock');
  const releaseLayer = registerModalLayer(modal);
  modalPageScrollLocks.add(token);
  syncModalPageScrollLock();
  let released = false;
  return () => {
    if (released) return;
    released = true;
    modalPageScrollLocks.delete(token);
    releaseLayer();
    syncModalPageScrollLock();
  };
}

document.addEventListener('click', event => {
  if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
  const anchor = event.target?.closest?.('a[href^="#/"]');
  if (!anchor || anchor.target) return;
  const href = anchor.getAttribute('href') || '';
  if (!href.startsWith('#/')) return;
  event.preventDefault();
  void navigateTo(href);
});

window.addEventListener('hashchange', event => {
  const targetHash = normalizeAppHash(location.hash || '#/digest');
  const stateHistoryIndex = routeHistoryIndexFromState(history.state);
  const historyDelta = Number.isFinite(stateHistoryIndex) ? stateHistoryIndex - _routeHistoryIndex : 0;
  if (_routeHistoryRepair) {
    const repair = _routeHistoryRepair;
    if (targetHash === repair.expectedHash) {
      _routeHistoryRepair = null;
      _routeHistoryIndex = repair.expectedIndex;
      replaceRouteHistoryState(repair.expectedHash, repair.expectedIndex);
      return;
    }
    _routeHistoryRepair = null;
  }
  const pendingIntent = _pendingRouteIntent;
  const intentSeq = pendingIntent?.hash === targetHash && pendingIntent.seq === _routeIntentSeq
    ? pendingIntent.seq
    : ++_routeIntentSeq;
  _pendingRouteIntent = null;
  void route({ previousHash: hashFromUrl(event.oldURL), historyDelta, intentSeq });
});

function closeTransientOverlays() {
  let blockedBySaving = !closeRerenderPanels();
  document.querySelectorAll('.modal-backdrop').forEach(el => {
    if (typeof el._onClose === 'function') {
      const closed = el._onClose();
      if (closed === false || el.isConnected && (el.dataset.closeAfterRerenderSave === '1' || !!el.querySelector?.('.rerender-popover[data-saving="1"]'))) {
        blockedBySaving = true;
      }
    } else {
      el.remove();
    }
  });
  if (blockedBySaving) return false;
  revokeTrackedObjectUrls();
  return true;
}

const FOCUSABLE_SELECTOR = [
  'a[href]',
  'button:not([disabled])',
  'input:not([disabled])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  '[tabindex]:not([tabindex="-1"])',
].join(',');
let _lastNonModalFocusedControl = null;
document.addEventListener('focusin', event => {
  const target = event.target;
  if (!target?.matches?.(FOCUSABLE_SELECTOR) || target.closest?.('.modal-backdrop')) return;
  _lastNonModalFocusedControl = target;
}, true);
document.addEventListener('click', event => {
  const target = event.target?.closest?.(FOCUSABLE_SELECTOR);
  if (!target || target.closest?.('.modal-backdrop')) return;
  _lastNonModalFocusedControl = target;
}, true);

function visibleFocusableElements(root) {
  return [...(root?.querySelectorAll?.(FOCUSABLE_SELECTOR) || [])]
    .filter(el => !el.hidden && el.offsetParent !== null && !el.closest?.('[inert]'));
}

function trapDialogFocus(dialog, initialFocus = null, { stopPropagation = false } = {}) {
  if (!dialog) return () => {};
  let released = false;
  const focusFallback = () => {
    const first = visibleFocusableElements(dialog)[0] || initialFocus;
    first?.focus?.();
  };
  const onKeydown = e => {
    if (e.key !== 'Tab') return;
    if (stopPropagation) e.stopPropagation();
    const focusable = visibleFocusableElements(dialog);
    if (!focusable.length) {
      e.preventDefault();
      initialFocus?.focus?.();
      return;
    }
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    const active = document.activeElement;
    if (e.shiftKey && (!dialog.contains(active) || active === first)) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && active === last) {
      e.preventDefault();
      first.focus();
    }
  };
  dialog.addEventListener('keydown', onKeydown);
  requestAnimationFrame(focusFallback);
  return () => {
    if (released) return;
    released = true;
    dialog.removeEventListener('keydown', onKeydown);
  };
}

function dialogFocusRestoreContext(opener = null) {
  const section = opener?.closest?.('[data-settings-section]');
  return {
    opener,
    opener_id: String(opener?.id || '').trim(),
    settings_section: String(section?.dataset?.settingsSection || '').trim(),
  };
}

function dialogFocusRestoreTarget(context = {}) {
  const opener = context.opener;
  if (opener?.isConnected && !opener.disabled && opener.getAttribute?.('aria-disabled') !== 'true') return opener;
  if (context.opener_id) {
    const byId = document.getElementById(context.opener_id);
    if (byId?.isConnected && !byId.disabled && byId.getAttribute?.('aria-disabled') !== 'true') return byId;
  }
  if (context.settings_section) activateSettingsSection(context.settings_section);
  const section = settingsSectionElement(context.settings_section);
  return section?.querySelector?.('h3') || section || $app.querySelector?.('h1, h2, .page-head h2') || null;
}

function restoreDialogFocus(context = {}) {
  const focusTarget = ({ onlyWhenLost = false } = {}) => {
    const active = document.activeElement;
    if (onlyWhenLost && active?.isConnected && active !== document.body && active !== document.documentElement) return false;
    const target = dialogFocusRestoreTarget(context);
    if (!target) return false;
    const naturallyFocusable = /^(A|BUTTON|INPUT|SELECT|TEXTAREA)$/i.test(target.tagName || '') || target.hasAttribute?.('tabindex');
    if (!naturallyFocusable) target.setAttribute?.('tabindex', '-1');
    try { target.focus?.({ preventScroll: true }); } catch { target.focus?.(); }
    return document.activeElement === target;
  };
  requestAnimationFrame(() => {
    focusTarget({ onlyWhenLost: true });
    if (!context.opener || context.opener.isConnected) {
      const observer = new MutationObserver(() => {
        if (context.opener?.isConnected) return;
        if (focusTarget({ onlyWhenLost: true })) observer.disconnect();
      });
      observer.observe($app, { childList: true, subtree: true });
      window.setTimeout(() => observer.disconnect(), 15000);
    }
  });
}

function showAppConfirmDialog({
  title = '确认操作',
  message = '',
  messages = [],
  confirmText = '确认',
  cancelText = '取消',
  tone = 'warn',
  hideCancel = false,
  resultMode = 'boolean',
  preferConfirmFocus = false,
} = {}) {
  const active = document.activeElement;
  const opener = active && active !== document.body && active !== document.documentElement
    ? active
    : _lastNonModalFocusedControl;
  const focusRestore = dialogFocusRestoreContext(opener);
  const lines = [
    ...String(message || '').split(/\n+/),
    ...(Array.isArray(messages) ? messages : []),
  ].map(value => String(value || '').trim()).filter(Boolean);
  return new Promise(resolve => {
    const modal = document.createElement('div');
    const titleId = `app-confirm-title-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`;
    const safeTone = ['warn', 'err', 'ok'].includes(String(tone || '').trim())
      ? String(tone || '').trim()
      : 'warn';
    const confirmButtonClass = safeTone === 'err' ? 'btn btn-danger' : 'btn btn-primary';
    modal.className = 'modal-backdrop confirm-backdrop';
    modal.innerHTML = `
      <div class="image-modal confirm-modal confirm-modal-${safeTone}" role="dialog" aria-modal="true" aria-labelledby="${escapeHtml(titleId)}">
        <div class="modal-head">
          <strong id="${escapeHtml(titleId)}">${escapeHtml(title)}</strong>
          <button class="icon-btn" type="button" data-confirm-cancel aria-label="关闭">×</button>
        </div>
        <div class="modal-body confirm-modal-body">
          ${lines.map(line => `<p>${escapeHtml(line)}</p>`).join('')}
        </div>
        <div class="confirm-modal-actions">
          ${hideCancel ? '' : `<button class="btn btn-ghost" type="button" data-confirm-cancel data-confirm-cancel-action>${escapeHtml(cancelText)}</button>`}
          <button class="${confirmButtonClass}" type="button" data-confirm-ok>${escapeHtml(confirmText)}</button>
        </div>
      </div>`;
    document.body.appendChild(modal);
    const okButton = modal.querySelector('[data-confirm-ok]');
    const cancelActionButton = modal.querySelector('[data-confirm-cancel-action]');
    const dismissButtons = modal.querySelectorAll('[data-confirm-cancel]:not([data-confirm-cancel-action])');
    const initialFocusButton = preferConfirmFocus || safeTone === 'ok' ? okButton : (cancelActionButton || okButton);
    const releaseScroll = lockPageScrollForModal(modal);
    const releaseFocus = trapDialogFocus(modal, initialFocusButton);
    let settled = false;
    const finish = (value, action = 'dismiss') => {
      if (settled) return;
      settled = true;
      releaseFocus();
      releaseScroll();
      modal.remove();
      restoreDialogFocus(focusRestore);
      resolve(resultMode === 'action' ? action : !!value);
      return true;
    };
    modal._onClose = () => finish(false, 'dismiss');
    okButton?.addEventListener('click', () => finish(true, 'confirm'));
    cancelActionButton?.addEventListener('click', () => finish(false, 'cancel'));
    dismissButtons.forEach(button => button.addEventListener('click', () => finish(false, 'dismiss')));
    modal.addEventListener('click', event => {
      if (event.target === modal) finish(false, 'dismiss');
    });
    modal.addEventListener('keydown', event => {
      if (event.key !== 'Escape') return;
      event.preventDefault();
      event.stopPropagation();
      finish(false, 'dismiss');
    });
    requestAnimationFrame(() => initialFocusButton?.focus?.());
  });
}

function renderRouteError(error) {
  setRouteDocumentTitle(location.hash || '#/digest', '页面加载失败');
  $app.innerHTML = `
    <section class="page">
      <section class="notice-card" id="route-error-notice" role="alert" aria-live="assertive" tabindex="-1">
        <strong>页面加载失败</strong>
        <span>${escapeHtml(error?.message || '未知错误')}</span>
        <button class="link-btn" id="route-retry" type="button">重试</button>
      </section>
    </section>`;
  document.getElementById('route-retry')?.addEventListener('click', route);
  requestAnimationFrame(() => document.getElementById('route-error-notice')?.focus?.({ preventScroll: true }));
}

function renderBootstrapError(error) {
  setRouteDocumentTitle(location.hash || '#/digest', '启动检查失败');
  $app.innerHTML = `
    <section class="page">
      <section class="notice-card" id="bootstrap-error-notice" role="alert" aria-live="assertive" tabindex="-1">
        <strong>启动检查失败</strong>
        <span>${escapeHtml(error?.message || '无法读取本机状态')}</span>
        <button class="link-btn" id="bootstrap-retry" type="button">重试</button>
      </section>
    </section>`;
  document.getElementById('bootstrap-retry')?.addEventListener('click', () => { void guardedReload('重新加载启动检查'); });
  requestAnimationFrame(() => document.getElementById('bootstrap-error-notice')?.focus?.({ preventScroll: true }));
}

async function reloadIfAssetVersionChanged(state = {}) {
  const serverVersion = String(state.asset_version || '').trim();
  const sourceVersion = String(state.source_asset_version || '').trim();
  const sourceChanged = !!serverVersion && !!sourceVersion && sourceVersion !== serverVersion;
  if (sourceChanged) {
    _serviceRestartRequired = true;
    _activeSourceAssetVersion = sourceVersion;
    _state_digest.frontendAssetStaleMessage = '本地代码已更新，但当前服务仍在运行旧代码；请先重启本地服务，再刷新页面后生成。';
    syncDigestGenerateButtons();
    showAssetReloadNotice(sourceVersion, { reason: 'source_changed', runningVersion: serverVersion });
    return false;
  }
  if (!ASSET_VERSION || !serverVersion || serverVersion === ASSET_VERSION) {
    _activeSourceAssetVersion = '';
    _serviceRestartRequired = false;
    clearFrontendAssetReloadRequired();
    hideAssetReloadNotice(serverVersion);
    if (_state_digest.frontendAssetStaleMessage) {
      _state_digest.frontendAssetStaleMessage = '';
      syncDigestGenerateButtons();
    }
    return false;
  }
  markFrontendAssetReloadRequired(serverVersion);
  _state_digest.frontendAssetStaleMessage = '本地页面版本已更新，请刷新页面后再生成。';
  syncDigestGenerateButtons();
  if ((hasUnsavedChanges() || hasActiveDigestGeneration()) && _deferredAssetReloadVersion === serverVersion) {
    showAssetReloadNotice(serverVersion, { reason: 'reload_deferred' });
    return false;
  }
  if (!await confirmDiscardDirtyChanges('刷新以加载新版前端')) {
    _deferredAssetReloadVersion = serverVersion;
    showAssetReloadNotice(serverVersion, { reason: 'dirty_rejected' });
    return false;
  }
  if (!await confirmActiveDigestReload('刷新以加载新版前端')) {
    _deferredAssetReloadVersion = serverVersion;
    showAssetReloadNotice(serverVersion, { reason: 'active_digest_rejected' });
    return false;
  }
  if (hasActiveDigestGeneration()) cancelDigestGeneration('刷新以加载新版前端');
  const reloadKey = `wx-summary:asset-reload:${serverVersion}`;
  try {
    if (sessionStorage.getItem(reloadKey) === ASSET_VERSION) {
      renderAssetReloadBlocked(serverVersion);
      return true;
    }
    sessionStorage.setItem(reloadKey, ASSET_VERSION);
  } catch {}
  $app.innerHTML = `
    <section class="page">
      <section class="notice-card">
        <strong>前端已更新</strong>
        <span>正在刷新页面以加载最新进度显示。</span>
      </section>
    </section>`;
  clearActiveDirtyProvider();
  setTimeout(() => location.reload(), 40);
  return true;
}

function ensureAssetReloadNotice() {
  let notice = document.getElementById('asset-reload-notice');
  if (notice) return notice;
  notice = document.createElement('section');
  notice.id = 'asset-reload-notice';
  notice.className = 'asset-reload-notice';
  notice.setAttribute('role', 'alert');
  notice.setAttribute('aria-live', 'assertive');
  notice.setAttribute('aria-atomic', 'true');

  const copy = document.createElement('div');
  copy.className = 'asset-reload-copy';
  const title = document.createElement('strong');
  title.dataset.assetReloadTitle = '';
  const message = document.createElement('span');
  message.dataset.assetReloadMessage = '';
  const version = document.createElement('small');
  version.dataset.assetReloadVersion = '';
  copy.append(title, message, version);

  const button = document.createElement('button');
  button.className = 'btn btn-primary';
  button.id = 'asset-reload-now';
  button.type = 'button';
  button.addEventListener('click', async () => {
    const current = _assetReloadNoticeState || {};
    const currentVersion = String(current.version || '').trim();
    if (currentVersion) {
      try { sessionStorage.removeItem(`wx-summary:asset-reload:${currentVersion}`); } catch {}
    }
    const reloadReason = current.sourceChanged ? '刷新以加载重启后的本地服务' : '刷新以加载新版前端';
    if (await guardedReload(reloadReason)) return;
    showAssetReloadNotice(currentVersion, {
      reason: current.sourceChanged ? 'source_changed' : 'reload_deferred',
      runningVersion: current.runningVersion || '',
    });
  });
  notice.append(copy, button);
  document.body.appendChild(notice);
  return notice;
}

function updateAssetReloadNoticeText(notice, selector, value) {
  const target = notice.querySelector(selector);
  if (target && target.textContent !== value) target.textContent = value;
}

function showAssetReloadNotice(serverVersion = '', { reason = '', runningVersion = '' } = {}) {
  if (!ASSET_VERSION) return;
  const sessionExpired = reason === 'session_rejected';
  const sourceChanged = reason === 'source_changed';
  const explicitVersion = String(serverVersion || '').trim();
  const version = sourceChanged
    ? explicitVersion
    : String(explicitVersion || _activeAssetReloadVersion || '').trim();
  _activeAssetReloadVersion = version;
  if (sourceChanged) _activeSourceAssetVersion = explicitVersion;
  const notice = ensureAssetReloadNotice();
  const runningText = String(runningVersion || ASSET_VERSION || '').trim();
  const versionText = sourceChanged
    ? `磁盘代码 ${version || '未知'}，运行服务 ${runningText || '未知'}`
    : (version ? `新版 ${version}，当前 ${ASSET_VERSION}` : `当前 ${ASSET_VERSION}`);
  const title = sourceChanged ? '本地代码已更新，服务需重启' : (sessionExpired ? '本地服务会话已失效' : '本地页面版本已更新');
  const reasonText = sessionExpired
    ? '本地服务已重启或页面来自旧服务。'
    : sourceChanged
    ? '当前服务仍在运行旧代码；仅刷新页面不会加载这次修改。'
    : reason === 'digest_preflight'
    ? '生成已暂停，先刷新页面。'
    : '继续生成、保存、打开文件夹会被本地服务拦截。';
  const actionText = sourceChanged ? '我已重启，刷新页面' : '刷新页面';
  _assetReloadNoticeState = {
    version,
    reason,
    runningVersion: runningText,
    sourceChanged,
  };
  updateAssetReloadNoticeText(notice, '[data-asset-reload-title]', title);
  updateAssetReloadNoticeText(notice, '[data-asset-reload-message]', `${reasonText}这不是数据库、本地数据或 key 错误；${sourceChanged ? '请重启本地服务后再刷新页面。' : '保存或放弃未保存更改后刷新页面。'}`);
  updateAssetReloadNoticeText(notice, '[data-asset-reload-version]', versionText);
  updateAssetReloadNoticeText(notice, '#asset-reload-now', actionText);
  syncAssetReloadNotice();
}

function hideAssetReloadNotice(serverVersion = '') {
  const version = String(serverVersion || '').trim();
  if (version && _activeAssetReloadVersion && version !== _activeAssetReloadVersion) return;
  _activeAssetReloadVersion = '';
  _assetReloadNoticeState = null;
  document.getElementById('asset-reload-notice')?.remove();
}

function renderAssetReloadBlocked(serverVersion = '') {
  showAssetReloadNotice(serverVersion, { reason: 'reload_blocked' });
  $app.innerHTML = `
    <section class="page">
      <section class="notice-card">
        <strong>前端版本未刷新成功</strong>
        <span>本地服务已更新，但浏览器仍在运行旧页面脚本。请手动刷新页面后再生成。</span>
        <button class="link-btn" id="asset-reload-retry" type="button">刷新页面</button>
      </section>
    </section>`;
  clearActiveDirtyProvider();
  document.getElementById('asset-reload-retry')?.addEventListener('click', () => {
    try { sessionStorage.removeItem(`wx-summary:asset-reload:${serverVersion}`); } catch {}
    location.reload();
  });
}

async function handleAccountSwitch() {
  const sel = document.getElementById('account-switcher');
  const intentSeq = ++_accountSwitchIntentSeq;
  const accountDataGeneration = _accountDataGeneration;
  const accountSwitchGeneration = _accountSwitchGeneration;
  const previousConfirmedValue = confirmedAccountSelectionValue();
  let nextValue = sel?.value || '';
  let nextAccountFingerprint = accountCacheFingerprint(accountForSelectionValue(_appAccounts, nextValue) || {});
  const frozenSelectionValue = previousConfirmedValue || nextValue;
  _pendingAccountSwitchIntent = { intent_seq: intentSeq, confirmed_value: previousConfirmedValue };
  if (sel && previousConfirmedValue && !accountsReferToSameAccount(nextValue, previousConfirmedValue)) {
    sel.value = previousConfirmedValue;
  }
  const intentStillCurrent = () => {
    if (intentSeq !== _accountSwitchIntentSeq
      || accountDataGeneration !== _accountDataGeneration
      || accountSwitchGeneration !== _accountSwitchGeneration
      || !sel?.isConnected) return false;
    const selectedValue = String(sel.value || '').trim();
    if (!accountsReferToSameAccount(selectedValue, frozenSelectionValue)) return false;
    return accountCacheFingerprint(accountForSelectionValue(_appAccounts, nextValue) || {}) === nextAccountFingerprint;
  };
  const restorePreviousSelection = () => {
    if (intentStillCurrent()) sel.value = previousConfirmedValue;
  };
  try {
    const digestConfirmed = await confirmActiveDigestReload('切换账号');
    if (!intentStillCurrent()) return false;
    if (!digestConfirmed) {
      restorePreviousSelection();
      return false;
    }
    const draftConfirmed = await confirmDigestDraftPersistenceRisk('切换微信账号');
    if (!intentStillCurrent()) return false;
    if (!draftConfirmed) {
      restorePreviousSelection();
      return false;
    }
    const dirtyConfirmed = await confirmDiscardDirtyChanges('切换微信账号');
    if (!intentStillCurrent()) return false;
    if (!dirtyConfirmed) {
      restorePreviousSelection();
      return false;
    }
    let nextStale = accountStaleInfoForAccountId(nextValue);
    let nextStaleKey = staleAccountConfirmationKey(nextStale);
    const keepStaleConfirmation = !!nextStaleKey && staleAccountConfirmed(nextStale);
    if (nextStale && !keepStaleConfirmation) {
      const choice = await chooseSelectedStaleAccount(nextStale);
      if (!intentStillCurrent()) return false;
      if (choice.action === 'dismiss') {
        restorePreviousSelection();
        return false;
      }
      if (choice.action === 'switch') {
        nextValue = String(choice.account_id || '').trim();
        if (!sel || !nextValue) {
          restorePreviousSelection();
          return false;
        }
        nextAccountFingerprint = accountCacheFingerprint(accountForSelectionValue(_appAccounts, nextValue) || {});
        if (!intentStillCurrent()) {
          restorePreviousSelection();
          return false;
        }
        nextStale = accountStaleInfoForAccountId(nextValue);
        nextStaleKey = staleAccountConfirmationKey(nextStale);
      }
    }
    if (!intentStillCurrent()) return false;
    sel.value = nextValue;
    _confirmedAccountValue = nextValue;
    _accountSwitchGeneration += 1;
    _accountListFailureConfirmedValue = '';
    writeConfirmedAccountValue(nextValue);
    if (_pendingAccountSwitchIntent?.intent_seq === intentSeq) _pendingAccountSwitchIntent = null;
    _confirmedStaleAccountKeys.clear();
    if (nextStaleKey) _confirmedStaleAccountKeys.add(nextStaleKey);
    clearActiveDirtyProvider();
    clearSetupAccountSelectionConfirmation();
    dispatchSettingsActionAbort('微信账号已切换，设置页请求已取消');
    if (hasActiveDigestGeneration()) cancelDigestGeneration('切换账号');
    resetDigestAccountState();
    if (_currentRouteHash === '#/history') {
      window.dispatchEvent(new CustomEvent(APP_STATE_UPDATED_EVENT, {
        detail: { account_changed: true, account_id: nextValue },
      }));
      syncAccountSwitcherDigestLock();
      return true;
    }
    await route({ bypassDirty: true });
    return true;
  } finally {
    if (_pendingAccountSwitchIntent?.intent_seq === intentSeq) _pendingAccountSwitchIntent = null;
    syncAccountSwitcherTitle(sel);
  }
}

function digestAccountSwitchLockMessage() {
  if (digestBatchSettlementPending()) return '上一批结果已生成，本地服务仍在收尾；结果操作已可用，确认完成后再切换微信账号。';
  if (_state_digest?.preflightConfirmationPending) return '正在确认最少消息数，确认或返回修改后再切换微信账号。';
  if (_state_digest?.generating) return '正在生成长图/文本预览，完成或取消后再切换微信账号。';
  if (_state_digest?.rerenderSaving) return '重渲染保存中，完成后再切换微信账号。';
  if (_historyRerenderSavingCount > 0) return '历史重渲染保存中，完成后再切换微信账号。';
  return '';
}

function syncAccountSwitcherTitle(select = null) {
  const sel = select || document.getElementById('account-switcher');
  if (!sel || sel.dataset.accountError === '1' || sel.dataset.digestAccountLock === '1') return;
  const selectedLabel = String(sel.selectedOptions?.[0]?.textContent || '').trim();
  sel.title = selectedLabel && sel.value ? `当前账号：${selectedLabel}` : '切换微信账号';
}

function syncAccountSwitcherDigestLock() {
  const sel = document.getElementById('account-switcher');
  if (!sel) return;
  const lockMessage = digestAccountSwitchLockMessage();
  if (lockMessage) {
    if (sel.dataset.digestAccountLock !== '1') {
      sel.dataset.digestAccountLockTitle = sel.title || '';
    }
    sel.dataset.digestAccountLock = '1';
    sel.disabled = true;
    sel.title = lockMessage;
    return;
  }
  const hadDigestLock = sel.dataset.digestAccountLock === '1';
  const previousTitle = sel.dataset.digestAccountLockTitle || '';
  delete sel.dataset.digestAccountLock;
  delete sel.dataset.digestAccountLockTitle;
  sel.disabled = !_appAccounts.length;
  if (hadDigestLock) {
    sel.title = sel.dataset.accountError === '1' ? previousTitle : '';
  }
  syncAccountSwitcherTitle(sel);
}

function clearSetupAccountSelectionConfirmation() {
  if (_setupWizardDraft?.data?.wechat) {
    const wechat = _setupWizardDraft.data.wechat;
    wechat.account_selection_needs_confirmation = false;
    wechat.account_selection_confirmed_account_id = '';
    wechat.account_selection_confirmed_switch_generation = 0;
    wechat.account_selection_confirmed_data_generation = 0;
  }
}

function dispatchSettingsActionAbort(reason = '设置页请求已取消') {
  window.dispatchEvent(new CustomEvent(SETTINGS_ACTION_ABORT_EVENT, { detail: { reason } }));
}

function dispatchAccountListUpdated(detail = {}) {
  window.dispatchEvent(new CustomEvent(ACCOUNT_LIST_UPDATED_EVENT, { detail }));
}

function scheduleDigestAccountStateReset() {
  if (_digestAccountResetTimer) return;
  const check = () => {
    _digestAccountResetTimer = null;
    if (!_state_digest.accountResetPending) return;
    if (hasActiveDigestGeneration()) {
      _digestAccountResetTimer = setTimeout(check, 250);
      return;
    }
    resetDigestAccountState({ preserveTerminalProgress: true });
  };
  _digestAccountResetTimer = setTimeout(check, 0);
}

function resetDigestAccountState({ preserveTerminalProgress = false } = {}) {
  if (hasActiveDigestGeneration()) {
    invalidateAppStateForAccountChange();
    advanceDigestRunEpoch();
    _state_digest.accountResetPending = true;
    cancelDigestGeneration('账号状态已刷新，当前生成已取消');
    scheduleDigestAccountStateReset();
    upsertDigestLifecycleStage({
      key: 'account-context-changed',
      name: 'account-context-changed',
      stageName: 'batch',
      label: '账号状态已变化，正在停止当前生成',
      status: 'running',
      detail: '已保留本批标识和取消确认；本地服务任务退出后再清理旧账号结果',
    });
    updateGlobalDigestActivity();
    return false;
  }
  invalidateAppStateForAccountChange();
  _state_digest.accountResetPending = false;
  advanceDigestRunEpoch();
  clearDigestCanvasPreview();
  clearTextPreviewOutput({ hide: true });
  resetDigestBatchResults();
  resetDigestDraftInputState();
  _state_digest.lastDigest = null;
  _state_digest.lastSavedItem = null;
  _state_digest.lastTextMarkdown = '';
  _state_digest.lastTextMarkdownFragments = [];
  _state_digest.lastTextTitle = '';
  _state_digest.lastTextComplete = false;
  _state_digest.lastTextDone = 0;
  _state_digest.lastTextTotal = 0;
  _state_digest.lastTextPartialReason = '';
  _state_digest.lastTextDigests = [];
  _state_digest.lastTextBatchId = '';
  _state_digest.lastTextBatchToken = '';
  _state_digest.lastTextBatchServiceInstanceId = '';
  clearTextPreviewServerSnapshotUnavailable();
  invalidateTextPreviewExportTarget({ sync: false });
  _state_digest.lastCanvasRenderKey = '';
  _state_digest.lastSavedRenderKey = '';
  _state_digest.lastRenderSelection = null;
  _state_digest.lastResultInputKey = '';
  _state_digest.lastResultRange = null;
  _state_digest.lastResultAtMs = 0;
  _state_digest.lastResultSourceSnapshot = null;
  _state_digest.lastResultRuntimeVersion = 0;
  _state_digest.groupListBlockedMessage = '';
  if (!preserveTerminalProgress) _state_digest.globalActivity = null;
  _state_digest.generating = false;
  clearActiveDigestRangeSnapshot();
  _state_digest.settlementPending = false;
  _state_digest.settlementWaitController?.abort?.();
  _state_digest.settlementWaitController = null;
  _state_digest.settlementBackgrounded = false;
  _state_digest.abortController = null;
  _state_digest.activeBatchId = '';
  _state_digest.activeBatchToken = '';
  _state_digest.activeBatchServiceInstanceId = '';
  _state_digest.cancelRequest = null;
  _state_digest.abortReason = '';
  if (!preserveTerminalProgress) _state_digest.progress = null;
  _state_digest.stopAfterCurrentSave = false;
  if (!preserveTerminalProgress) abortDigestProgressLog('摘要状态已重置，日志读取已取消');
  stopDigestProgressPaintTimer();
  const previewCard = document.getElementById('preview-card');
  if (previewCard) {
    previewCard.classList.add('hidden');
    previewCard.classList.remove('pending-render');
  }
  updateDigestPreviewActionLock();
  paintDigestProgressSnapshot();
  updateGlobalDigestActivity();
  syncDigestGenerateButtons();
  for (const record of readInterruptedDigestBatchRecords()) {
    if (interruptedDigestBatchMatchesSelectedAccount(record)) {
      _digestBatchRecoveryVisitedIds.delete(record.batch_id);
    }
  }
  if (_digestBatchCrossTabActiveId || _digestBatchRecoveryPending) {
    _digestBatchRecoveryRescheduleAfterAccountReset = true;
  } else {
    queueMicrotask(() => scheduleInterruptedDigestBatchRecoveryFromStorage(0));
  }
  return true;
}

function digestBatchFinishFailureNotice(error = null) {
  if (String(error?.code || '').trim() === 'digest_batch_finish_pending') {
    return '原任务仍在本地服务处理中，页面已保留恢复记录。请等当前任务收尾后刷新页面，不要立即重复生成。';
  }
  const detail = compactErrorSummary(error?.message || error?.statusText || String(error || '未知错误'));
  return `生成结果已留在页面，但本地服务未确认本批已结束${detail ? `：${detail}` : ''}。如果后续按钮仍显示忙碌或保存异常，请刷新页面后再试。`;
}

function digestBatchSettlementPending() {
  return !!(_state_digest.settlementPending && _state_digest.abortController);
}

function digestOutputStillGenerating() {
  return !!(_state_digest.generating && !digestBatchSettlementPending());
}

function notifyDigestBatchFinishFailure(error = null, { runEpoch = 0 } = {}) {
  if (runEpoch && _digestRunEpoch !== runEpoch) return;
  if (hasActiveDigestGeneration()) return;
  const level = String(error?.code || '').trim() === 'digest_batch_finish_pending' ? 'warn' : 'error';
  setGlobalDigestActivityNotice(level, digestBatchFinishFailureNotice(error));
}

const _digestCancelRequestsByBatch = new Map();

function forgetDigestCancelRequest(batchId = '') {
  const id = String(batchId || '').trim();
  if (!id) return false;
  const request = _digestCancelRequestsByBatch.get(id) || null;
  const removed = _digestCancelRequestsByBatch.delete(id);
  if (request && _state_digest.cancelRequest === request) _state_digest.cancelRequest = null;
  return removed;
}

async function finishDigestBatchLeaseResult(batchId, reason = 'finished', {
  notify = false,
  releasePreview = true,
  releaseTerminalResults = false,
  batchToken = '',
  batchServiceInstanceId = '',
  notifyRunEpoch = 0,
  forgetRecovery = true,
  requestTimeoutMs = 15_000,
  retryDelays = null,
  signal = null,
} = {}) {
  const id = String(batchId || '').trim();
  if (!id) return { state: 'invalid', settled: false, error: null };
  const token = String(batchToken || '').trim() || (id === String(_state_digest.activeBatchId || '').trim() ? _state_digest.activeBatchToken : '');
  const serviceInstanceId = digestBatchServiceInstanceId(id, batchServiceInstanceId);
  try {
    const delays = Array.isArray(retryDelays) && retryDelays.length ? retryDelays : [0, 250, 750, 1500];
    for (const delayMs of delays) {
      if (signal?.aborted) return { state: 'cancelled', settled: false, error: abortErrorForSignal(signal, '已停止等待摘要批次收尾') };
      if (delayMs) await digestResultRecoveryDelay(delayMs, signal);
      if (signal?.aborted) return { state: 'cancelled', settled: false, error: abortErrorForSignal(signal, '已停止等待摘要批次收尾') };
      const result = await api('/api/digest-batch-finish', {
        method: 'POST',
        signal,
        timeoutMs: Math.max(1000, Number(requestTimeoutMs || 0) || 15_000),
        body: {
          batch_id: id,
          batch_token: token,
          service_instance_id: serviceInstanceId,
          reason,
          release_preview: releasePreview !== false,
          release_terminal_results: releaseTerminalResults === true,
        },
      });
      if (result.settled === true) {
        if (forgetRecovery) forgetInterruptedDigestBatch(id);
        forgetDigestCancelRequest(id);
        return { state: 'settled', settled: true, error: null, result };
      }
    }
    const pendingError = new Error('原摘要任务仍在本地服务处理中，恢复记录已保留。');
    pendingError.code = 'digest_batch_finish_pending';
    if (notify) notifyDigestBatchFinishFailure(pendingError, { runEpoch: notifyRunEpoch });
    return { state: 'pending', settled: false, error: pendingError };
  } catch (e) {
    if (signal?.aborted) {
      return { state: 'cancelled', settled: false, error: abortErrorForSignal(signal, '已停止等待摘要批次收尾') };
    }
    console.warn('digest batch finish failed', e);
    if (digestBatchRestartInterrupted(e)) {
      if (forgetRecovery) forgetInterruptedDigestBatch(id);
      return { state: 'interrupted', settled: false, error: e };
    }
    if (notify) notifyDigestBatchFinishFailure(e, { runEpoch: notifyRunEpoch });
    return { state: 'unreachable', settled: false, error: e };
  }
}

async function finishDigestBatchLease(batchId, reason = 'finished', options = {}) {
  return (await finishDigestBatchLeaseResult(batchId, reason, options)).settled === true;
}

function releaseTextPreviewRecoveryAfterExport({ batchId = '', batchToken = '', batchServiceInstanceId = '' } = {}) {
  const id = String(batchId || '').trim();
  const token = String(batchToken || '').trim();
  const serviceInstanceId = normalizeServiceInstanceId(batchServiceInstanceId || '');
  if (!id || !token || !serviceInstanceId) return;
  // The MD commit is already durable when this function runs. Server-side
  // lease cleanup may be retried or expire naturally, but it must never make a
  // new page present the committed preview as "not exported" again.
  forgetInterruptedDigestBatch(id);
  void finishDigestBatchLeaseResult(id, 'preview_exported', {
    notify: false,
    releasePreview: true,
    releaseTerminalResults: true,
    batchToken: token,
    batchServiceInstanceId: serviceInstanceId,
    forgetRecovery: true,
    requestTimeoutMs: 5000,
    retryDelays: [0],
  }).then(result => {
    if (!result.settled && result.state !== 'cancelled') {
      console.warn('text preview batch cleanup deferred', result.error || result.state);
    }
  });
}

function digestCancelRequestForBatch(batchId = '') {
  const id = String(batchId || '').trim();
  if (!id) return null;
  const tracked = _digestCancelRequestsByBatch.get(id) || null;
  if (tracked) return tracked;
  const request = _state_digest.cancelRequest;
  return request?.batchId === id ? request : null;
}

function digestCancelConfirmationRetryAvailable() {
  const request = digestCancelRequestForBatch(_state_digest.activeBatchId);
  return !!(_state_digest.abortController?.signal?.aborted
    && request
    && request.confirmed !== true
    && !request.inFlight
    && request.lastError);
}

function showDigestCancelConfirmationFailure(request = null) {
  if (!request || request !== _state_digest.cancelRequest || !request.lastError) return;
  const detail = compactErrorSummary(request.lastError?.message || '本地服务暂时无响应');
  upsertDigestLifecycleStage({
    key: 'cancel-confirmation',
    name: 'cancel-confirmation',
    stageName: 'batch',
    label: '取消请求未确认，可重试',
    status: 'warn',
    detail: `${detail}；已停止浏览器侧等待，点击“重试取消”可再次通知本地服务`,
  });
  const preferredStatusId = _state_digest.progress?.previewText ? 'text-preview-status' : 'preview-status';
  const status = document.getElementById(preferredStatusId)
    || document.getElementById(preferredStatusId === 'preview-status' ? 'text-preview-status' : 'preview-status');
  if (status?.isConnected) {
    status.className = 'status warn';
    status.textContent = `取消请求未收到本地服务确认：${detail}。可点击“重试取消”。`;
  }
}

async function confirmDigestCancelRequest(request = null) {
  if (!request || request.confirmed === true) return true;
  if (request.inFlight) return request.inFlight;
  request.attempts = Math.max(0, Number(request.attempts || 0) || 0) + 1;
  request.inFlight = api('/api/digest-cancel', {
    method: 'POST',
    timeoutMs: 8000,
    body: {
      batch_id: request.batchId,
      batch_token: request.batchToken,
      service_instance_id: request.serviceInstanceId,
      reason: request.reason,
      abort_saves: request.abortSaves,
      preserve_completed_results: true,
    },
  }).then(result => {
    request.confirmed = true;
    request.lastError = null;
    request.result = result;
    return true;
  }).catch(error => {
    request.lastError = error;
    return false;
  }).finally(() => {
    request.inFlight = null;
    const pendingHardCancel = request.pendingAbortSaves === true && request.abortSaves === false;
    if (pendingHardCancel) {
      request.pendingAbortSaves = false;
      request.abortSaves = true;
      request.reason = String(request.pendingReason || request.reason || '取消').trim() || '取消';
      request.pendingReason = '';
      request.confirmed = false;
      request.lastError = null;
      request.result = null;
      void confirmDigestCancelRequest(request);
    }
    if (request === _state_digest.cancelRequest) {
      try {
        if (request.lastError) showDigestCancelConfirmationFailure(request);
      } catch (error) {
        console.warn('digest cancel failure status update failed', error);
      } finally {
        try { updateDigestCancelButton(); } catch (error) { console.warn('digest cancel button update failed', error); }
        try { updateGlobalDigestActivity(); } catch (error) { console.warn('digest cancel activity update failed', error); }
      }
    }
  });
  updateDigestCancelButton();
  updateGlobalDigestActivity();
  return request.inFlight;
}

function beginDigestCancelConfirmation({ batchId = '', batchToken = '', batchServiceInstanceId = '', reason = '取消', abortSaves = true } = {}) {
  const id = String(batchId || '').trim();
  if (!id) return null;
  const cleanReason = String(reason || '取消').trim() || '取消';
  const wantsHardCancel = abortSaves !== false;
  let request = digestCancelRequestForBatch(id);
  if (request?.confirmed === true && request.abortSaves === false && wantsHardCancel) request = null;
  if (!request) {
    request = {
      batchId: id,
      batchToken: String(batchToken || '').trim(),
      serviceInstanceId: digestBatchServiceInstanceId(id, batchServiceInstanceId),
      reason: cleanReason,
      abortSaves: wantsHardCancel,
      pendingAbortSaves: false,
      pendingReason: '',
      confirmed: false,
      attempts: 0,
      lastError: null,
      result: null,
      inFlight: null,
      createdAt: Date.now(),
    };
    _digestCancelRequestsByBatch.set(id, request);
  } else {
    request.batchToken ||= String(batchToken || '').trim();
    request.serviceInstanceId ||= digestBatchServiceInstanceId(id, batchServiceInstanceId);
    if (request.inFlight && request.abortSaves === false && wantsHardCancel) {
      request.pendingAbortSaves = true;
      request.pendingReason = cleanReason;
    } else if (!request.inFlight && request.confirmed !== true) {
      request.reason = cleanReason;
      request.abortSaves = request.abortSaves !== false || wantsHardCancel;
    }
  }
  if (String(_state_digest.activeBatchId || '').trim() === id) _state_digest.cancelRequest = request;
  void confirmDigestCancelRequest(request);
  return request;
}

function abortActiveDigest(reason = '取消', { abortSaves = true, forceLocalAbort = false } = {}) {
  if (!_state_digest.abortController) return false;
  const controller = _state_digest.abortController;
  const batchId = _state_digest.activeBatchId;
  const batchToken = _state_digest.activeBatchToken;
  const batchServiceInstanceId = _state_digest.activeBatchServiceInstanceId;
  const shouldAbortSaves = abortSaves !== false;
  beginDigestCancelConfirmation({ batchId, batchToken, batchServiceInstanceId, reason, abortSaves: shouldAbortSaves });
  _state_digest.abortReason = reason;
  if (shouldAbortSaves) {
    _state_digest.stopAfterCurrentSave = false;
    controller.abort();
  } else {
    _state_digest.stopAfterCurrentSave = true;
    if (forceLocalAbort && !controller.signal.aborted) {
      controller.abort(digestAbortError(reason || '已停止等待保存结果'));
    }
  }
  updateDigestCancelButton();
  updateGlobalDigestActivity();
  return true;
}

function cancelDigestGeneration(reason = '取消', { commitReason = '', forceLocalAbort = false } = {}) {
  if (!_state_digest.generating && _digestBatchRecoveryPending) {
    return backgroundInterruptedDigestBatchRecovery(reason || '已转到后台确认刷新前的摘要结果');
  }
  if (digestBatchSettlementPending()) return backgroundDigestBatchSettlement(reason || '已转到后台确认本批服务端收尾');
  const commitStage = !!_state_digest.stopAfterCurrentSave || digestProgressCommitSensitiveStage();
  const finalReason = commitStage && commitReason ? commitReason : reason;
  return abortActiveDigest(finalReason, { abortSaves: !commitStage, forceLocalAbort });
}

function backgroundDigestBatchSettlement(reason = '已转到后台确认本批服务端收尾') {
  if (!digestBatchSettlementPending()) return false;
  _state_digest.settlementBackgrounded = true;
  upsertDigestLifecycleStage({
    key: 'batch-settlement',
    name: 'batch-settlement',
    stageName: 'batch',
    label: '本批正在后台确认收尾',
    status: 'running',
    detail: '已生成结果仍可使用；服务端确认全部任务退出前不会开放新批次',
  });
  setGlobalDigestActivityNotice('warn', `${reason}；确认完成前不能开始新批次。`);
  syncDigestGenerateButtons();
  updateDigestCancelButton();
  updateGlobalDigestActivity();
  return true;
}

function cancelActiveDigestFromUser() {
  if (!_state_digest.generating && _digestBatchRecoveryPending) {
    return backgroundInterruptedDigestBatchRecovery('已转到后台确认刷新前的摘要结果');
  }
  const cancelRequest = digestCancelRequestForBatch(_state_digest.activeBatchId);
  if (digestCancelConfirmationRetryAvailable()) {
    void confirmDigestCancelRequest(cancelRequest);
    return true;
  }
  if (digestBatchSettlementPending()) {
    return backgroundDigestBatchSettlement('已转到后台确认本批服务端收尾');
  }
  if (_state_digest.stopAfterCurrentSave && _state_digest.abortController && !_state_digest.abortController.signal.aborted) {
    return abortActiveDigest('用户停止等待保存结果', { abortSaves: false, forceLocalAbort: true });
  }
  return cancelDigestGeneration('用户取消', { commitReason: '用户停止后续群' });
}

function setupGlobalDigestActivity() {
  document.getElementById('global-digest-jump')?.addEventListener('click', () => {
    if (location.hash.replace(/^#/, '').split('?')[0] === '/digest') {
      scrollDigestWorkIntoView(document.getElementById('progress-card'));
      return;
    }
    navigateTo('#/digest');
  });
  document.getElementById('global-digest-cancel')?.addEventListener('click', () => {
    if (hasActiveDigestGeneration()) cancelActiveDigestFromUser();
    else clearGlobalDigestActivityNotice();
  });
  updateGlobalDigestActivity();
}

let _stickyHeaderResizeObserver = null;
let _stickyHeaderResizeFallbackAttached = false;

function updateStickyHeaderHeight() {
  const header = document.getElementById('app-sticky-header');
  if (!header) return;
  const height = Math.max(1, Math.ceil(header.getBoundingClientRect().height));
  document.documentElement.style.setProperty('--app-sticky-header-h', `${height}px`);
}

function setupStickyHeaderHeightTracking() {
  const header = document.getElementById('app-sticky-header');
  if (!header) return;
  updateStickyHeaderHeight();
  if (typeof ResizeObserver === 'function') {
    _stickyHeaderResizeObserver?.disconnect?.();
    _stickyHeaderResizeObserver = new ResizeObserver(() => updateStickyHeaderHeight());
    _stickyHeaderResizeObserver.observe(header);
    return;
  }
  if (!_stickyHeaderResizeFallbackAttached) {
    window.addEventListener('resize', updateStickyHeaderHeight, { passive: true });
    _stickyHeaderResizeFallbackAttached = true;
  }
}

function updateGlobalDigestActivity() {
  const bar = document.getElementById('global-digest-activity');
  if (!bar) return;
  const active = hasActiveDigestGeneration();
  const notice = _state_digest.globalActivity && typeof _state_digest.globalActivity === 'object'
    ? _state_digest.globalActivity
    : null;
  const visible = active || !!notice;
  const focusWasInside = !visible && bar.contains(document.activeElement);
  bar.classList.toggle('hidden', !visible);
  bar.classList.toggle('running', active);
  bar.classList.toggle('done', !active && notice?.kind === 'done');
  bar.classList.toggle('warn', !active && notice?.kind === 'warn');
  bar.classList.toggle('error', !active && notice?.kind === 'error');
  bar.classList.toggle('cancelled', !active && notice?.kind === 'cancelled');
  requestAnimationFrame(updateStickyHeaderHeight);
  if (!visible) {
    if (focusWasInside) {
      requestAnimationFrame(() => {
        const focused = document.activeElement;
        if (focused?.isConnected
          && focused !== document.body
          && focused !== document.documentElement
          && !bar.contains(focused)) return;
        focusRouteHeading();
      });
    }
    announceGlobalDigestActivity('');
    return;
  }
  const text = document.getElementById('global-digest-text');
  const jump = document.getElementById('global-digest-jump');
  const cancel = document.getElementById('global-digest-cancel');
  if (active) {
    const recovering = !_state_digest.generating && _digestBatchRecoveryPending;
    const current = recovering ? null : (_state_digest.progress ? digestProgressCurrentState(_state_digest.progress) : null);
    const label = current?.text
      ? current.text.replace(/^(正在|最近完成|失败|已取消)：/, '')
      : (recovering
        ? (_digestBatchRecoveryBackgrounded ? '刷新前任务正在后台确认...' : '正在恢复刷新前的摘要结果...')
        : '生成中...');
    if (text) text.textContent = label || (recovering
      ? (_digestBatchRecoveryBackgrounded ? '刷新前任务正在后台确认...' : '正在恢复刷新前的摘要结果...')
      : '生成中...');
    announceGlobalDigestActivity(
      digestOutputStatusOwnsTerminalAnnouncement(current?.className) ? '' : (current?.text || label),
    );
    if (jump) jump.textContent = '查看';
    if (cancel) {
      const aborted = recovering
        ? !!_digestBatchRecoveryAbortController?.signal?.aborted
        : !!_state_digest.abortController?.signal?.aborted;
      const retryCancel = digestCancelConfirmationRetryAvailable();
      const stoppingAfterSave = !!_state_digest.stopAfterCurrentSave && !aborted;
      const settlementBackgrounded = digestBatchSettlementPending() && _state_digest.settlementBackgrounded;
      const recoveryBackgrounded = recovering && _digestBatchRecoveryBackgrounded;
      cancel.disabled = aborted && !retryCancel;
      if (settlementBackgrounded || recoveryBackgrounded) cancel.disabled = true;
      if (recovering) cancel.textContent = recoveryBackgrounded ? '后台确认中' : (aborted ? '正在停止...' : '转后台确认');
      else cancel.textContent = retryCancel ? '重试取消' : (aborted ? '正在取消...' : (digestBatchSettlementPending() ? (settlementBackgrounded ? '后台确认中' : '转后台确认') : (stoppingAfterSave ? '停止等待' : '取消')));
      cancel.title = retryCancel
        ? '上次取消请求未收到本地服务确认；点击重新发送取消请求'
        : (digestBatchSettlementPending()
          ? (settlementBackgrounded ? '本批正在后台确认收尾；确认完成前不能开始新批次' : '把收尾确认转到后台继续；确认完成前不能开始新批次')
          : (recovering
            ? (recoveryBackgrounded ? '刷新前任务正在后台确认；确认完成前不能开始新批次' : '把刷新前任务的收尾确认转到后台继续')
            : (stoppingAfterSave ? '不再等待当前保存响应；如果保存已提交，历史记录可能稍后出现' : '')));
      cancel.classList.add('danger-link');
    }
    return;
  }
  if (text) text.textContent = notice?.text || '摘要任务已结束';
  const terminalClass = _state_digest.progress ? digestProgressCurrentState(_state_digest.progress).className : '';
  announceGlobalDigestActivity(
    digestOutputStatusOwnsTerminalAnnouncement(terminalClass) ? '' : (notice?.text || '摘要任务已结束'),
  );
  if (jump) jump.textContent = notice?.kind === 'done' ? '查看结果' : '查看详情';
  if (cancel) {
    cancel.disabled = false;
    cancel.textContent = '关闭';
    cancel.title = '';
    cancel.classList.remove('danger-link');
  }
}

function setGlobalDigestActivityNotice(kind = 'done', text = '', { announce = true } = {}) {
  _state_digest.globalActivity = {
    kind: ['done', 'warn', 'error', 'cancelled'].includes(kind) ? kind : 'done',
    text: compactErrorSummary(text) || '摘要任务已结束',
    announce: announce !== false,
    at: Date.now(),
  };
  updateGlobalDigestActivity();
}

function clearGlobalDigestActivityNotice() {
  _state_digest.globalActivity = null;
  updateGlobalDigestActivity();
}

async function bootstrap() {
  queueMicrotask(() => startInterruptedDigestBatchBootstrapHeartbeat());
  const accountResult = await api('/api/accounts').then(
    accounts => ({ accounts }),
    error => ({ error }),
  );
  applyBootstrapAccountsResult(accountResult, { routeDigest: false });

  const stateResult = await fetchAppState().then(
    state => ({ state }),
    error => ({ error }),
  );

  if (stateResult.error) {
    renderBootstrapError(stateResult.error);
    return;
  }
  let state = stateResult.state;
  const stateAccounts = Array.isArray(state?.wechat?.accounts) ? state.wechat.accounts : [];
  if (accountResult.error && stateAccounts.length) {
    const previousSelected = selectedAccountId();
    applyBootstrapAccountsResult({ accounts: stateAccounts }, { routeDigest: false });
    const selectedAfterStateAccounts = selectedAccountId();
    if (selectedAfterStateAccounts && !accountsReferToSameAccount(previousSelected, selectedAfterStateAccounts, stateAccounts)) {
      const selectedStateResult = await fetchAppState().then(
        nextState => ({ state: nextState }),
        error => ({ error }),
      );
      if (selectedStateResult.error) {
        renderBootstrapError(selectedStateResult.error);
        return;
      }
      state = selectedStateResult.state;
    }
  }
  if (await reloadIfAssetVersionChanged(state)) return;
  void recoverInterruptedDigestBatchAfterBootstrap();
  if (state.need_setup && normalizeAppHash(location.hash || '#/digest') !== '#/setup') {
    navigateTo('#/setup', { bypassDirty: true });
  } else if (!location.hash) {
    navigateTo('#/digest', { bypassDirty: true });
  } else {
    await route();
  }
  void (async () => {
    await recoverBrowserClipboardJournalAfterBootstrap();
    await recoverPendingLocalActionsAfterBootstrap();
  })().catch(error => {
    showLocalActionNotice({
      title: '刷新前操作恢复未完成',
      message: `恢复刷新前操作时发生异常：${compactErrorSummary(error?.message || '未知错误')}；页面没有重放任何本地操作，请核对文件、历史记录或剪贴板后再决定是否重试。`,
      tone: 'warn',
    });
  });
}
setupFrontendAssetFreshnessWatchers();
setupBrowserClipboardWritePermissionWatcher();
bootstrap();

function applyBootstrapAccountsResult(accountResult = {}, { routeDigest = true } = {}) {
  const sel = document.getElementById('account-switcher');
  if (sel) {
    if (accountResult.error) {
      _lastAccountsError = accountResult.error;
      const previousAccounts = _appAccounts;
      const previousValue = stableAccountSelectionValue(sel);
      const previousAliases = accountAliasesForValue(previousValue, previousAccounts);
      const preserveEmptySelection = sel.dataset.bound === '1' && !previousValue;
      if (previousAccounts.length) {
        sel.innerHTML = renderAccountOptions(previousAccounts, previousValue, { previousAliases, preserveMissingSelection: true, preserveEmptySelection });
        restoreAccountSelection(sel, previousAccounts, previousValue, { previousAliases, preserveMissingSelection: true, preserveEmptySelection });
        sel.disabled = false;
        sel.dataset.accountError = '1';
        sel.title = `账号列表读取失败：${compactErrorSummary(accountResult.error.message || '未知错误')}。已保留上一次可用账号；请重试账号列表，或确认继续使用上次账号。`;
      } else {
        applyAccountsSnapshot([]);
        sel.innerHTML = `<option value="">账号读取失败：${escapeHtml(accountResult.error.message || '未知错误')}</option>`;
        sel.disabled = true;
      }
      if (sel.dataset.bound !== '1') {
        sel.addEventListener('change', handleAccountSwitch);
        sel.dataset.bound = '1';
      }
      syncAccountSwitcherDigestLock();
    } else {
      _lastAccountsError = null;
      const { accounts } = applyAccountsSnapshot(accountResult.accounts);
      const previousValue = stableAccountSelectionValue(sel);
      const hadListener = sel.dataset.bound === '1';
      const preserveEmptySelection = hadListener && !previousValue;
      if (hadListener) sel.removeEventListener('change', handleAccountSwitch);
      sel.innerHTML = renderAccountOptions(accounts, previousValue, { preserveEmptySelection });
      restoreAccountSelection(sel, accounts, previousValue, { preserveEmptySelection });
      const selectedValue = sel.value || '';
      if (previousValue && selectedValue && previousValue !== selectedValue) {
        resetDigestAccountState();
      }
      _confirmedAccountValue = sel.value || '';
      sel.disabled = !accounts.length;
      sel.addEventListener('change', handleAccountSwitch);
      sel.dataset.bound = '1';
      syncAccountSwitcherDigestLock();
    }
  }
  syncAppStateDependentControls();
  window.dispatchEvent(new CustomEvent(ACCOUNT_LIST_UPDATED_EVENT, {
    detail: {
      accounts: _appAccounts,
      error: accountResult.error || null,
      bootstrap: true,
    },
  }));
  if (routeDigest && normalizeAppHash(location.hash || '#/digest') === '#/digest' && document.querySelector('.page-digest') && !hasActiveDigestGeneration()) {
    void route({ bypassDirty: true });
  }
}

async function refreshTopbarAccounts({ returnMeta = false, preserveMissingSelection = false, force = false, signal = null, acceptedIdentityUpgrade = null, preserveGroupRequestLease = null } = {}) {
  const requestMeta = beginAccountListRequest({ force });
  try {
    const accountsPath = force ? '/api/accounts?refresh=true' : '/api/accounts';
    const accountPayload = await api(accountsPath, { signal });
    if (!accountListResponseMayApply(requestMeta)) {
      const sel = document.getElementById('account-switcher');
      const selectedValue = stableAccountSelectionValue(sel);
      return returnMeta
        ? { applied: false, accounts: _appAccounts, previousValue: selectedValue, selectedValue, selectionChanged: false, selectionLost: false, accountsChanged: false, stale: true }
        : _appAccounts;
    }
    markAccountListResponseApplied(requestMeta);
    _lastAccountsError = null;
    _accountListFailureConfirmedValue = '';
    const sel = document.getElementById('account-switcher');
    const previousAccounts = _appAccounts;
    const previousGroupCacheAccounts = digestGroupCacheAccountsSignature(previousAccounts);
    const previousValue = stableAccountSelectionValue(sel);
    const previousAliases = accountAliasesForValue(previousValue, previousAccounts);
    const previousAccountFingerprint = accountFingerprintForValue(previousValue, previousAccounts);
    const { accounts, accountsChanged } = applyAccountsSnapshot(accountPayload);
    const groupCacheAccountsChanged = previousGroupCacheAccounts !== digestGroupCacheAccountsSignature(accounts);
    if (!sel) return returnMeta ? { applied: true, accounts, previousValue: '', selectedValue: '', selectionChanged: false, selectionLost: false, accountsChanged } : accounts;
    const preserveEmptySelection = sel.dataset.bound === '1' && !previousValue;
    sel.innerHTML = renderAccountOptions(accounts, previousValue, { previousAliases, preserveMissingSelection, preserveEmptySelection });
    restoreAccountSelection(sel, accounts, previousValue, { previousAliases, preserveMissingSelection, preserveEmptySelection });
    const selectedValue = sel.value || '';
    const previousAccount = accountForSelectionValue(accounts, previousValue, { previousAliases });
    const previousStale = previousAccount ? accountStaleInfoForAccount(previousAccount, accounts) : null;
    const staleAutoSwitchSuppressed = !!previousStale
      && !staleAccountConfirmed(previousStale);
    const selectionLost = !!previousValue && !selectedValue;
    const rawSelectionChanged = !!previousValue && !!selectedValue && previousValue !== selectedValue;
    const selectedAccountFingerprint = accountFingerprintForValue(selectedValue, accounts);
    const acceptedPreviousFingerprint = String(acceptedIdentityUpgrade?.previous_fingerprint || '').trim().toLowerCase();
    const acceptedNextFingerprint = String(acceptedIdentityUpgrade?.next_fingerprint || '').trim().toLowerCase();
    const identityUpgradeProofValid = apiPlainObject(acceptedIdentityUpgrade)
      && /^[a-f0-9]{64}$/.test(acceptedPreviousFingerprint)
      && /^[a-f0-9]{64}$/.test(acceptedNextFingerprint)
      && acceptedPreviousFingerprint !== acceptedNextFingerprint;
    const identityUpgradeTransitionAccepted = identityUpgradeProofValid
      && acceptedPreviousFingerprint === previousAccountFingerprint
      && acceptedNextFingerprint === selectedAccountFingerprint
      && accountsReferToSameAccount(previousValue, selectedValue);
    const identityUpgradeAlreadyApplied = identityUpgradeProofValid
      && acceptedNextFingerprint === previousAccountFingerprint
      && acceptedNextFingerprint === selectedAccountFingerprint
      && accountsReferToSameAccount(previousValue, selectedValue);
    const identityUpgradeAccepted = identityUpgradeTransitionAccepted || identityUpgradeAlreadyApplied;
    const selectionChanged = rawSelectionChanged && !identityUpgradeAccepted;
    const accountContextChanged = !!previousValue
      && !!selectedValue
      && !selectionChanged
      && !identityUpgradeAccepted
      && accountFingerprintContextChanged(previousAccountFingerprint, selectedAccountFingerprint);
    if (previousValue && (selectionLost || selectionChanged || accountContextChanged)) resetDigestAccountState();
    if (groupCacheAccountsChanged) {
      clearDigestGroupCache('微信账号缓存上下文已变化', { preserveLease: preserveGroupRequestLease });
    }
    _confirmedAccountValue = selectedValue;
    sel.disabled = !accounts.length;
    delete sel.dataset.accountError;
    sel.title = '';
    syncAccountSwitcherDigestLock();
    if (sel.dataset.bound !== '1') {
      sel.addEventListener('change', handleAccountSwitch);
      sel.dataset.bound = '1';
    }
    dispatchAccountListUpdated({ accounts, previousValue, selectedValue, selectionChanged, selectionLost, accountsChanged, accountContextChanged, identityUpgraded: identityUpgradeAccepted, staleAutoSwitchSuppressed });
    return returnMeta ? { applied: true, accounts, previousValue, selectedValue, selectionChanged, selectionLost, accountsChanged, accountContextChanged, identityUpgraded: identityUpgradeAccepted, staleAutoSwitchSuppressed } : accounts;
  } catch (e) {
    if (signal?.aborted || e?.name === 'AbortError' || e?.status === 499) throw e;
    if (!accountListResponseMayApply(requestMeta)) {
      const sel = document.getElementById('account-switcher');
      const selectedValue = stableAccountSelectionValue(sel);
      return returnMeta
        ? { applied: false, accounts: _appAccounts, previousValue: selectedValue, selectedValue, selectionChanged: false, selectionLost: false, accountsChanged: false, stale: true }
        : _appAccounts;
    }
    markAccountListResponseApplied(requestMeta);
    _lastAccountsError = e;
    _accountListFailureConfirmedValue = '';
    const sel = document.getElementById('account-switcher');
    const previousAccounts = _appAccounts;
    const previousValue = stableAccountSelectionValue(sel);
    const previousAliases = accountAliasesForValue(previousValue, previousAccounts);
    const preserveEmptySelection = sel?.dataset?.bound === '1' && !previousValue;
    let selectedValue = previousValue;
    if (sel) {
      if (previousAccounts.length) {
        sel.innerHTML = renderAccountOptions(previousAccounts, previousValue, { previousAliases, preserveMissingSelection: true, preserveEmptySelection });
        restoreAccountSelection(sel, previousAccounts, previousValue, { previousAliases, preserveMissingSelection: true, preserveEmptySelection });
        selectedValue = sel.value || previousValue;
        sel.disabled = false;
        sel.dataset.accountError = '1';
        sel.title = `账号列表刷新失败：${compactErrorSummary(e.message || '未知错误')}。已保留上一次可用账号，可继续确认或稍后重试账号列表。`;
      } else {
        sel.innerHTML = `<option value="">账号读取失败：${escapeHtml(e.message || '未知错误')}</option>`;
        selectedValue = '';
        sel.disabled = true;
      }
      syncAccountSwitcherDigestLock();
      if (sel.dataset.bound !== '1') {
        sel.addEventListener('change', handleAccountSwitch);
        sel.dataset.bound = '1';
      }
    }
    dispatchAccountListUpdated({ accounts: previousAccounts, previousValue, selectedValue, selectionChanged: false, selectionLost: false, accountsChanged: false, error: e });
    return returnMeta ? { applied: true, accounts: previousAccounts, previousValue, selectedValue, selectionChanged: false, selectionLost: false, accountsChanged: false, error: e } : previousAccounts;
  }
}

async function refreshAppStateSilently({ refresh = false, signal = null } = {}) {
  try {
    return await fetchAppState({ refresh, signal });
  } catch (e) {
    if (!(signal?.aborted || e?.name === 'AbortError' || e?.status === 499)) rememberAppStateRefreshFailure(e);
    return null;
  }
}

function scheduleLocalActionCapabilityRefreshAfterFailure() {
  if (_localActionCapabilityRefreshPromise) return _localActionCapabilityRefreshPromise;
  _localActionCapabilityRefreshPromise = Promise.resolve()
    .then(() => refreshAppStateSilently({ refresh: true }))
    .finally(() => {
      _localActionCapabilityRefreshPromise = null;
    });
  return _localActionCapabilityRefreshPromise;
}

// ---------- 工具 ----------
function tplOf(id) {
  const tpl = document.getElementById(id);
  return tpl.content.cloneNode(true);
}

function escapeHtml(s) {
  return String(s ?? '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
}

function setSecretTextareaVisibility(input, toggle, visible = false) {
  if (!input || !toggle) return;
  const show = visible === true;
  input.classList.toggle('secret-textarea-masked', !show);
  const label = show ? '隐藏手动密钥输入' : '显示手动密钥输入';
  toggle.setAttribute('aria-label', label);
  toggle.setAttribute('aria-pressed', show ? 'true' : 'false');
  toggle.title = label;
}

function bindSecretTextareaToggle(input, toggle) {
  if (!input || !toggle || toggle.dataset.bound === '1') return;
  setSecretTextareaVisibility(input, toggle, false);
  toggle.addEventListener('click', () => {
    setSecretTextareaVisibility(input, toggle, toggle.getAttribute('aria-pressed') !== 'true');
    input.focus({ preventScroll: true });
  });
  toggle.dataset.bound = '1';
}

function splitManualKeysText(value) {
  const text = String(value || '');
  const out = [];
  const seen = new Set();
  const add = token => {
    for (const key of normalizeManualKeyTokens(token)) {
      if (!key || seen.has(key)) continue;
      seen.add(key);
      out.push(key);
    }
  };
  manualKeyTextMatches(text).forEach(item => add(item.token));
  return out;
}

function manualKeyCandidateMatches(value) {
  const text = String(value || '');
  const matches = [];
  const explicit = /[xX]'([a-fA-F0-9]{64,192})'|0[xX]([a-fA-F0-9]{64,192})/g;
  let match;
  while ((match = explicit.exec(text))) {
    const token = match[1] || match[2];
    matches.push({ index: match.index, end: match.index + match[0].length, token });
  }
  const bare = /[a-fA-F0-9]{64,192}/g;
  while ((match = bare.exec(text))) {
    const start = match.index;
    const end = start + match[0].length;
    const before = start > 0 ? text.charCodeAt(start - 1) : 0;
    const after = end < text.length ? text.charCodeAt(end) : 0;
    if (isHexCharCode(before) || isHexCharCode(after)) continue;
    matches.push({ index: start, end, token: match[0] });
  }
  return matches.sort((a, b) => a.index - b.index);
}

function manualKeyTextMatches(value) {
  return manualKeyCandidateMatches(value)
    .filter(item => normalizeManualKeyTokens(item.token).length > 0);
}

function manualKeyContextLine(line = '') {
  const clean = String(line || '').trim();
  if (!clean) return true;
  if (/^[{}\[\],]+$/.test(clean)) return true;
  if (/^(?:\/\/|#)/.test(clean)) return true;
  if (/^["']?[\w .:/\\@-]+["']?\s*:\s*(?:["'][^"']{0,200}["']|[{}\[\],]|null|true|false|\d+)?\s*,?$/.test(clean)) return true;
  if (/^[\w .:/\\@_]+,?$/.test(clean) && /(?:all_keys|manual_key|message|contact|session|database|db|salt|hmac|note|export)/i.test(clean)) return true;
  return false;
}

function manualKeyInvalidFragments(value) {
  const text = String(value || '');
  const matches = manualKeyTextMatches(text);
  const invalid = [];
  const seen = new Set();
  const addInvalid = value => {
    const compact = String(value || '').trim().replace(/\s+/g, ' ').slice(0, 120);
    if (!compact || seen.has(compact)) return;
    seen.add(compact);
    invalid.push(invalid.length + 1);
  };
  for (const item of manualKeyCandidateMatches(text)) {
    if (normalizeManualKeyTokens(item.token).length > 0) continue;
    addInvalid(item.token);
  }
  let offset = 0;
  for (const rawLine of text.split(/\r?\n/)) {
    const lineStart = offset;
    const lineEnd = offset + rawLine.length;
    offset = lineEnd + 1;
    const clean = rawLine.trim();
    if (!clean) continue;
    const hasKey = matches.some(item => item.index < lineEnd && item.end > lineStart);
    if (hasKey || manualKeyContextLine(clean)) continue;
    addInvalid(clean);
  }
  return invalid;
}

function normalizeManualKeysText(value) {
  const text = String(value || '').trim();
  const keys = splitManualKeysText(value);
  const invalid = text ? manualKeyInvalidFragments(value) : [];
  if (text && !keys.length && !invalid.length) invalid.push(text);
  return { keys, invalid, text: keys.join('\n') };
}

function manualKeyInvalidMessage(manualKeys = {}) {
  const invalid = Array.isArray(manualKeys.invalid) ? manualKeys.invalid : [];
  return `✗ 手动密钥里检测到 ${invalid.length || 1} 处未识别的行/片段。为避免泄露密钥，错误信息不会回显原文；请删除无效行，或填写 64/96/128/160/192 位 hex、all_keys.json、导出 blob、x\u0027...\u0027 / 0x... 片段`;
}

function normalizeManualKeyTokens(value) {
  const text = String(value || '').trim().toLowerCase().replace(/^['"`]+|['"`]+$/g, '');
  if (/^[a-f0-9]{192}$/.test(text)) {
    return [text];
  }
  return /^(?:[a-f0-9]{64}|[a-f0-9]{96}|[a-f0-9]{128}|[a-f0-9]{160})$/.test(text) ? [text] : [];
}

function isHexCharCode(code) {
  return (code >= 0x30 && code <= 0x39)
    || (code >= 0x41 && code <= 0x46)
    || (code >= 0x61 && code <= 0x66);
}

function fmtTimeAgo(ts, status = '') {
  const state = String(status || '').trim();
  if (state === 'session_unavailable' || state === 'unknown') return '消息时间未知';
  if (state === 'untrusted_time') return '消息时间异常';
  const value = Number(ts || 0);
  if (!Number.isFinite(value) || value < 946684800000) return '消息时间未知';
  const d = Math.max(0, Date.now() - value);
  const m = Math.floor(d / 60000);
  if (m < 1) return '刚刚';
  if (m < 60) return `${m} 分钟前`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h} 小时前`;
  return `${Math.floor(h / 24)} 天前`;
}

function padTimePart(value) {
  return String(Math.max(0, Number(value || 0) || 0)).padStart(2, '0');
}

function formatGroupExactTime(ts, status = '') {
  const state = String(status || '').trim();
  if (state === 'session_unavailable' || state === 'untrusted_time') return '';
  const value = Number(ts || 0);
  if (!Number.isFinite(value) || value < 946684800000) return '';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return '';
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const day = new Date(date);
  day.setHours(0, 0, 0, 0);
  const diffDays = Math.round((today.getTime() - day.getTime()) / 86400000);
  const time = `${padTimePart(date.getHours())}:${padTimePart(date.getMinutes())}`;
  if (diffDays === 0) return `今天 ${time}`;
  if (diffDays === 1) return `昨天 ${time}`;
  const monthDay = `${padTimePart(date.getMonth() + 1)}-${padTimePart(date.getDate())}`;
  if (date.getFullYear() === new Date().getFullYear()) return `${monthDay} ${time}`;
  return `${date.getFullYear()}-${monthDay} ${time}`;
}

function groupLastMessageStatusHint(status = '') {
  const state = String(status || '').trim();
  if (state === 'session_unavailable') return '最近消息数据暂不可用，排序可能不完整';
  if (state === 'untrusted_time') return '最近消息时间来自异常字段，不能作为可靠排序依据';
  if (state === 'unknown') return '未读取到可信最近消息时间';
  return '';
}

function groupLastMessageMetaText(group = {}) {
  const relative = fmtTimeAgo(group.last_msg_at, group.last_msg_status);
  const exact = formatGroupExactTime(group.last_msg_at, group.last_msg_status);
  return exact ? `${relative} · ${exact}` : relative;
}

function groupListItemTitle(group = {}) {
  const name = String(group.name || group.id || '').trim();
  const relative = fmtTimeAgo(group.last_msg_at, group.last_msg_status);
  const exact = formatGroupExactTime(group.last_msg_at, group.last_msg_status);
  const parts = [
    name,
    exact ? `最近消息：${exact}（${relative}）` : `最近消息：${relative}`,
    groupLastMessageStatusHint(group.last_msg_status),
    Number(group.members || 0) > 0 ? `成员：${Number(group.members || 0)}` : '',
    Number(group.unread_count || 0) > 0 ? `未读：${Number(group.unread_count || 0)}` : '',
  ].filter(Boolean);
  return parts.join('；');
}

const QUICK_RANGE_LABELS = {
  today: '今天',
  yesterday: '昨天',
  yesterdayToday: '昨天+今天',
  last4h: '最近 4h',
  last12h: '最近 12h',
  last1d: '最近 24h',
  thisweek: '本周',
  custom: '自定义',
};

function quickRangeToDates(key) {
  const now = new Date();
  const since = new Date(now);
  let includeSeconds = true;
  if (key === 'today') since.setHours(0, 0, 0, 0);
  else if (key === 'yesterday') {
    since.setDate(since.getDate() - 1);
    since.setHours(0, 0, 0, 0);
    now.setTime(since.getTime());
    now.setHours(23, 59, 59, 0);
  } else if (key === 'yesterdayToday') {
    since.setDate(since.getDate() - 1);
    since.setHours(0, 0, 0, 0);
  } else if (key === 'last4h') since.setTime(now.getTime() - 4 * 60 * 60 * 1000);
  else if (key === 'last12h') since.setTime(now.getTime() - 12 * 60 * 60 * 1000);
  else if (key === 'last1d') since.setTime(now.getTime() - 24 * 60 * 60 * 1000);
  else if (key === 'thisweek') {
    const day = now.getDay() || 7;
    since.setDate(now.getDate() - (day - 1));
    since.setHours(0, 0, 0, 0);
  }
  return { since: fmtDateTime(since, { includeSeconds }), until: fmtDateTime(now, { includeSeconds }) };
}

function digestRangeLabel(key = _state_digest.rangeKey) {
  return QUICK_RANGE_LABELS[key] || QUICK_RANGE_LABELS.yesterdayToday;
}

function currentDigestRange() {
  if (_state_digest.rangeKey === 'custom') {
    ensureCustomRangeDefaults();
    return { since: _state_digest.customSince, until: _state_digest.customUntil || 'now' };
  }
  return quickRangeToDates(_state_digest.rangeKey);
}

function captureDigestRangeForRun() {
  const key = String(_state_digest.rangeKey || '').trim() || 'yesterdayToday';
  const current = currentDigestRange();
  const since = String(current?.since || '').trim();
  const until = String(current?.until || '').trim();
  return {
    key,
    range: {
      since,
      // A custom "now" must mean the instant the user clicked, not the later request time.
      until: until === 'now' ? fmtDateTime(new Date(), { includeSeconds: true }) : until,
    },
  };
}

function digestRangePreflightError(range = {}) {
  const since = String(range?.since || '').trim();
  const until = String(range?.until || '').trim();
  const start = parseLocalDateTime(since);
  const end = parseLocalDateTime(until, { endOfMinuteWhenSecondsMissing: true, endOfSecond: true });
  if (!start || !end) {
    return {
      code: 'digest_range_invalid_date',
      message: '本次时间范围无效，请重新选择开始和结束时间。',
    };
  }
  if (start.getTime() > end.getTime()) {
    return {
      code: 'digest_range_reversed',
      message: '开始时间不能晚于结束时间，请调整后再生成。',
    };
  }
  if (start.getTime() > Date.now() + 60_000) {
    return {
      code: 'digest_range_starts_in_future',
      message: '开始时间晚于当前时间；这个时间窗还没有本机微信消息，请选择当前时间之前的范围。',
    };
  }
  return null;
}

function activeDigestRangeForSummary() {
  if (!_state_digest.generating) return null;
  const range = _state_digest.activeRange;
  const since = String(range?.since || '').trim();
  const until = String(range?.until || '').trim();
  if (!since || !until) return null;
  return {
    key: String(_state_digest.activeRangeKey || _state_digest.rangeKey || '').trim() || 'yesterdayToday',
    range: { since, until },
  };
}

function clearActiveDigestRangeSnapshot() {
  _state_digest.activeRangeKey = '';
  _state_digest.activeRange = null;
  updateDigestRangeSummary();
}

function updateDigestRangeSummary() {
  const el = document.getElementById('range-summary');
  if (!el) return;
  const active = activeDigestRangeForSummary();
  const range = active?.range || currentDigestRange();
  const rangeKey = active?.key || _state_digest.rangeKey;
  const adjustment = String(_state_digest.customRangeAdjustment || '').trim();
  el.classList.toggle('warn', !!adjustment);
  el.textContent = `${digestRangeLabel(rangeKey)}${active ? '（本次已锁定）' : ''}：${range.since} ~ ${range.until}${adjustment ? `。${adjustment}` : ''}`;
}

function digestRangeSummaryUsesCurrentTime(key = _state_digest.rangeKey) {
  return !['custom', 'yesterday'].includes(String(key || ''));
}

function refreshDigestRangeSummary() {
  if (activeDigestRangeForSummary()) {
    updateDigestRangeSummary();
    return;
  }
  if (!digestRangeSummaryUsesCurrentTime()) return;
  updateDigestRangeSummary();
}

function startDigestRangeSummaryTimer() {
  stopDigestRangeSummaryTimer();
  refreshDigestRangeSummary();
  _digestRangeSummaryTimer = setInterval(refreshDigestRangeSummary, DIGEST_RANGE_SUMMARY_REFRESH_MS);
}

function stopDigestRangeSummaryTimer() {
  if (!_digestRangeSummaryTimer) return;
  clearInterval(_digestRangeSummaryTimer);
  _digestRangeSummaryTimer = null;
}

function fmtDateTime(d, { includeSeconds = false } = {}) {
  const pad = n => String(n).padStart(2, '0');
  const base = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
  return includeSeconds ? `${base}:${pad(d.getSeconds())}` : base;
}

const SUPERSCRIPT_RENDER_MAP = {
  '⁰': '0', '¹': '1', '²': '2', '³': '3', '⁴': '4', '⁵': '5', '⁶': '6', '⁷': '7', '⁸': '8', '⁹': '9',
  'ᴬ': 'A', 'ᴮ': 'B', 'ᴰ': 'D', 'ᴱ': 'E', 'ᴳ': 'G', 'ᴴ': 'H', 'ᴵ': 'I', 'ᴶ': 'J', 'ᴷ': 'K', 'ᴸ': 'L',
  'ᴹ': 'M', 'ᴺ': 'N', 'ᴼ': 'O', 'ᴾ': 'P', 'ᴿ': 'R', 'ᵀ': 'T', 'ᵁ': 'U', 'ⱽ': 'V', 'ᵂ': 'W',
  'ᵃ': 'a', 'ᵇ': 'b', 'ᶜ': 'c', 'ᵈ': 'd', 'ᵉ': 'e', 'ᶠ': 'f', 'ᵍ': 'g', 'ʰ': 'h', 'ⁱ': 'i', 'ʲ': 'j',
  'ᵏ': 'k', 'ˡ': 'l', 'ᵐ': 'm', 'ⁿ': 'n', 'ᵒ': 'o', 'ᵖ': 'p', 'ʳ': 'r', 'ˢ': 's', 'ᵗ': 't', 'ᵘ': 'u',
  'ᵛ': 'v', 'ʷ': 'w', 'ˣ': 'x', 'ʸ': 'y', 'ᶻ': 'z',
};

function normalizeDecorativeGlyph(ch) {
  if (!ch || typeof ch.normalize !== 'function') return ch;
  const normalized = ch.normalize('NFKC');
  return normalized !== ch && /^[A-Za-z0-9 ()+./_-]+$/.test(normalized) ? normalized : ch;
}

function renderSafeText(text) {
  return String(text ?? '')
    .replace(/[\u{1F1E6}-\u{1F1FF}]/gu, ch => String.fromCharCode(ch.codePointAt(0) - 0x1F1E6 + 65))
    .replace(/([0-9#*])\uFE0F?\u20E3/g, '$1')
    .replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹ᴬᴮᴰᴱᴳᴴᴵᴶᴷᴸᴹᴺᴼᴾᴿᵀᵁⱽᵂᵃᵇᶜᵈᵉᶠᵍʰⁱʲᵏˡᵐⁿᵒᵖʳˢᵗᵘᵛʷˣʸᶻ]/g, ch => SUPERSCRIPT_RENDER_MAP[ch] || ch)
    .replace(/[\u{1D400}-\u{1D7FF}\u{2100}-\u{214F}\u{2460}-\u{24FF}]/gu, normalizeDecorativeGlyph)
    .replace(/\u1BE4/g, '')
    .replace(/\uFE0F/g, '')
    .replace(/(?<![A-Za-z])(?:[A-Z]\s+){2,}[A-Z](?![A-Za-z])/g, m => m.replace(/\s+/g, ''));
}

const GRAPHEME_SEGMENTER = typeof Intl !== 'undefined' && Intl.Segmenter
  ? new Intl.Segmenter('zh-Hans', { granularity: 'grapheme' })
  : null;

function splitGraphemes(text) {
  const value = String(text ?? '');
  if (!GRAPHEME_SEGMENTER) return Array.from(value);
  return Array.from(GRAPHEME_SEGMENTER.segment(value), item => item.segment);
}

function parseDurationParts(value, fallback = '30m') {
  const raw = String(value || fallback || '').trim().toLowerCase();
  const match = raw.match(/^(\d+)\s*([mhd])$/);
  if (!match) return parseDurationParts(fallback === raw ? '30m' : fallback, '30m');
  const amount = Math.max(1, Math.min(999, parseInt(match[1], 10) || 1));
  return { amount, unit: match[2] };
}

function durationPartScale(unit) {
  return unit === 'm' ? 60 * 1000 : unit === 'h' ? 60 * 60 * 1000 : 24 * 60 * 60 * 1000;
}

function setDurationControl(fieldId, value, fallback) {
  const parts = parseDurationParts(value, fallback);
  const hidden = document.getElementById(fieldId);
  const amount = document.getElementById(`${fieldId}-value`);
  const unit = document.getElementById(`${fieldId}-unit`);
  if (hidden) hidden.value = `${parts.amount}${parts.unit}`;
  if (amount) amount.value = parts.amount;
  if (unit) unit.value = parts.unit;
}

function getDurationControlValue(fieldId, fallback, { maxMs = 0 } = {}) {
  const fallbackParts = parseDurationParts(fallback);
  let amount = Math.max(1, Math.min(999, parseInt(document.getElementById(`${fieldId}-value`)?.value || '', 10) || fallbackParts.amount));
  const unit = ['m', 'h', 'd'].includes(document.getElementById(`${fieldId}-unit`)?.value)
    ? document.getElementById(`${fieldId}-unit`).value
    : fallbackParts.unit;
  if (maxMs) {
    const maxAmount = Math.max(1, Math.floor(maxMs / durationPartScale(unit)));
    amount = Math.min(amount, maxAmount);
  }
  const value = `${amount}${unit}`;
  const hidden = document.getElementById(fieldId);
  if (hidden) hidden.value = value;
  const amountInput = document.getElementById(`${fieldId}-value`);
  if (amountInput) amountInput.value = amount;
  return value;
}

function durationControlValidationMessage(fieldId, label) {
  const input = document.getElementById(`${fieldId}-value`);
  if (!input) return '';
  const raw = String(input.value || '').trim();
  let message = '';
  if (!raw) message = `${label}不能为空，请填写大于 0 的整数`;
  else if (!/^\d+$/.test(raw) || !Number.isSafeInteger(Number(raw)) || Number(raw) < 1) {
    message = `${label}必须是大于 0 的整数`;
  }
  if (message) input.setAttribute('aria-invalid', 'true');
  else input.removeAttribute('aria-invalid');
  return message;
}

function busyButtonFocusSnapshot(button) {
  if (!button) return null;
  const id = String(button.id || '').trim();
  const key = String(button.dataset?.busyFocusKey || '').trim();
  if (!id && !key) return null;
  return {
    id,
    key,
    scopeId: String(button.closest?.('[id]')?.id || '').trim(),
  };
}

function resolveBusyButtonFocusTarget(snapshot) {
  if (!snapshot) return null;
  if (snapshot.id) {
    const byId = document.getElementById(snapshot.id);
    if (byId) return byId;
  }
  if (!snapshot.key) return null;
  const scope = snapshot.scopeId ? document.getElementById(snapshot.scopeId) : document;
  return [...(scope?.querySelectorAll?.('[data-busy-focus-key]') || [])]
    .find(candidate => String(candidate.dataset?.busyFocusKey || '') === snapshot.key) || null;
}

function busyButtonOwnsFallbackFocus(snapshot, active) {
  if (!snapshot?.scopeId || !active) return false;
  const scope = document.getElementById(snapshot.scopeId);
  if (!scope?.contains(active) && active !== scope) return false;
  return active === scope
    || active.matches?.('[data-batch-result-index][tabindex="-1"], [role="status"][tabindex="-1"], [role="alert"][tabindex="-1"]');
}

async function withBusyButtons(buttons, action) {
  const items = (Array.isArray(buttons) ? buttons : [buttons]).filter(Boolean);
  if (items.some(button => button.dataset.busy === '1')) return undefined;
  const focusedButton = items.find(button => button === document.activeElement) || null;
  const focusSnapshot = focusedButton ? busyButtonFocusSnapshot(focusedButton) : null;
  for (const button of items) {
    button.dataset.busy = '1';
    button.setAttribute('aria-busy', 'true');
    button.disabled = true;
  }
  let busyFocusTimer = null;
  let busyFallbackFocused = null;
  if (focusedButton) {
    busyFocusTimer = setTimeout(() => {
      const active = document.activeElement;
      if (active && active !== document.body && active !== document.documentElement && active !== focusedButton) {
        if (busyButtonOwnsFallbackFocus(focusSnapshot, active)) busyFallbackFocused = active;
        return;
      }
      const replacement = resolveBusyButtonFocusTarget(focusSnapshot);
      const section = replacement?.closest?.('[data-settings-section], .modal-backdrop, .card')
        || (focusSnapshot?.scopeId ? document.getElementById(focusSnapshot.scopeId) : null)
        || focusedButton.closest?.('[data-settings-section], .modal-backdrop, .card');
      let target = [...(section?.querySelectorAll?.('.busy-cancel:not(.hidden):not([disabled])') || [])]
        .find(item => item.offsetParent !== null);
      if (!target) {
        target = [...(section?.querySelectorAll?.('[role="status"], [role="alert"]') || [])]
          .find(item => String(item.textContent || '').trim() && !item.closest('[hidden]')) || null;
        if (target && !target.hasAttribute('tabindex')) target.setAttribute('tabindex', '-1');
      }
      if (!target && section?.isConnected) {
        target = section;
        if (!target.hasAttribute('tabindex')) target.setAttribute('tabindex', '-1');
      }
      if (target?.isConnected) {
        target.focus?.({ preventScroll: true });
        busyFallbackFocused = target;
      }
    }, 300);
  }
  try {
    return await action();
  } finally {
    if (busyFocusTimer) clearTimeout(busyFocusTimer);
    const modalSyncTargets = new Set();
    for (const button of items) {
      delete button.dataset.busy;
      button.removeAttribute('aria-busy');
      if (!button.isConnected) continue;
      button.disabled = button.dataset.keepDisabled === '1';
      const modal = button.closest?.('.modal-backdrop');
      if (modal && typeof modal._syncAfterBusyButtons === 'function') modalSyncTargets.add(modal);
    }
    for (const modal of modalSyncTargets) {
      try { modal._syncAfterBusyButtons(); } catch {}
    }
    syncDigestActionButtonsAfterAsync();
    if (focusedButton) {
      requestAnimationFrame(() => {
        const active = document.activeElement;
        if (active
          && active !== document.body
          && active !== document.documentElement
          && active !== focusedButton
          && active !== busyFallbackFocused
          && !busyButtonOwnsFallbackFocus(focusSnapshot, active)) return;
        const replacement = resolveBusyButtonFocusTarget(focusSnapshot);
        let target = replacement?.disabled ? null : replacement;
        if (!target && focusedButton.isConnected && !focusedButton.disabled) target = focusedButton;
        if (!target) {
          const section = replacement?.closest?.('[data-settings-section], .modal-backdrop, .card')
            || (focusSnapshot?.scopeId ? document.getElementById(focusSnapshot.scopeId) : null)
            || focusedButton.closest?.('[data-settings-section], .modal-backdrop, .card');
          const statuses = [...(section?.querySelectorAll?.('[role="status"], [role="alert"]') || [])];
          target = statuses.find(item => String(item.textContent || '').trim() && !item.closest('[hidden]'))
            || section?.querySelector?.('[data-close]:not(:disabled), button:not(:disabled)')
            || section?.querySelector?.('h3')
            || null;
          if (target && !target.hasAttribute('tabindex')) target.setAttribute('tabindex', '-1');
        }
        if (!target?.isConnected || target.disabled) return;
        try { target.focus({ preventScroll: true }); } catch { target.focus?.(); }
      });
    }
  }
}

function markInvalidFormFields(status, message, fields = []) {
  const invalid = [...new Set((Array.isArray(fields) ? fields : [fields]).filter(field => field?.isConnected))];
  if (!invalid.length) return false;
  if (status) {
    status.className = 'status err';
    status.textContent = String(message || '请检查标记的字段');
    if (!status.id) status.id = `field-error-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`;
  }
  for (const field of invalid) {
    field.setAttribute('aria-invalid', 'true');
    if (status?.id) field.setAttribute('aria-errormessage', status.id);
    if (field.dataset.fieldValidationClearBound !== '1') {
      field.dataset.fieldValidationClearBound = '1';
      const clear = () => {
        field.removeAttribute('aria-invalid');
        field.removeAttribute('aria-errormessage');
      };
      field.addEventListener('input', clear);
      field.addEventListener('change', clear);
    }
  }
  const first = invalid[0];
  requestAnimationFrame(() => {
    if (!first.isConnected) return;
    try { first.focus({ preventScroll: false }); } catch { first.focus?.(); }
  });
  return true;
}

function syncDigestActionButtonsAfterAsync() {
  if (document.getElementById('digest-canvas') || document.getElementById('preview-card')) {
    updateDigestPreviewActionLock();
  }
  if (document.getElementById('text-preview-card')) {
    syncTextPreviewCopyButton();
    syncTextPreviewExportButton();
    syncTextPreviewDownloadButton();
    syncTextPreviewRevealButton();
  }
}

function setButtonKeepDisabled(button, disabled) {
  if (!button) return;
  if (disabled) button.dataset.keepDisabled = '1';
  else delete button.dataset.keepDisabled;
  button.disabled = !!disabled || button.dataset.busy === '1';
}

function browserBlobDownloadSupported() {
  return browserDownloadCapability({ requireObjectUrl: true }).supported;
}

function syncBrowserDownloadOnlyButton(button, {
  available = true,
  availableTitle = '',
  unavailableTitle = '',
  artifactLabel = '文件',
  savedArtifact = false,
  revealSupported = false,
  copySupported = false,
  copyLabel = '复制内容',
} = {}) {
  if (!button) return false;
  const downloadSupported = browserBlobDownloadSupported();
  const enabled = !!available && downloadSupported;
  setButtonKeepDisabled(button, !enabled);
  button.setAttribute('aria-disabled', enabled ? 'false' : 'true');
  button.title = !available
    ? String(unavailableTitle || `${artifactLabel}暂不可下载`).trim()
    : (downloadSupported
      ? String(availableTitle || `下载${artifactLabel}`).trim()
      : browserDownloadUnsupportedMessage({
        artifactLabel,
        savedArtifact,
        revealSupported,
        copySupported,
        copyLabel,
      }));
  return enabled;
}

function normalizeAiConcurrency(value) {
  const parsed = parseStrictIntegerInput(value ?? '2', { min: 1, max: AI_CONCURRENCY_MAX, clamp: true });
  return parsed.ok ? parsed.value : 2;
}

function clampAiConcurrencyInput(input = document.getElementById('s-ai-concurrency')) {
  if (!input) return { value: 2, clamped: false, invalid: false };
  const before = String(input.value || '').trim();
  const parsed = parseStrictIntegerInput(before, { min: 1, max: AI_CONCURRENCY_MAX, clamp: true });
  input.setAttribute('aria-invalid', parsed.ok ? 'false' : 'true');
  if (!parsed.ok) return { value: null, clamped: false, invalid: true, reason: parsed.reason };
  input.value = parsed.value;
  return { value: parsed.value, clamped: parsed.clamped, invalid: false };
}

function fmtMonthTitle(date) {
  return `${date.getFullYear()} 年 ${date.getMonth() + 1} 月`;
}

function sameDay(a, b) {
  return a && b
    && a.getFullYear() === b.getFullYear()
    && a.getMonth() === b.getMonth()
    && a.getDate() === b.getDate();
}

function monthKey(date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
}

function setupCustomRangePicker() {
  const startButton = document.getElementById('range-start');
  const endButton = document.getElementById('range-end');
  const popover = document.getElementById('range-popover');
  const picker = document.getElementById('range-picker');
  if (!startButton || !endButton || !popover || !picker) return;

  const hour = document.getElementById('range-hour');
  const minute = document.getElementById('range-minute');
  hour.innerHTML = Array.from({ length: 24 }, (_, i) => `<option value="${String(i).padStart(2, '0')}">${String(i).padStart(2, '0')}</option>`).join('');
  minute.innerHTML = Array.from({ length: 12 }, (_, i) => {
    const value = String(i * 5).padStart(2, '0');
    return `<option value="${value}">${value}</option>`;
  }).join('');

  function open(side) {
    if (_state_digest.generating) return;
    ensureCustomRangeDefaults();
    _state_digest.customRangeSide = side;
    const selected = parseLocalDateTime(side === 'since' ? _state_digest.customSince : _state_digest.customUntil) || new Date();
    _state_digest.customRangeMonth = monthKey(selected);
    popover.classList.remove('hidden');
    paintCustomRangeFields();
    paintRangeCalendar();
    const selectedDate = fmtDateOnly(selected);
    requestAnimationFrame(() => {
      const focusTarget = popover.querySelector(`button[data-date="${selectedDate}"]`)
        || popover.querySelector('button[data-date]')
        || hour;
      focusTarget?.focus?.();
    });
  }

  startButton.addEventListener('click', () => open('since'));
  endButton.addEventListener('click', () => open('until'));
  popover.addEventListener('keydown', e => {
    if (e.key !== 'Escape') return;
    e.preventDefault();
    e.stopPropagation();
    closeCustomRangePopover({ restoreFocus: true });
  });
  picker.addEventListener('focusout', () => {
    requestAnimationFrame(() => {
      if (!popover.isConnected || popover.classList.contains('hidden')) return;
      if (picker.contains(document.activeElement)) return;
      closeCustomRangePopover();
    });
  });
  document.getElementById('range-prev-month').addEventListener('click', () => shiftRangeMonth(-1));
  document.getElementById('range-next-month').addEventListener('click', () => shiftRangeMonth(1));
  document.getElementById('range-calendar')?.addEventListener('keydown', handleRangeCalendarKeydown);
  hour.addEventListener('change', updateCustomRangeTime);
  minute.addEventListener('change', updateCustomRangeTime);
  ensureCustomRangeOutsideClick();
}

function ensureCustomRangeOutsideClick() {
  if (_customRangeOutsideClickAttached) return;
  document.addEventListener('click', e => {
    const popover = document.getElementById('range-popover');
    if (!popover || popover.classList.contains('hidden')) return;
    if (document.getElementById('range-picker')?.contains(e.target)) return;
    closeCustomRangePopover();
  });
  document.addEventListener('keydown', e => {
    if (e.key !== 'Escape') return;
    const popover = document.getElementById('range-popover');
    if (!popover || popover.classList.contains('hidden')) return;
    e.preventDefault();
    closeCustomRangePopover({ restoreFocus: true });
  });
  _customRangeOutsideClickAttached = true;
}

function updateCustomRangePopoverState() {
  const popover = document.getElementById('range-popover');
  const open = !!popover && !popover.classList.contains('hidden');
  const side = _state_digest.customRangeSide;
  const startButton = document.getElementById('range-start');
  const endButton = document.getElementById('range-end');
  startButton?.setAttribute('aria-expanded', open && side === 'since' ? 'true' : 'false');
  endButton?.setAttribute('aria-expanded', open && side === 'until' ? 'true' : 'false');
}

function closeCustomRangePopover({ restoreFocus = false } = {}) {
  const popover = document.getElementById('range-popover');
  if (!popover) return;
  popover.classList.add('hidden');
  document.getElementById('range-start')?.classList.remove('active');
  document.getElementById('range-end')?.classList.remove('active');
  updateCustomRangePopoverState();
  if (restoreFocus) {
    const target = document.getElementById(_state_digest.customRangeSide === 'until' ? 'range-end' : 'range-start');
    target?.focus?.();
  }
}

function ensureCustomRangeDefaults() {
  if (_state_digest.customSince && _state_digest.customUntil) return;
  const r = quickRangeToDates('yesterdayToday');
  _state_digest.customSince = _state_digest.customSince || r.since;
  _state_digest.customUntil = _state_digest.customUntil || r.until;
}

function normalizeCustomRangeMinutes() {
  const since = parseLocalDateTime(_state_digest.customSince);
  if (since) {
    since.setSeconds(0, 0);
    _state_digest.customSince = fmtDateTime(since);
  }
  const until = parseLocalDateTime(_state_digest.customUntil);
  if (until) {
    until.setSeconds(59, 0);
    _state_digest.customUntil = fmtDateTime(until, { includeSeconds: true });
  }
}

function paintCustomRangeFields() {
  const start = document.getElementById('range-start-text');
  const end = document.getElementById('range-end-text');
  if (start) start.textContent = _state_digest.customSince || '';
  if (end) end.textContent = _state_digest.customUntil || '';
  const popoverOpen = !document.getElementById('range-popover')?.classList.contains('hidden');
  const startButton = document.getElementById('range-start');
  const endButton = document.getElementById('range-end');
  startButton?.classList.toggle('active', _state_digest.customRangeSide === 'since' && popoverOpen);
  endButton?.classList.toggle('active', _state_digest.customRangeSide === 'until' && popoverOpen);
  startButton?.setAttribute('aria-label', `开始时间 ${_state_digest.customSince || '未设置'}`);
  endButton?.setAttribute('aria-label', `结束时间 ${_state_digest.customUntil || '未设置'}`);
  updateCustomRangePopoverState();
}

function shiftRangeMonth(delta) {
  if (_state_digest.generating) return;
  const base = rangeCalendarMonth();
  base.setMonth(base.getMonth() + delta);
  _state_digest.customRangeMonth = monthKey(base);
  paintRangeCalendar();
}

function rangeCalendarMonth() {
  if (_state_digest.customRangeMonth) {
    const [y, m] = _state_digest.customRangeMonth.split('-').map(Number);
    if (y && m) return new Date(y, m - 1, 1);
  }
  return new Date(new Date().getFullYear(), new Date().getMonth(), 1);
}

function paintRangeCalendar({ focusDate = '' } = {}) {
  const grid = document.getElementById('range-calendar');
  const title = document.getElementById('range-month-title');
  if (!grid || !title) return;
  const month = rangeCalendarMonth();
  title.textContent = fmtMonthTitle(month);
  const startDate = parseLocalDateTime(_state_digest.customSince);
  const endDate = parseLocalDateTime(_state_digest.customUntil);
  const sideDate = parseLocalDateTime(_state_digest.customRangeSide === 'since' ? _state_digest.customSince : _state_digest.customUntil) || new Date();
  document.getElementById('range-hour').value = String(sideDate.getHours()).padStart(2, '0');
  document.getElementById('range-minute').value = String(Math.floor(sideDate.getMinutes() / 5) * 5).padStart(2, '0');

  const first = new Date(month.getFullYear(), month.getMonth(), 1);
  const offset = (first.getDay() + 6) % 7;
  const firstCell = new Date(first);
  firstCell.setDate(first.getDate() - offset);
  const activeDate = grid.contains(document.activeElement)
    ? String(document.activeElement?.dataset?.date || '').trim()
    : '';
  const dates = Array.from({ length: 42 }, (_, i) => {
    const date = new Date(firstCell);
    date.setDate(firstCell.getDate() + i);
    return date;
  });
  const availableDates = new Set(dates.map(fmtDateOnly));
  const preferredDate = String(focusDate || activeDate || fmtDateOnly(sideDate)).trim();
  const rovingDate = availableDates.has(preferredDate)
    ? preferredDate
    : (availableDates.has(fmtDateOnly(sideDate)) ? fmtDateOnly(sideDate) : fmtDateOnly(dates[0]));
  const cells = [];
  for (const date of dates) {
    const muted = date.getMonth() !== month.getMonth();
    const selectingEnd = _state_digest.customRangeSide === 'until';
    const sideDateValue = selectingEnd ? endDate : startDate;
    const otherDateValue = selectingEnd ? startDate : endDate;
    const sideSelected = sameDay(date, sideDateValue);
    const otherEndpoint = sameDay(date, otherDateValue);
    const selected = sideSelected || otherEndpoint;
    const inRange = startDate && endDate && date >= stripTime(startDate) && date <= stripTime(endDate);
    const dateText = fmtDateOnly(date);
    const sideLabel = selectingEnd ? '结束' : '开始';
    const otherLabel = selectingEnd ? '开始' : '结束';
    const stateLabel = sideSelected
      ? `，当前${sideLabel}日期`
      : (otherEndpoint ? `，当前${otherLabel}日期` : (inRange ? '，在当前范围内' : ''));
    cells.push(`<button type="button" data-date="${dateText}" tabindex="${dateText === rovingDate ? '0' : '-1'}" aria-label="选择${sideLabel}日期 ${dateText}${stateLabel}" aria-pressed="${sideSelected ? 'true' : 'false'}" class="${[
      muted ? 'muted-day' : '',
      selected ? 'selected' : '',
      inRange && !selected ? 'in-range' : '',
    ].filter(Boolean).join(' ')}">${date.getDate()}</button>`);
  }
  grid.innerHTML = cells.join('');
  grid.querySelectorAll('button[data-date]').forEach(button => {
    button.addEventListener('click', () => updateCustomRangeDate(button.dataset.date));
  });
  paintCustomRangeFields();
  if (focusDate || activeDate) {
    requestAnimationFrame(() => grid.querySelector(`button[data-date="${rovingDate}"]`)?.focus?.());
  }
}

function handleRangeCalendarKeydown(event) {
  const button = event.target?.closest?.('button[data-date]');
  if (!button || !event.currentTarget?.contains?.(button)) return;
  const current = parseLocalDateTime(`${button.dataset.date} 00:00`);
  if (!current) return;
  const next = new Date(current);
  let handled = true;
  if (event.key === 'ArrowLeft') next.setDate(next.getDate() - 1);
  else if (event.key === 'ArrowRight') next.setDate(next.getDate() + 1);
  else if (event.key === 'ArrowUp') next.setDate(next.getDate() - 7);
  else if (event.key === 'ArrowDown') next.setDate(next.getDate() + 7);
  else if (event.key === 'Home') next.setDate(next.getDate() - ((next.getDay() + 6) % 7));
  else if (event.key === 'End') next.setDate(next.getDate() + (6 - ((next.getDay() + 6) % 7)));
  else if (event.key === 'PageUp' || event.key === 'PageDown') {
    const monthDelta = (event.key === 'PageUp' ? -1 : 1) * (event.shiftKey ? 12 : 1);
    const day = next.getDate();
    const targetMonth = new Date(next.getFullYear(), next.getMonth() + monthDelta, 1);
    const lastDay = new Date(targetMonth.getFullYear(), targetMonth.getMonth() + 1, 0).getDate();
    next.setFullYear(targetMonth.getFullYear(), targetMonth.getMonth(), Math.min(day, lastDay));
  } else {
    handled = false;
  }
  if (!handled) return;
  event.preventDefault();
  _state_digest.customRangeMonth = monthKey(next);
  paintRangeCalendar({ focusDate: fmtDateOnly(next) });
}

function stripTime(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function fmtDateOnly(date) {
  const pad = n => String(n).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

function normalizePathForUi(value) {
  return String(value || '').trim().replaceAll('\\', '/').replace(/\/+/g, '/').replace(/\/$/, '');
}

function normalizeRelativePathForUi(value) {
  return normalizePathForUi(value).replace(/^\.\/+/, '');
}

function isAbsolutePathForUi(value) {
  const s = String(value || '').trim();
  return /^[a-zA-Z]:[\\/]/.test(s) || s.startsWith('/') || s.startsWith('\\\\');
}

function platformPathIdentityForUi(value = '', platform = _appState?.platform) {
  const text = String(value || '');
  return platform === 'win32' ? text.toLowerCase() : text;
}

function outputDirLooksInsideProject(dir, projectRoot) {
  const raw = String(dir || '').trim();
  if (!raw) return false;
  const normalized = normalizePathForUi(raw);
  if (!isAbsolutePathForUi(raw)) {
    const rel = platformPathIdentityForUi(normalizeRelativePathForUi(raw));
    return rel.startsWith('outputs/')
      && !rel.split('/').includes('..')
      && rel !== 'outputs'
      && rel !== 'outputs/.tmp'
      && !rel.startsWith('outputs/.tmp/');
  }
  if (!projectRoot) return false;
  const root = platformPathIdentityForUi(normalizePathForUi(projectRoot));
  const full = platformPathIdentityForUi(normalizePathForUi(raw));
  if (full.split('/').includes('..')) return false;
  const outputs = root ? `${root}/outputs` : '';
  const tmp = root ? `${root}/outputs/.tmp` : '';
  return !!root && full.startsWith(`${outputs}/`) && full !== outputs && full !== tmp && !full.startsWith(`${tmp}/`);
}

function outputDirIdentityForUi(dir, projectRoot) {
  const raw = String(dir || '').trim();
  if (!raw) return '';
  if (!isAbsolutePathForUi(raw)) return platformPathIdentityForUi(normalizeRelativePathForUi(raw));
  const root = platformPathIdentityForUi(normalizePathForUi(projectRoot));
  if (!root) return platformPathIdentityForUi(normalizePathForUi(raw));
  const full = platformPathIdentityForUi(normalizePathForUi(raw));
  if (full === root) return '';
  return full.startsWith(`${root}/`) ? full.slice(root.length + 1) : full;
}

function outputDirValidationMessage(dir, projectRoot) {
  if (isAbsolutePathForUi(dir) && !String(projectRoot || '').trim()) {
    return '✗ 正在读取项目根目录，请稍后重试';
  }
  return '✗ 输出目录请放在项目 outputs 子目录内，且不能位于 outputs/.tmp';
}

function updateCustomRangeDate(dateText) {
  if (_state_digest.generating) return;
  const [y, m, d] = String(dateText).split('-').map(Number);
  const isUntil = _state_digest.customRangeSide === 'until';
  const next = new Date(y, m - 1, d, isUntil ? 23 : 0, isUntil ? 59 : 0, isUntil ? 59 : 0, 0);
  commitCustomRangeSide(next);
}

function updateCustomRangeTime() {
  if (_state_digest.generating) return;
  const current = parseLocalDateTime(_state_digest.customRangeSide === 'since' ? _state_digest.customSince : _state_digest.customUntil) || new Date();
  current.setHours(Number(document.getElementById('range-hour').value || 0));
  current.setMinutes(Number(document.getElementById('range-minute').value || 0));
  commitCustomRangeSide(current);
}

function commitCustomRangeSide(date) {
  let adjustment = '';
  if (_state_digest.customRangeSide === 'since') {
    const start = new Date(date);
    start.setSeconds(0, 0);
    _state_digest.customSince = fmtDateTime(start);
  } else {
    const end = new Date(date);
    end.setSeconds(59, 0);
    _state_digest.customUntil = fmtDateTime(end, { includeSeconds: true });
  }
  const sinceDate = parseLocalDateTime(_state_digest.customSince);
  const untilDate = parseLocalDateTime(_state_digest.customUntil);
  if (sinceDate && untilDate && sinceDate > untilDate) {
    if (_state_digest.customRangeSide === 'since') {
      const end = new Date(sinceDate.getTime() + 60 * 60 * 1000);
      end.setSeconds(59, 0);
      _state_digest.customUntil = fmtDateTime(end, { includeSeconds: true });
      adjustment = `已自动把结束时间调整为 ${_state_digest.customUntil}`;
    } else {
      const start = new Date(untilDate.getTime() - 60 * 60 * 1000);
      start.setSeconds(0, 0);
      _state_digest.customSince = fmtDateTime(start);
      adjustment = `已自动把开始时间调整为 ${_state_digest.customSince}`;
    }
  }
  _state_digest.customRangeAdjustment = adjustment;
  paintCustomRangeFields();
  paintRangeCalendar();
  updateDigestRangeSummary();
  markDigestResultInputChanged();
}

