function rememberDigestDraftProjectScope(state = _appState) {
  const projectRoot = normalizePathForUi(state?.project_root || '');
  if (projectRoot) {
    _digestDraftPlatform = String(state?.platform || _digestDraftPlatform || '').trim();
    _digestDraftProjectScopeIdentity = platformPathIdentityForUi(projectRoot, _digestDraftPlatform);
  }
  return _digestDraftProjectScopeIdentity;
}

function digestDraftScopeIdentity({ state = _appState, accountId = selectedAccountId() } = {}) {
  const project = rememberDigestDraftProjectScope(state);
  const rawAccount = canonicalAccountIdForValue(accountId) || String(accountId || '').trim();
  const account = platformPathIdentityForUi(rawAccount, state?.platform || _digestDraftPlatform);
  return project && account ? JSON.stringify([project, account]) : '';
}

function digestDraftAccountFingerprint(accountId = selectedAccountId()) {
  return String(accountFingerprintForValue(accountId) || '').trim().toLowerCase();
}

function digestDraftPendingFilterValue(name) {
  const box = document.querySelector(`.chip-input[data-name="${name}"]`);
  const input = box?.querySelector?.('input');
  return String(input?.value ?? _state_digest.pendingFilters?.[name] ?? '').slice(0, 500);
}

function digestDraftStateSnapshot() {
  return {
    selected_group_ids: [...(_state_digest.selectedGroups || [])],
    range_key: _state_digest.rangeKey,
    custom_since: _state_digest.customSince,
    custom_until: _state_digest.customUntil,
    filters: {
      senders: [...(_state_digest.filters?.senders || [])],
      keywords: [...(_state_digest.filters?.keywords || [])],
      exclude_types: [...(_state_digest.filters?.excludeTypes || [])],
      pending_senders: digestDraftPendingFilterValue('senders'),
      pending_keywords: digestDraftPendingFilterValue('keywords'),
    },
    min_messages: readDigestMinMessagesInput(),
  };
}

function applyDigestDraftState(draft = {}) {
  const filters = draft.filters && typeof draft.filters === 'object' && !Array.isArray(draft.filters)
    ? draft.filters
    : {};
  _state_digest.selectedGroups = new Set(Array.isArray(draft.selected_group_ids) ? draft.selected_group_ids : []);
  _state_digest.rangeKey = String(draft.range_key || 'yesterdayToday');
  _state_digest.customSince = String(draft.custom_since || '');
  _state_digest.customUntil = String(draft.custom_until || '');
  _state_digest.customRangeAdjustment = '';
  _state_digest.customRangeSide = 'since';
  _state_digest.customRangeMonth = '';
  _state_digest.filters = {
    senders: Array.isArray(filters.senders) ? [...filters.senders] : [],
    keywords: Array.isArray(filters.keywords) ? [...filters.keywords] : [],
    excludeTypes: new Set(Array.isArray(filters.exclude_types) ? filters.exclude_types : []),
  };
  _state_digest.pendingFilters = {
    senders: String(filters.pending_senders || ''),
    keywords: String(filters.pending_keywords || ''),
  };
  _state_digest.minMessages = Math.max(1, Math.min(DIGEST_MIN_MESSAGES_MAX, Number(draft.min_messages || 1) || 1));
}

function resetDigestDraftInputState() {
  _state_digest.selectedGroups.clear();
  applyDigestDraftState({
    selected_group_ids: [],
    range_key: 'yesterdayToday',
    filters: {},
    min_messages: 1,
  });
  _digestDraftMutationVersion += 1;
  _digestDraftPersistenceFailed = false;
  syncDigestDraftControlsFromState();
}

function persistDigestDraftState({ state = _appState, accountId = selectedAccountId() } = {}) {
  const scope = digestDraftScopeIdentity({ state, accountId });
  if (!scope) return false;
  const accountFingerprint = digestDraftAccountFingerprint(accountId);
  const draft = digestDraftStateSnapshot();
  _digestDraftMemoryCache.set(scope, { draft, account_fingerprint: accountFingerprint });
  const persisted = writeDigestDraftSnapshot(sessionStorage, DIGEST_DRAFT_STORAGE_KEY, scope, draft, {
    accountFingerprint,
  });
  _digestDraftPersistenceFailed = !persisted && digestDraftHasMeaningfulInput(draft);
  return persisted;
}

function restorePersistedDigestDraftState({ state = _appState, accountId = selectedAccountId() } = {}) {
  const scope = digestDraftScopeIdentity({ state, accountId });
  if (!scope) return false;
  const accountFingerprint = digestDraftAccountFingerprint(accountId);
  const memory = _digestDraftMemoryCache.get(scope);
  if (memory?.draft
    && (!accountFingerprint || !memory.account_fingerprint || accountFingerprint === memory.account_fingerprint)) {
    applyDigestDraftState(memory.draft);
    _digestDraftPersistenceFailed = false;
    return true;
  }
  const restored = readDigestDraftSnapshot(sessionStorage, DIGEST_DRAFT_STORAGE_KEY, scope, {
    accountFingerprint,
  });
  if (!restored.ok) {
    _digestDraftPersistenceFailed = digestDraftHasMeaningfulInput(digestDraftStateSnapshot());
    return false;
  }
  if (!restored.draft) return false;
  applyDigestDraftState(restored.draft);
  _digestDraftMemoryCache.set(scope, { draft: restored.draft, account_fingerprint: accountFingerprint });
  _digestDraftPersistenceFailed = false;
  return true;
}

function persistDigestDraftInput() {
  _digestDraftMutationVersion += 1;
  return persistDigestDraftState();
}

function digestDraftPersistenceRisk() {
  return _digestDraftPersistenceFailed && digestDraftHasMeaningfulInput(digestDraftStateSnapshot());
}

async function confirmDigestDraftPersistenceRisk(actionLabel = '切换微信账号') {
  if (!digestDraftPersistenceRisk()) return true;
  return showAppConfirmDialog({
    title: '摘要草稿未能保存',
    messages: [
      '浏览器暂时无法保存当前群选择、时间范围和筛选条件。',
      `${actionLabel}会清空当前账号的内存草稿。`,
    ],
    confirmText: '仍然继续',
    cancelText: '返回检查',
    tone: 'warn',
  });
}

