function normalizeInterruptedDigestBatchTargets(value = null) {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value) || value.length > DIGEST_BATCH_MAX_GROUPS) return null;
  const targets = [];
  for (const raw of value) {
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null;
    const groupId = String(raw.group_id || raw.id || '').trim().slice(0, 240);
    const groupName = String(raw.group_name || raw.name || groupId).trim().slice(0, 240);
    if (!groupId || !groupName) return null;
    targets.push({ group_id: groupId, group_name: groupName });
  }
  return targets;
}

function normalizeInterruptedDigestBatchSupersessions(value = null, currentBatchId = '') {
  if (!Array.isArray(value) || value.length > INTERRUPTED_DIGEST_BATCH_MAX_RECORDS) return [];
  const currentId = String(currentBatchId || '').trim();
  const seen = new Set();
  const output = [];
  for (const raw of value) {
    const batchId = String(raw?.batch_id || '').trim();
    const retryGroupIds = [...new Set((Array.isArray(raw?.retry_group_ids) ? raw.retry_group_ids : [])
      .map(groupId => String(groupId || '').trim().slice(0, 240))
      .filter(Boolean))];
    if (!/^[a-zA-Z0-9_.:-]{8,80}$/.test(batchId)
      || batchId === currentId
      || seen.has(batchId)
      || !retryGroupIds.length
      || retryGroupIds.length > DIGEST_BATCH_MAX_GROUPS) continue;
    seen.add(batchId);
    output.push({ batch_id: batchId, retry_group_ids: retryGroupIds });
  }
  return output;
}

function normalizeInterruptedDigestResultRange(value = null) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const key = String(value.key || '').trim().slice(0, 40);
  const since = String(value.since || '').trim().slice(0, 80);
  const until = String(value.until || '').trim().slice(0, 80);
  if (!key || !since || !until) return null;
  return {
    key,
    since,
    until,
    dynamic: value.dynamic === true,
  };
}

function normalizeInterruptedDigestBatch(value = {}) {
  const batchId = String(value?.batch_id || '').trim();
  const batchToken = String(value?.batch_token || '').trim();
  const serviceInstanceId = normalizeServiceInstanceId(value?.service_instance_id || '');
  const startedAt = Math.max(0, Number(value?.started_at || 0) || 0);
  const updatedAt = Math.max(startedAt, Number(value?.updated_at || 0) || startedAt);
  const accountFingerprint = String(value?.account_fingerprint || '').trim().toLowerCase();
  if (!/^[a-zA-Z0-9_.:-]{8,80}$/.test(batchId)
    || !/^[a-zA-Z0-9_.:-]{16,256}$/.test(batchToken)
    || !startedAt
    || !updatedAt
    || !/^[a-f0-9]{64}$/.test(accountFingerprint)
    || Date.now() - updatedAt > INTERRUPTED_DIGEST_BATCH_MAX_AGE_MS) return null;
  const rawRender = value?.render && typeof value.render === 'object' && !Array.isArray(value.render) ? value.render : {};
  const targets = normalizeInterruptedDigestBatchTargets(value?.targets);
  if (!targets) return null;
  const supersedes = normalizeInterruptedDigestBatchSupersessions(value?.supersedes, batchId);
  const rawResultInputKey = typeof value?.result_input_key === 'string' ? value.result_input_key : '';
  const resultInputKey = rawResultInputKey.length <= INTERRUPTED_DIGEST_BATCH_MAX_INPUT_KEY_CHARS
    ? rawResultInputKey
    : '';
  const resultRange = normalizeInterruptedDigestResultRange(value?.result_range);
  const rawResultRuntimeVersion = value?.result_runtime_version;
  const parsedResultRuntimeVersion = rawResultRuntimeVersion === null || rawResultRuntimeVersion === undefined
    ? null
    : Number(rawResultRuntimeVersion);
  const resultRuntimeVersion = Number.isSafeInteger(parsedResultRuntimeVersion) && parsedResultRuntimeVersion >= 0
    ? parsedResultRuntimeVersion
    : null;
  const parsedTotal = Math.trunc(Number(value.batch_total || 0));
  const submittedTotal = Number.isFinite(parsedTotal) && parsedTotal >= 0 && parsedTotal <= DIGEST_BATCH_MAX_GROUPS
    ? parsedTotal
    : 0;
  if (targets.length && submittedTotal && submittedTotal !== targets.length) return null;
  return {
    version: 5,
    batch_id: batchId,
    batch_token: batchToken,
    service_instance_id: serviceInstanceId,
    account_id: String(value.account_id || '').trim(),
    account_fingerprint: accountFingerprint,
    preview_text: value.preview_text === true,
    current_group: String(value.current_group || '').trim().slice(0, 240),
    current_group_id: String(value.current_group_id || '').trim().slice(0, 240),
    batch_index: Math.max(-1, Math.trunc(Number(value.batch_index ?? -1))),
    batch_total: Math.max(submittedTotal, targets.length),
    targets,
    supersedes,
    result_input_key: resultInputKey,
    result_range: resultRange,
    result_runtime_version: resultRuntimeVersion,
    phase: String(value.phase || '').trim().slice(0, 80),
    render: {
      theme: normalizeDigestTheme(rawRender.theme),
      fontsize: normalizeDigestFontSize(rawRender.fontsize || rawRender.font_size),
      accent: normalizeDigestAccent(rawRender.accent),
      accent_color: /^#[0-9a-fA-F]{6}$/.test(String(rawRender.accent_color || ''))
        ? String(rawRender.accent_color).toUpperCase()
        : '',
    },
    started_at: startedAt,
    updated_at: updatedAt,
  };
}

function interruptedDigestBatchMatchesSelectedAccount(record = {}, accountId = selectedAccountId(), accounts = _appAccounts) {
  const selectedId = canonicalAccountIdForValue(accountId, accounts);
  const selectedFingerprint = String(accountFingerprintForValue(selectedId, accounts) || '').trim().toLowerCase();
  const recordFingerprint = String(record?.account_fingerprint || '').trim().toLowerCase();
  return !!selectedId
    && /^[a-f0-9]{64}$/.test(selectedFingerprint)
    && recordFingerprint === selectedFingerprint
    && accountScopeUniquelyMatches(record?.account_id || '', selectedId, accounts);
}

function digestBatchServiceInstanceId(batchId = '', explicit = '') {
  const supplied = normalizeServiceInstanceId(explicit);
  if (supplied) return supplied;
  const id = String(batchId || '').trim();
  if (id && id === String(_state_digest.activeBatchId || '').trim()) {
    return normalizeServiceInstanceId(_state_digest.activeBatchServiceInstanceId || '');
  }
  if (id && id === String(_state_digest.lastTextBatchId || '').trim()) {
    return normalizeServiceInstanceId(_state_digest.lastTextBatchServiceInstanceId || '');
  }
  return '';
}

function readInterruptedDigestBatchRecords() {
  try {
    const persistedRaw = localStorage.getItem(INTERRUPTED_DIGEST_BATCH_STORAGE_KEY);
    const legacyRaw = persistedRaw ? '' : sessionStorage.getItem(INTERRUPTED_DIGEST_BATCH_STORAGE_KEY);
    const raw = persistedRaw || legacyRaw;
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (Number(parsed?.version || 0) !== 5) throw new Error('stale interrupted digest recovery schema');
    const values = Array.isArray(parsed)
      ? parsed
      : (Array.isArray(parsed?.records) ? parsed.records : [parsed]);
    const records = values
      .map(value => normalizeInterruptedDigestBatch(value))
      .filter(Boolean)
      .sort((left, right) => Number(right.updated_at || 0) - Number(left.updated_at || 0));
    if (records.length) {
      if (legacyRaw) writeInterruptedDigestBatchRecords(records);
      return records;
    }
    localStorage.removeItem(INTERRUPTED_DIGEST_BATCH_STORAGE_KEY);
    sessionStorage.removeItem(INTERRUPTED_DIGEST_BATCH_STORAGE_KEY);
  } catch {
    try { localStorage.removeItem(INTERRUPTED_DIGEST_BATCH_STORAGE_KEY); } catch {}
    try { sessionStorage.removeItem(INTERRUPTED_DIGEST_BATCH_STORAGE_KEY); } catch {}
  }
  return [];
}

function readInterruptedDigestBatch() {
  return readInterruptedDigestBatchRecords()
    .find(record => interruptedDigestBatchMatchesSelectedAccount(record)
      && !_digestBatchRecoveryVisitedIds.has(record.batch_id)) || null;
}

function writeInterruptedDigestBatchRecords(records = []) {
  const normalized = (Array.isArray(records) ? records : [])
    .map(value => normalizeInterruptedDigestBatch(value))
    .filter(Boolean)
    .sort((left, right) => Number(right.updated_at || 0) - Number(left.updated_at || 0));
  if (normalized.length > INTERRUPTED_DIGEST_BATCH_MAX_RECORDS) return false;
  try {
    if (!normalized.length) {
      localStorage.removeItem(INTERRUPTED_DIGEST_BATCH_STORAGE_KEY);
      sessionStorage.removeItem(INTERRUPTED_DIGEST_BATCH_STORAGE_KEY);
      return true;
    }
    localStorage.setItem(INTERRUPTED_DIGEST_BATCH_STORAGE_KEY, JSON.stringify({
      version: 5,
      records: normalized,
    }));
    sessionStorage.removeItem(INTERRUPTED_DIGEST_BATCH_STORAGE_KEY);
    return true;
  } catch {
    return false;
  }
}

function rememberInterruptedDigestBatch(value = {}) {
  const existingRecords = readInterruptedDigestBatchRecords();
  const nextBatchId = String(value?.batch_id || '').trim();
  const existing = existingRecords.find(record => record.batch_id === nextBatchId) || null;
  const sameBatch = !!existing;
  const record = normalizeInterruptedDigestBatch({
    ...(sameBatch ? existing : {}),
    ...value,
    started_at: Number((sameBatch ? existing?.started_at : 0) || value.started_at || Date.now()) || Date.now(),
    updated_at: Date.now(),
  });
  if (!record) return false;
  return writeInterruptedDigestBatchRecords([
    ...existingRecords.filter(item => item.batch_id !== nextBatchId),
    record,
  ]);
}

function forgetInterruptedDigestBatch(batchId = '') {
  const expectedId = String(batchId || '').trim();
  const records = readInterruptedDigestBatchRecords();
  if (expectedId && records.length && !records.some(record => record.batch_id === expectedId)) return false;
  if (expectedId) _digestBatchRecoveryVisitedIds.delete(expectedId);
  return writeInterruptedDigestBatchRecords(expectedId
    ? records.filter(record => record.batch_id !== expectedId)
    : []);
}

function forgetSupersededTextPreviewRecoveries(currentBatchId = '') {
  const currentId = String(currentBatchId || '').trim();
  if (!currentId) return 0;
  const records = readInterruptedDigestBatchRecords();
  const superseded = records.filter(record => record.preview_text === true && record.batch_id !== currentId);
  if (!superseded.length) return 0;
  writeInterruptedDigestBatchRecords(records.filter(record => !superseded.some(old => old.batch_id === record.batch_id)));
  for (const record of superseded) {
    void finishDigestBatchLeaseResult(record.batch_id, 'text_preview_superseded', {
      notify: false,
      releasePreview: true,
      releaseTerminalResults: true,
      batchToken: record.batch_token,
      batchServiceInstanceId: record.service_instance_id,
      forgetRecovery: false,
      requestTimeoutMs: 5000,
      retryDelays: [0],
    });
  }
  return superseded.length;
}

function preserveInterruptedDigestBatchForUnload() {
  const activeBatchId = String(_state_digest.activeBatchId || '').trim();
  const activeBatchToken = String(_state_digest.activeBatchToken || '').trim();
  if (!activeBatchId || !activeBatchToken) return false;
  return rememberInterruptedDigestBatch({
    batch_id: activeBatchId,
    batch_token: activeBatchToken,
    service_instance_id: _state_digest.activeBatchServiceInstanceId || '',
  });
}

function resetInterruptedDigestBatchRecoveryRetryState() {
  _digestBatchRecoveryStartedAt = 0;
  _digestBatchRecoveryDeadlineAt = 0;
  _digestBatchRecoveryRetryCount = 0;
}

function activeInterruptedDigestBatchRecoveryController() {
  if (_digestBatchRecoveryAbortController && !_digestBatchRecoveryAbortController.signal.aborted) {
    return _digestBatchRecoveryAbortController;
  }
  _digestBatchRecoveryBackgrounded = false;
  _digestBatchRecoveryAbortController = new AbortController();
  return _digestBatchRecoveryAbortController;
}

function backgroundInterruptedDigestBatchRecovery(reason = '已转到后台确认刷新前的摘要结果') {
  if (!_digestBatchRecoveryPending) return false;
  _digestBatchRecoveryBackgrounded = true;
  syncDigestGenerateButtons();
  updateDigestCancelButton();
  setGlobalDigestActivityNotice('warn', `${reason}；恢复记录和页面锁仍保留，服务端确认收尾前不能开始新批次。`);
  updateGlobalDigestActivity();
  return true;
}

function scheduleInterruptedDigestBatchRecoveryFromStorage(delayMs = 0) {
  if (!_digestBatchCrossTabRecoveryReady) return false;
  const record = readInterruptedDigestBatch();
  if (!record) return false;
  startInterruptedDigestBatchBootstrapHeartbeat();
  if (_digestBatchCrossTabRecoveryTimer
    || _digestBatchRecoveryPending
    || _digestBatchCrossTabActiveId
    || DIGEST_BATCH_RECOVERY_RUNNER.has(record.batch_id)) return true;
  _digestBatchCrossTabRecoveryTimer = setTimeout(() => {
    _digestBatchCrossTabRecoveryTimer = null;
    if (_state_digest.generating) {
      scheduleInterruptedDigestBatchRecoveryFromStorage(1000);
      return;
    }
    _digestBatchRecoveryPending = true;
    syncDigestGenerateButtons();
    updateGlobalDigestActivity();
    void recoverInterruptedDigestBatchAfterBootstrap();
  }, Math.max(0, Number(delayMs || 0) || 0));
  return true;
}

function handleInterruptedDigestBatchStorageChange() {
  const records = readInterruptedDigestBatchRecords();
  const selectedAccountRecord = readInterruptedDigestBatch();
  const activeId = String(_digestBatchCrossTabActiveId || '').trim();
  const activeStillStored = !!activeId && records.some(record => record.batch_id === activeId);
  if (activeId && !activeStillStored) {
    if (_digestBatchRecoveryRetryTimer) {
      clearTimeout(_digestBatchRecoveryRetryTimer);
      _digestBatchRecoveryRetryTimer = null;
    }
    const controller = _digestBatchRecoveryAbortController;
    if (controller && !controller.signal.aborted) {
      controller.abort(digestAbortError('另一页面已完成这批摘要的收尾'));
    }
  }
  if (selectedAccountRecord) {
    scheduleInterruptedDigestBatchRecoveryFromStorage(250);
    return;
  }
  if (_digestBatchCrossTabRecoveryTimer) {
    clearTimeout(_digestBatchCrossTabRecoveryTimer);
    _digestBatchCrossTabRecoveryTimer = null;
  }
  if (records.length) startInterruptedDigestBatchBootstrapHeartbeat();
  else stopInterruptedDigestBatchBootstrapHeartbeat();
  if (!activeId) {
    _digestBatchRecoveryPending = false;
    resetInterruptedDigestBatchRecoveryRetryState();
    syncDigestGenerateButtons();
    updateDigestCancelButton();
    updateGlobalDigestActivity();
  }
}

function queueRemainingInterruptedDigestBatchRecovery() {
  const nextRecord = readInterruptedDigestBatch();
  if (!nextRecord) return false;
  _digestBatchRecoveryPending = true;
  syncDigestGenerateButtons();
  queueMicrotask(() => {
    void recoverInterruptedDigestBatchAfterBootstrap();
  });
  return true;
}

function interruptedDigestBatchNeedsBootstrapHeartbeat(record = {}) {
  const phase = String(record?.phase || '').trim();
  return !!record?.batch_id
    && !['text_preview_pending_export', 'terminal_results_pending_recovery'].includes(phase)
    && !_digestBatchBootstrapHeartbeatIgnoredIds.has(record.batch_id);
}

function stopInterruptedDigestBatchBootstrapHeartbeat() {
  if (_digestBatchBootstrapHeartbeatTimer) clearInterval(_digestBatchBootstrapHeartbeatTimer);
  _digestBatchBootstrapHeartbeatTimer = null;
}

function startInterruptedDigestBatchBootstrapHeartbeat() {
  if (_digestBatchBootstrapHeartbeatTimer) return false;
  const heartbeat = async () => {
    if (_digestBatchBootstrapHeartbeatInFlight) return;
    const record = readInterruptedDigestBatchRecords().find(interruptedDigestBatchNeedsBootstrapHeartbeat);
    if (!record) {
      stopInterruptedDigestBatchBootstrapHeartbeat();
      return;
    }
    _digestBatchBootstrapHeartbeatInFlight = true;
    try {
      const result = await api('/api/digest-batch-heartbeat', {
        method: 'POST',
        timeoutMs: 8000,
        body: {
          batch_id: record.batch_id,
          batch_token: record.batch_token,
          service_instance_id: record.service_instance_id,
        },
      });
      if (result.pending !== true) {
        _digestBatchBootstrapHeartbeatIgnoredIds.add(record.batch_id);
        queueMicrotask(() => { void heartbeat(); });
        return;
      }
      rememberInterruptedDigestBatch({
        batch_id: record.batch_id,
        batch_token: record.batch_token,
        service_instance_id: record.service_instance_id,
      });
    } catch (error) {
      const code = String(error?.code || '').trim();
      if (digestBatchRestartInterrupted(error)
        || ['digest_batch_finished', 'digest_batch_id_invalid', 'digest_batch_token_missing', 'digest_batch_token_invalid'].includes(code)) {
        _digestBatchBootstrapHeartbeatIgnoredIds.add(record.batch_id);
        queueMicrotask(() => { void heartbeat(); });
      }
    } finally {
      _digestBatchBootstrapHeartbeatInFlight = false;
    }
  };
  _digestBatchBootstrapHeartbeatTimer = setInterval(() => { void heartbeat(); }, DIGEST_BATCH_HEARTBEAT_INTERVAL_MS);
  void heartbeat();
  return true;
}

function digestBatchRestartInterrupted(error = {}) {
  const code = String(error?.code || error?.public_code || '').trim();
  return code === 'digest_batch_interrupted_by_restart' || code === 'digest_batch_unknown_or_expired';
}

function digestBatchRestartInterruptedMessage(record = {}) {
  const groupText = String(record?.current_group || '').trim();
  return `本地服务已重启，${groupText ? `刷新前的摘要任务（${groupText}）` : '刷新前的摘要任务'}无法确认未完成状态；没有把它标记为已取消。请到历史页核对可能已保存的结果后重新生成。`;
}

function interruptedDigestBatchResultLabel(item = {}, index = -1) {
  return String(item.group_name || item.group_id || '').trim() || `第 ${Math.max(0, Number(index || 0)) + 1} 个群`;
}

function interruptedDigestBatchTarget(record = {}, index = -1) {
  const cleanIndex = Math.max(0, Number(index || 0) || 0);
  const target = Array.isArray(record?.targets) ? record.targets[cleanIndex] : null;
  return target && typeof target === 'object' && !Array.isArray(target)
    ? {
        group_id: String(target.group_id || '').trim(),
        group_name: String(target.group_name || target.group_id || '').trim(),
      }
    : { group_id: '', group_name: '' };
}

function interruptedDigestBatchResultLabelForRecord(record = {}, item = {}, index = -1) {
  const direct = interruptedDigestBatchResultLabel(item, index);
  if (String(item?.group_name || item?.group_id || '').trim()) return direct;
  return interruptedDigestBatchTarget(record, index).group_name || direct;
}

function interruptedDigestBatchSavedResult(index, item = {}, savedItem = null, detail = '', commitSource = null, batchId = '') {
  const commitWarning = savedPngCommitWarning(commitSource || savedItem || {});
  setDigestBatchResult(index, {
    status: commitWarning ? 'partial' : 'done',
    type: 'image',
    batch_id: String(batchId || '').trim(),
    account_id: String(item.account_id || '').trim(),
    group_id: String(item.group_id || '').trim(),
    group: interruptedDigestBatchResultLabel(item, index),
    detail: commitWarning?.text || detail || savedItem?.relative_path || '已恢复到历史记录',
    actionStatus: commitWarning ? 'warn' : '',
    actionDetail: commitWarning?.text || '',
    item: savedItem || null,
  });
  return commitWarning;
}

function interruptedDigestBatchFailure(item = {}, fallback = '刷新前该群没有完成') {
  const error = item?.error && typeof item.error === 'object' ? item.error : {};
  const detail = compactErrorSummary(error.message || fallback);
  const cancelled = Number(error.status || 0) === 499
    || ['cancelled', 'request_cancelled', 'digest_batch_cancelled'].includes(String(error.code || '').trim());
  const collectionSkipped = String(item?.status || '').trim() === 'skipped'
    || ['digest_below_minimum', 'digest_empty_after_filters', 'digest_no_messages'].includes(String(error.code || '').trim());
  return {
    status: cancelled ? 'cancelled' : (collectionSkipped ? 'skipped' : 'error'),
    detail,
    cancelled,
    collectionSkipped,
    meta: error,
  };
}

function prepareInterruptedDigestBatchResultRows(batchId = '') {
  const expectedBatchId = String(batchId || '').trim();
  if (!_digestBatchRecoveryResultsInitialized) {
    resetDigestBatchResults();
    _digestBatchRecoveryResultsInitialized = true;
    return 0;
  }
  const retained = [];
  for (const result of (_state_digest.batchResults || [])) {
    if (String(result?.batch_id || '').trim() === expectedBatchId) {
      revokeObjectUrl(result?.previewDownloadUrl || '');
      continue;
    }
    retained.push(result);
  }
  _state_digest.batchResults = retained.map((result, index) => ({ ...result, index }));
  return retained.length;
}

async function recoverInterruptedImageBatchResults(record = {}, batchResults = {}) {
  const recoverySignal = _digestBatchRecoveryAbortController?.signal || null;
  const terminalItems = Array.isArray(batchResults.items) ? batchResults.items : [];
  const total = Math.max(
    0,
    Number(record.batch_total || 0) || 0,
    Array.isArray(record.targets) ? record.targets.length : 0,
    ...terminalItems.map(item => Math.max(0, Number(item.batch_index || 0) + 1)),
  );
  const resultOffset = prepareInterruptedDigestBatchResultRows(record.batch_id);
  for (let index = 0; index < total; index += 1) {
    const target = interruptedDigestBatchTarget(record, index);
    setDigestBatchResult(resultOffset + index, {
      status: 'cancelled',
      type: 'image',
      batch_id: String(record.batch_id || '').trim(),
      account_id: record.account_id || '',
      group_id: target.group_id,
      group: target.group_name || `第 ${index + 1} 个群`,
      detail: '页面刷新时尚未形成可恢复结果，没有重复请求 AI',
    });
  }
  let recovered = 0;
  let alreadySaved = 0;
  let failed = 0;
  let skipped = 0;
  let warningCount = 0;
  const durableGroupIds = new Set();
  let lastRecoveredPreview = null;
  const renderSelection = record.render && typeof record.render === 'object'
    ? record.render
    : currentDigestRenderSelection();
  for (const item of terminalItems) {
    const index = Math.max(0, Number(item.batch_index || 0) || 0);
    const label = interruptedDigestBatchResultLabelForRecord(record, item, index);
    if (['error', 'skipped'].includes(item.status)) {
      const failure = interruptedDigestBatchFailure(item);
      setDigestBatchResult(resultOffset + index, {
        status: failure.status,
        type: 'image',
        batch_id: String(record.batch_id || '').trim(),
        account_id: item.account_id || record.account_id || '',
        group_id: item.group_id || '',
        group: label,
        detail: failure.detail,
        meta: failure.meta,
      });
      failed += failure.cancelled || failure.collectionSkipped ? 0 : 1;
      skipped += failure.collectionSkipped ? 1 : 0;
      continue;
    }
    if (item.status === 'saved' && item.item) {
      if (interruptedDigestBatchSavedResult(resultOffset + index, item, item.item, item.item.relative_path || '刷新前已写入历史记录', item, record.batch_id)) {
        warningCount += 1;
      } else {
        durableGroupIds.add(String(item.group_id || interruptedDigestBatchTarget(record, index).group_id || '').trim());
      }
      alreadySaved += 1;
      continue;
    }
    setGlobalDigestActivityNotice('running', `正在恢复刷新前已完成的长图 ${recovered + alreadySaved + 1}/${Math.max(1, terminalItems.length)}（${label}）：取回原摘要并在本机重新绘制，不会再次请求 AI。`);
    const terminal = await api('/api/digest-result', {
      method: 'POST',
      timeoutMs: 15_000,
      signal: recoverySignal,
      body: {
        batch_id: record.batch_id,
        batch_token: record.batch_token,
        service_instance_id: record.service_instance_id,
        batch_index: index,
        account_id: item.account_id || record.account_id || '',
        expected_account_fingerprint: record.account_fingerprint,
        group_id: item.group_id || '',
      },
    });
    if (terminal.status === 'saved' && terminal.item) {
      if (interruptedDigestBatchSavedResult(resultOffset + index, item, terminal.item, terminal.item.relative_path || '已确认写入历史记录', terminal, record.batch_id)) {
        warningCount += 1;
      } else {
        durableGroupIds.add(String(item.group_id || interruptedDigestBatchTarget(record, index).group_id || '').trim());
      }
      alreadySaved += 1;
      continue;
    }
    if (terminal.status !== 'done' || !terminal.digest) {
      throw Object.assign(new Error(`刷新前的 ${label} 终态摘要已变化，暂不能安全恢复；恢复记录仍保留。`), {
        code: 'digest_batch_recovery_result_changed',
      });
    }
    const digest = terminal.digest;
    const canvas = await drawDigestCanvas(digest, document.createElement('canvas'), renderSelection, { signal: recoverySignal });
    const recoveredSave = await saveRenderedCanvas(digest, canvas, {
      signal: recoverySignal,
      batchId: record.batch_id,
      batchToken: record.batch_token,
      batchServiceInstanceId: record.service_instance_id,
      renderSelection,
      accountId: item.account_id || record.account_id || '',
      accountLabel: digest.account_label || record.account_id || '',
    });
    const savedItem = recoveredSave?.item || null;
    if (!savedItem) {
      throw Object.assign(new Error(`刷新前的 ${label} 已重新绘制，但本地服务没有返回可确认的历史记录；恢复记录仍保留。`), {
        code: 'digest_batch_recovery_save_unconfirmed',
      });
    }
    if (interruptedDigestBatchSavedResult(resultOffset + index, item, savedItem, savedItem.relative_path || '已恢复并写入历史记录', recoveredSave, record.batch_id)) {
      warningCount += 1;
    } else {
      durableGroupIds.add(String(item.group_id || digest.group_id || interruptedDigestBatchTarget(record, index).group_id || '').trim());
    }
    recovered += 1;
    lastRecoveredPreview = { digest, savedItem };
  }
  if (lastRecoveredPreview) {
    _state_digest.lastDigest = lastRecoveredPreview.digest;
    _state_digest.lastSavedItem = lastRecoveredPreview.savedItem;
    _state_digest.lastRenderSelection = { ...renderSelection };
    _state_digest.lastCanvasRenderKey = digestRenderStateKey(renderSelection);
    _state_digest.lastSavedRenderKey = _state_digest.lastCanvasRenderKey;
    rememberRecoveredDigestFreshness(record, lastRecoveredPreview.digest);
    updatePreviewSavedRenderState();
    updateDigestPreviewActionLock();
    if (document.getElementById('digest-canvas')) {
      await drawDigestCanvas(lastRecoveredPreview.digest, null, renderSelection, { signal: recoverySignal });
      const previewCard = document.getElementById('preview-card');
      previewCard?.classList.remove('hidden', 'pending-render');
    }
  }
  return {
    recovered,
    alreadySaved,
    failed,
    skipped,
    warningCount,
    durableGroupIds: [...durableGroupIds].filter(Boolean),
    total,
    terminalCount: terminalItems.length,
  };
}

async function recoverInterruptedDigestBatchAfterBootstrap({ lockAcquired = false, lockedRecord = null } = {}) {
  _digestBatchCrossTabRecoveryReady = true;
  const record = lockedRecord
    ? (interruptedDigestBatchMatchesSelectedAccount(lockedRecord) ? lockedRecord : null)
    : readInterruptedDigestBatch();
  if (!record) {
    resetInterruptedDigestBatchRecoveryRetryState();
    _digestBatchRecoveryResultsInitialized = false;
    _digestBatchRecoveryAbortController = null;
    _digestBatchRecoveryBackgrounded = false;
    _digestBatchRecoveryPending = false;
    syncDigestGenerateButtons();
    updateDigestCancelButton();
    updateGlobalDigestActivity();
    return false;
  }
  if (!lockAcquired) {
    _digestBatchRecoveryPending = true;
    syncDigestGenerateButtons();
    updateDigestCancelButton();
    updateGlobalDigestActivity();
    try {
      const outcome = await DIGEST_BATCH_RECOVERY_RUNNER.run(record.batch_id, async () => {
        const current = readInterruptedDigestBatchRecords().find(item => item.batch_id === record.batch_id);
        if (!current || !interruptedDigestBatchMatchesSelectedAccount(current)) return false;
        return recoverInterruptedDigestBatchAfterBootstrap({ lockAcquired: true, lockedRecord: current });
      }, {
        shouldRun: () => {
          const current = readInterruptedDigestBatchRecords().find(item => item.batch_id === record.batch_id);
          if (!current
            || !interruptedDigestBatchMatchesSelectedAccount(current)
            || current.batch_token !== record.batch_token) return false;
          return current.phase !== 'text_preview_pending_export'
            || Number(current.updated_at || 0) === Number(record.updated_at || 0);
        },
      });
      if (outcome.ran) return outcome.value;
      if (!readInterruptedDigestBatchRecords().some(item => item.batch_id === record.batch_id)) {
        _digestBatchRecoveryPending = false;
        resetInterruptedDigestBatchRecoveryRetryState();
        syncDigestGenerateButtons();
        updateDigestCancelButton();
        setGlobalDigestActivityNotice('done', '另一页面已完成刷新前摘要的收尾；如有已保存结果，可在历史页查看。当前页面没有重复请求 AI 或重复保存。');
      } else {
        _digestBatchRecoveryPending = false;
        scheduleInterruptedDigestBatchRecoveryFromStorage(500);
      }
      return false;
    } catch (error) {
      _digestBatchRecoveryPending = false;
      syncDigestGenerateButtons();
      updateDigestCancelButton();
      setGlobalDigestActivityNotice('error', `无法协调刷新前摘要的跨页面恢复：${compactErrorSummary(error?.message || '浏览器任务锁不可用')}。恢复记录仍保留，刷新页面后可重试。`);
      return false;
    }
  }
  _digestBatchCrossTabActiveId = record.batch_id;
  const recoveryController = activeInterruptedDigestBatchRecoveryController();
  const recoverySignal = recoveryController.signal;
  if (!_digestBatchRecoveryStartedAt) _digestBatchRecoveryStartedAt = Date.now();
  _digestBatchRecoveryPending = true;
  syncDigestGenerateButtons();
  const groupText = record.current_group ? `（${record.current_group}）` : '';
  let retryScheduled = false;
  let retainRecoveredTextPreview = false;
  const pauseRecovery = () => {
    _digestBatchRecoveryPending = false;
    resetInterruptedDigestBatchRecoveryRetryState();
    syncDigestGenerateButtons();
    setGlobalDigestActivityNotice('warn', `刷新前的摘要任务${groupText}已超过本地服务任务截止时间和收尾宽限，自动确认已暂停并解除页面锁；恢复记录仍保留，刷新页面后可继续核对。`);
  };
  const scheduleRecoveryRetry = (delayMs = 3000) => {
    const deadlineAt = _digestBatchRecoveryDeadlineAt
      || (_digestBatchRecoveryStartedAt + DIGEST_BATCH_RECOVERY_FALLBACK_WAIT_MS);
    const remainingMs = deadlineAt - Date.now();
    if (remainingMs <= 0) {
      pauseRecovery();
      return false;
    }
    const fastRetry = _digestBatchRecoveryRetryCount < DIGEST_BATCH_RECOVERY_FAST_RETRIES;
    const nextDelayMs = fastRetry
      ? Math.max(1000, Number(delayMs || 0) || 3000)
      : Math.max(DIGEST_BATCH_RECOVERY_SLOW_RETRY_MS, Number(delayMs || 0) || 0);
    _digestBatchRecoveryRetryCount += 1;
    retryScheduled = true;
    _digestBatchRecoveryRetryTimer = setTimeout(() => {
      _digestBatchRecoveryRetryTimer = null;
      if (recoverySignal.aborted) return;
      _digestBatchRecoveryPending = false;
      void recoverInterruptedDigestBatchAfterBootstrap();
    }, Math.max(250, Math.min(nextDelayMs, remainingMs)));
    return true;
  };
  try {
    const batchResults = await api('/api/digest-batch-results', {
      method: 'POST',
      timeoutMs: 12_000,
      signal: recoverySignal,
      body: {
        batch_id: record.batch_id,
        batch_token: record.batch_token,
        service_instance_id: record.service_instance_id,
        account_id: record.account_id,
        expected_account_fingerprint: record.account_fingerprint,
      },
    });
    if (batchResults.recovered_after_restart === true) {
      const recoveredServiceInstanceId = normalizeServiceInstanceId(batchResults.service_instance_id || '');
      if (!recoveredServiceInstanceId) throw invalidApiResponseError('本地服务恢复了摘要结果，但没有返回新的服务实例标识。', 'digest_recovery_service_instance_missing');
      record.service_instance_id = recoveredServiceInstanceId;
      rememberServiceInstanceId(recoveredServiceInstanceId);
      rememberInterruptedDigestBatch(record);
    }
    const pendingDeadlineAt = Date.parse(String(batchResults.pending_deadline_at || '').trim());
    if (batchResults.pending === true && Number.isFinite(pendingDeadlineAt)) {
      _digestBatchRecoveryDeadlineAt = pendingDeadlineAt + DIGEST_BATCH_RECOVERY_DEADLINE_GRACE_MS;
    }
    if (batchResults.pending === true) {
      if (scheduleRecoveryRetry(3000)) {
        setGlobalDigestActivityNotice('warn', `刷新前的摘要任务${groupText}仍在本地服务收尾，恢复记录和页面锁暂时保留；服务恢复后会自动继续确认。`);
      }
      return false;
    }
    let recoveryNotice = null;
    if (record.preview_text) {
      const recovered = await api('/api/digest-batch-preview', {
        method: 'POST',
        timeoutMs: 12_000,
        signal: recoverySignal,
        body: {
          batch_id: record.batch_id,
          batch_token: record.batch_token,
          service_instance_id: record.service_instance_id,
          account_id: record.account_id,
          expected_account_fingerprint: record.account_fingerprint,
          batch_total: Math.max(
            0,
            Number(record.batch_total || 0) || 0,
            Array.isArray(record.targets) ? record.targets.length : 0,
          ),
        },
      });
      const recoveredDigests = Array.isArray(recovered?.digests)
        ? recovered.digests.filter(digest => digest && typeof digest === 'object' && String(digest.digest_id || '').trim())
        : [];
      const terminalItems = Array.isArray(batchResults.items) ? batchResults.items : [];
      if ((recovered.status === 'done' && recoveredDigests.length) || terminalItems.length) {
        const resultOffset = prepareInterruptedDigestBatchResultRows(record.batch_id);
        const recoveredTotal = Math.max(
          recoveredDigests.length,
          Number(recovered.total || record.batch_total || 0) || 0,
          Array.isArray(record.targets) ? record.targets.length : 0,
          ...terminalItems.map(item => Math.max(
            Math.max(0, Number(item.batch_total || 0) || 0),
            Math.max(0, Number(item.batch_index || 0) + 1),
          )),
        );
        const recoveredComplete = recovered.complete === true && recoveredDigests.length === recoveredTotal;
        if (recoveredDigests.length) {
          renderTextPreviews(recoveredDigests, {
            complete: recoveredComplete,
            total: recoveredTotal,
            partialReason: recoveredComplete ? '' : 'recovered_partial',
            batchId: record.batch_id,
            batchToken: record.batch_token,
            batchServiceInstanceId: record.service_instance_id,
          });
          rememberRecoveredDigestFreshness(record, recoveredDigests);
        }
        retainRecoveredTextPreview = recoveredDigests.length > 0;
        const recoveredByIndex = new Map(recoveredDigests.map((digest, fallbackIndex) => {
          const batchIndex = Number(digest.preview_batch_index);
          return [Number.isInteger(batchIndex) && batchIndex >= 0 ? batchIndex : fallbackIndex, digest];
        }));
        const terminalByIndex = new Map(terminalItems.map(item => [Math.max(0, Number(item.batch_index || 0) || 0), item]));
        let failedCount = 0;
        let cancelledCount = 0;
        let skippedCount = 0;
        for (let index = 0; index < recoveredTotal; index += 1) {
          const digest = recoveredByIndex.get(index);
          const terminal = terminalByIndex.get(index) || null;
          const target = interruptedDigestBatchTarget(record, index);
          if (terminal && ['error', 'skipped'].includes(terminal.status)) {
            const failure = interruptedDigestBatchFailure(terminal);
            if (failure.cancelled) cancelledCount += 1;
            else if (failure.collectionSkipped) skippedCount += 1;
            else failedCount += 1;
            setDigestBatchResult(resultOffset + index, {
              status: failure.status,
              type: 'text',
              batch_id: String(record.batch_id || '').trim(),
              account_id: terminal.account_id || record.account_id || '',
              group_id: terminal.group_id || target.group_id,
              group: interruptedDigestBatchResultLabelForRecord(record, terminal, index),
              detail: failure.detail,
              meta: failure.meta,
            });
            continue;
          }
          setDigestBatchResult(resultOffset + index, digest ? {
            status: 'done',
            type: 'text',
            batch_id: String(record.batch_id || '').trim(),
            account_id: digest.account_id || record.account_id,
            group_id: digest.group_id || target.group_id,
            group: digest.group || target.group_name || `第 ${index + 1} 个群`,
            retryable: false,
             detail: '已从刷新前的任务恢复到文本预览；可复制或点“导出 MD”保存本批',
             actionStatus: '',
             actionDetail: '',
          } : {
            status: 'cancelled',
            type: 'text',
            batch_id: String(record.batch_id || '').trim(),
            account_id: terminal?.account_id || record.account_id,
            group_id: terminal?.group_id || target.group_id || (index === record.batch_index ? record.current_group_id : ''),
            group: terminal ? interruptedDigestBatchResultLabelForRecord(record, terminal, index) : (target.group_name || (index === record.batch_index ? record.current_group : '') || `第 ${index + 1} 个群`),
            detail: '页面刷新时尚未完成，本次恢复没有重新请求 AI',
          });
          if (!digest) cancelledCount += 1;
        }
        if (recoveredDigests.length) paintTextPreviewMarkdown();
        const failureSuffix = [
          failedCount ? `${failedCount} 个群失败` : '',
          skippedCount ? `${skippedCount} 个群未生成` : '',
          cancelledCount ? `${cancelledCount} 个群未完成` : '',
        ].filter(Boolean).join('，');
        recoveryNotice = recoveredDigests.length
          ? {
              level: recoveredComplete ? 'done' : 'warn',
              text: recoveredComplete
                ? `刷新前的文本预览已完整恢复 ${recoveredDigests.length}/${recoveredTotal} 个群；可复制或点“导出 MD”保存本批。`
                : `刷新前的文本预览已恢复 ${recoveredDigests.length}/${recoveredTotal} 个群${failureSuffix ? `，${failureSuffix}` : ''}；没有重复请求 AI。可点“导出 MD”保存已恢复内容。`,
            }
          : {
              level: 'warn',
              text: `刷新前的文本批次没有成功内容${failureSuffix ? `：${failureSuffix}` : ''}；每个群的原失败原因已恢复到本批结果，没有重复请求 AI。`,
            };
      }
    } else {
      const imageRecovery = await recoverInterruptedImageBatchResults(record, batchResults);
      const savedCount = imageRecovery.recovered + imageRecovery.alreadySaved;
      releaseCompletedImageRetrySupersessions(record.supersedes, imageRecovery.durableGroupIds, {
        accountId: record.account_id,
        accountFingerprint: record.account_fingerprint,
      });
      recoveryNotice = savedCount > 0
        ? {
            level: imageRecovery.failed > 0 || imageRecovery.skipped > 0 || imageRecovery.warningCount > 0 ? 'warn' : 'done',
            text: `刷新前已完成的长图已恢复 ${savedCount} 张（重新绘制并保存 ${imageRecovery.recovered} 张，确认此前已保存 ${imageRecovery.alreadySaved} 张）；没有重复请求 AI。${imageRecovery.warningCount > 0 ? ` 其中 ${imageRecovery.warningCount} 张已写入，但历史或输出目录状态需按结果提示核对。` : ''}${imageRecovery.skipped > 0 ? ` 另有 ${imageRecovery.skipped} 个群未满足生成条件。` : ''}${imageRecovery.failed > 0 ? ` 另有 ${imageRecovery.failed} 个群在刷新前已失败。` : ''}`,
          }
        : {
            level: imageRecovery.failed > 0 || imageRecovery.skipped > 0 ? 'warn' : 'cancelled',
            text: imageRecovery.failed > 0
              ? `刷新前的长图批次没有可保存的成功结果，${imageRecovery.failed} 个群已失败；没有重复请求 AI。`
              : (imageRecovery.skipped > 0
                ? `刷新前的长图批次没有可保存的成功结果，${imageRecovery.skipped} 个群未满足生成条件；没有重复请求 AI。`
                : `刷新前的摘要任务${groupText}已自动停止；尚未完成的群没有重复请求 AI。`),
          };
    }
    const finishResult = await finishDigestBatchLeaseResult(record.batch_id, 'page_reload_recovery_consumed', {
      notify: false,
      releasePreview: !retainRecoveredTextPreview,
      releaseTerminalResults: !retainRecoveredTextPreview,
      batchToken: record.batch_token,
      batchServiceInstanceId: record.service_instance_id,
      forgetRecovery: false,
      signal: recoverySignal,
    });
    if (!finishResult.settled) {
      if (scheduleRecoveryRetry(finishResult.state === 'unreachable' ? 5000 : 3000)) {
        setGlobalDigestActivityNotice('warn', '刷新前的已完成结果已恢复，但本地服务仍在确认批次释放；恢复记录和页面锁暂时保留，服务恢复后会自动继续确认。');
      }
      return false;
    }
    if (retainRecoveredTextPreview) {
      rememberInterruptedDigestBatch({
        ...record,
        phase: 'text_preview_pending_export',
      });
      forgetSupersededTextPreviewRecoveries(record.batch_id);
      _digestBatchRecoveryVisitedIds.add(record.batch_id);
      resetInterruptedDigestBatchRecoveryRetryState();
      setGlobalDigestActivityNotice(recoveryNotice?.level || 'warn', recoveryNotice?.text || '刷新前的文本预览已恢复；可复制或导出 MD。');
      retryScheduled = queueRemainingInterruptedDigestBatchRecovery();
      if (retryScheduled) {
        setGlobalDigestActivityNotice('running', '文本预览已恢复并保留待导出，正在继续核对其余未收尾任务。');
      }
      return true;
    }
    forgetInterruptedDigestBatch(record.batch_id);
    resetInterruptedDigestBatchRecoveryRetryState();
    setGlobalDigestActivityNotice(recoveryNotice?.level || 'cancelled', recoveryNotice?.text || `刷新前的摘要任务${groupText}已自动停止；没有可恢复的已完成结果。`);
    retryScheduled = queueRemainingInterruptedDigestBatchRecovery();
    if (retryScheduled) {
      setGlobalDigestActivityNotice('running', '已确认一条刷新前的摘要任务，正在继续核对其余未收尾任务。');
    }
    return true;
  } catch (error) {
    if (recoverySignal.aborted || error?.name === 'AbortError' || Number(error?.status || 0) === 499) {
      const recordStillStored = readInterruptedDigestBatchRecords().some(item => item.batch_id === record.batch_id);
      setGlobalDigestActivityNotice(
        recordStillStored ? 'cancelled' : 'done',
        recordStillStored
          ? '已停止恢复刷新前的摘要结果；恢复记录仍保留，刷新页面后可继续确认。'
          : '另一页面已完成刷新前摘要的收尾；当前页面已停止重复恢复。',
      );
      return false;
    }
    const code = String(error?.code || '').trim();
    if (digestBatchRestartInterrupted(error)) {
      forgetInterruptedDigestBatch(record.batch_id);
      resetInterruptedDigestBatchRecoveryRetryState();
      setGlobalDigestActivityNotice('warn', digestBatchRestartInterruptedMessage(record));
      retryScheduled = queueRemainingInterruptedDigestBatchRecovery();
      if (retryScheduled) {
        setGlobalDigestActivityNotice('running', '一条刷新前的任务因本地服务重启无法继续确认，正在继续核对其余未收尾任务。');
      }
      return false;
    }
    if (['digest_batch_id_invalid', 'digest_batch_token_missing', 'digest_batch_token_invalid'].includes(code)) {
      forgetInterruptedDigestBatch(record.batch_id);
      resetInterruptedDigestBatchRecoveryRetryState();
      setGlobalDigestActivityNotice('error', `刷新前的摘要任务${groupText}恢复凭据已失效，页面已解除锁；请到历史页核对已完成结果后再重新生成。`);
      retryScheduled = queueRemainingInterruptedDigestBatchRecovery();
      if (retryScheduled) {
        setGlobalDigestActivityNotice('running', '一条刷新前的任务恢复凭据已失效，正在继续核对其余未收尾任务。');
      }
      return false;
    } else {
      if (scheduleRecoveryRetry(5000)) {
        setGlobalDigestActivityNotice('error', `刷新前的摘要任务${groupText}未能自动收尾：${compactErrorSummary(error?.message || '本地服务暂时不可用')}。页面会暂时保留锁并继续确认；请检查或重启本地服务。`);
      }
    }
    return false;
  } finally {
    if (_digestBatchCrossTabActiveId === record.batch_id) _digestBatchCrossTabActiveId = '';
    if (!retryScheduled) {
      _digestBatchRecoveryPending = false;
      if (_digestBatchRecoveryAbortController === recoveryController) {
        _digestBatchRecoveryAbortController = null;
        _digestBatchRecoveryBackgrounded = false;
      }
      syncDigestGenerateButtons();
      updateDigestCancelButton();
    }
    if (_digestBatchRecoveryRescheduleAfterAccountReset && !_digestBatchCrossTabActiveId) {
      _digestBatchRecoveryRescheduleAfterAccountReset = false;
      queueMicrotask(() => scheduleInterruptedDigestBatchRecoveryFromStorage(0));
    }
  }
}

function advanceDigestRunEpoch() {
  const next = Math.max(0, Number(_digestRunEpoch || 0) || 0) + 1;
  _digestRunEpoch = next > Number.MAX_SAFE_INTEGER ? 1 : next;
  return _digestRunEpoch;
}

function bumpTextPreviewExportVersion() {
  const next = Math.max(0, Number(_state_digest.textExportVersion || 0) || 0) + 1;
  _state_digest.textExportVersion = next > Number.MAX_SAFE_INTEGER ? 1 : next;
  return _state_digest.textExportVersion;
}

function setTextPreviewExportState(state = '', {
  error = '',
  canRetry = true,
  committedUnbound = false,
  auto = false,
} = {}) {
  _state_digest.lastTextExportState = String(state || '').trim();
  _state_digest.lastTextExportError = compactErrorSummary(error || '');
  _state_digest.lastTextExportCanRetry = canRetry !== false;
  _state_digest.lastTextExportCommittedUnbound = !!committedUnbound;
  _state_digest.lastTextExportAuto = !!auto;
}

function clearTextPreviewExportState() {
  setTextPreviewExportState('');
}

function textPreviewExportStateMessage() {
  const state = String(_state_digest.lastTextExportState || '').trim();
  const item = _state_digest.lastTextExportItem || null;
  const target = outputItemTarget(item || {});
  const error = compactErrorSummary(_state_digest.lastTextExportError || '');
  if (state === 'saved') {
    if (item && !markdownOutputTargetUsable(item)) {
      return {
        className: 'status warn',
        text: target
          ? `MD 已写入 ${item.relative_path || target}，但${markdownOutputUnusableReasonText(item)}。`
          : `MD 已写入，但${markdownOutputUnusableReasonText(item)}。`,
      };
    }
    return {
      className: 'status ok',
      text: target
        ? `✓ 已保存本批合并 MD：${item.relative_path || target}，可下载或在文件夹中显示`
        : '✓ 已保存本批合并 MD',
    };
  }
  if (state === 'unbound') {
    return {
      className: 'status warn',
      text: error || 'MD 已写入但未绑定当前下载/显示入口；可点“导出 MD”重新绑定。',
    };
  }
  if (state === 'missing') {
    const action = _state_digest.lastTextExportCanRetry
      ? '可点“导出 MD”重试保存到历史'
      : '请重新生成后再保存 MD';
    return {
      className: 'status warn',
      text: `文本已生成，MD 未保存到历史${error ? `：${error}` : ''}；${action}`,
    };
  }
  return null;
}

function invalidateTextPreviewExportTarget({ sync = true, notice = '' } = {}) {
  abortTextPreviewActions('文本预览、输入或输出目录已变化，导出/显示 MD 已取消');
  bumpTextPreviewExportVersion();
  _state_digest.lastTextExportItem = null;
  _state_digest.textExportInFlight = false;
  _state_digest.textExportInvalidationNotice = String(notice || '').trim();
  clearTextPreviewExportState();
  const exportButton = document.getElementById('btn-export-md');
  if (exportButton) delete exportButton.dataset.busy;
  if (sync) {
    updateDigestSelectionLock();
    syncTextPreviewExportButton(exportButton);
    syncTextPreviewDownloadButton();
    syncTextPreviewRevealButton();
  }
}

function clearTextPreviewServerSnapshotUnavailable() {
  _state_digest.lastTextServerSnapshotUnavailable = false;
  _state_digest.textExportInvalidationNotice = '';
}

function textPreviewServerSnapshotUnavailable() {
  const hasBatch = !!String(_state_digest.lastTextBatchId || '').trim();
  const previewServiceInstance = normalizeServiceInstanceId(_state_digest.lastTextBatchServiceInstanceId || '');
  const currentServiceInstance = normalizeServiceInstanceId(SERVICE_INSTANCE_ID || '');
  const missingServiceInstance = hasBatch && !previewServiceInstance;
  const serviceInstanceChanged = hasBatch
    && !!previewServiceInstance
    && !!currentServiceInstance
    && previewServiceInstance !== currentServiceInstance;
  return (_state_digest.lastTextServerSnapshotUnavailable === true || missingServiceInstance || serviceInstanceChanged)
    && hasBatch
    && !!String(_state_digest.lastTextMarkdown || '').trim();
}

function textPreviewServerExportSnapshotAvailable() {
  return !textPreviewServerSnapshotUnavailable()
    && !!String(_state_digest.lastTextBatchId || '').trim()
    && !!String(_state_digest.lastTextBatchToken || '').trim()
    && !!normalizeServiceInstanceId(_state_digest.lastTextBatchServiceInstanceId || '');
}

function textPreviewServerSnapshotUnavailableMessage() {
  return String(_state_digest.textExportInvalidationNotice || '').trim()
    || '本地服务已重启或文本预览快照已过期；当前文本仍可复制，但不能保存为可信 MD。请重新生成后再导出 MD。';
}

function markTextPreviewServerSnapshotUnavailable(message = '') {
  _state_digest.lastTextServerSnapshotUnavailable = true;
  _state_digest.lastTextExportItem = null;
  _state_digest.textExportInFlight = false;
  _state_digest.textExportInvalidationNotice = String(message || '本地服务已重启或文本预览快照已过期；当前文本仍可复制，但不能保存为可信 MD。请重新生成后再导出 MD。').trim();
  clearTextPreviewExportState();
  const status = document.getElementById('text-preview-status');
  if (status?.isConnected && textPreviewServerSnapshotUnavailable()) {
    status.className = 'status warn';
    status.textContent = textPreviewServerSnapshotUnavailableMessage();
  }
  syncTextPreviewExportButton();
  syncTextPreviewDownloadButton();
  syncTextPreviewRevealButton();
}

function digestBatchPreviewMissingError(error = {}) {
  const code = String(error?.code || error?.public_code || '').trim();
  return code === 'digest_batch_preview_missing'
    || code === 'digest_batch_preview_empty'
    || code === 'digest_batch_preview_incomplete'
    || code === 'digest_batch_preview_limit_exceeded'
    || code === 'digest_batch_preview_index_invalid'
    || code === 'digest_batch_cancelled'
    || code === 'digest_batch_settings_expired'
    || code === 'digest_batch_token_invalid'
    || code === 'digest_batch_unknown_or_expired'
    || code === 'digest_batch_interrupted_by_restart'
    || code === 'digest_runtime_settings_changed';
}

function digestBatchPreviewUnavailableMessage(error = {}) {
  const code = String(error?.code || error?.public_code || '').trim();
  if (code === 'digest_batch_cancelled') {
    return '本次生成已取消且没有可恢复的服务端文本快照；当前文本仍可复制，但不能保存为可信 MD。请重新生成后再导出 MD。';
  }
  if (code === 'digest_batch_token_invalid') {
    return '文本预览批次凭据不匹配；当前文本仍可复制，但不能保存为可信 MD。请重新生成后再导出 MD。';
  }
  if (code === 'digest_batch_interrupted_by_restart' || code === 'digest_batch_unknown_or_expired') {
    return '本地服务已重启或批次已过期；当前文本仍可复制，但不能保存为可信 MD。请到历史页核对后重新生成。';
  }
  if (code === 'digest_batch_settings_expired' || code === 'digest_runtime_settings_changed') {
    return '摘要生成设置或批次快照已变化；当前文本仍可复制，但不能保存为可信 MD。请重新生成后再导出 MD。';
  }
  if (code === 'digest_batch_preview_incomplete') {
    return '服务端文本预览快照不完整；当前文本仍可复制，但不能保存为可信 MD。请重新生成或分批生成后再导出 MD。';
  }
  if (code === 'digest_batch_preview_limit_exceeded' || code === 'digest_batch_preview_index_invalid') {
    return `一次文本预览最多支持 ${DIGEST_TEXT_PREVIEW_MAX_GROUPS} 个群；当前文本仍可复制，但不能保存为可信 MD。请减少选择或分批生成。`;
  }
  return '本地服务已重启或文本预览快照已过期；当前文本仍可复制，但不能保存为可信 MD。请重新生成后再导出 MD。';
}

function previewMarkdownExportTooLargeError(error = {}) {
  const code = String(error?.code || error?.public_code || '').trim();
  const status = Number(error?.status || 0) || 0;
  return code === 'preview_markdown_too_large'
    || code === 'preview_too_large'
    || status === 413
    || /超过\s*2MB|payload too large|request body too large/i.test(String(error?.message || ''));
}

function settingsPatchTouchesLlmRuntimeForUi(patch = {}) {
  if (!patch?.llm || typeof patch.llm !== 'object' || Array.isArray(patch.llm)) return false;
  return [
    'api_key',
    'clear_api_key',
    'provider',
    'base_url',
    'model',
    'long_context_model',
    'temperature',
    'timeout_ms',
    'max_input_chars',
    'max_messages_per_call',
    'ai_concurrency',
  ].some(key => Object.hasOwn(patch.llm, key));
}

function settingsPatchTouchesManualKeyForUi(patch = {}) {
  return !!patch?.wechat
    && (Object.hasOwn(patch.wechat, 'manual_key')
      || Object.hasOwn(patch.wechat, 'clear_manual_key')
      || Object.hasOwn(patch.wechat, 'clear_orphaned_manual_key')
      || Object.hasOwn(patch.wechat, 'clear_legacy_manual_key'));
}

function settingsPatchTouchesDigestRuntimeForUi(patch = {}) {
  if (settingsPatchTouchesLlmRuntimeForUi(patch)) return true;
  if (settingsPatchTouchesManualKeyForUi(patch)) return true;
  if (patch?.privacy && typeof patch.privacy === 'object' && !Array.isArray(patch.privacy)) return true;
  if (patch?.render && typeof patch.render === 'object' && !Array.isArray(patch.render)) return true;
  if (patch?.link_preview && typeof patch.link_preview === 'object' && !Array.isArray(patch.link_preview)) return true;
  return false;
}

function responseCancelledDigestRuntimeWork(response = null) {
  return (Array.isArray(response?.warnings) ? response.warnings : [])
    .some(w => String(w?.code || '').trim() === 'active_digest_cancelled_after_runtime_change');
}

function settingsPatchResultChangedDigestRuntime(patch = {}, response = null) {
  if (responseCancelledDigestRuntimeWork(response)) return true;
  if (response && typeof response === 'object' && Object.hasOwn(response, 'digest_runtime_changed')) return response.digest_runtime_changed === true;
  return settingsPatchTouchesDigestRuntimeForUi(patch);
}

function invalidateDigestResultsAfterSettingsPatch(patch = {}, response = null, { notice = '' } = {}) {
  if (!settingsPatchResultChangedDigestRuntime(patch, response)) return false;
  const next = currentDigestRuntimeVersion() + 1;
  _state_digest.digestRuntimeVersion = next > Number.MAX_SAFE_INTEGER ? 1 : next;
  invalidateTextPreviewExportTarget({
    sync: false,
    notice: notice || '摘要生成相关设置已变化，请重新生成后再导出 MD。',
  });
  markDigestResultInputChanged();
  return true;
}

function abortTextPreviewActions(reason = '文本预览操作已取消') {
  for (const controller of [..._activeTextPreviewActionControllers]) {
    if (!controller.signal.aborted) controller.abort(digestAbortError(reason));
  }
  _activeTextPreviewActionControllers.clear();
}

function textPreviewActionAbortSignal(message = '文本预览操作已取消', externalSignal = null, { bindRoute = true } = {}) {
  const controller = new AbortController();
  _activeTextPreviewActionControllers.add(controller);
  const abort = () => {
    if (!controller.signal.aborted) controller.abort(digestAbortError(message));
  };
  const unregisterRouteCleanup = bindRoute ? registerRouteCleanup(() => abort()) : () => {};
  const abortFromExternal = () => {
    if (!controller.signal.aborted) controller.abort(externalSignal?.reason || digestAbortError(message));
  };
  if (bindRoute) window.addEventListener('hashchange', abort, { once: true });
  if (externalSignal?.aborted) abortFromExternal();
  else if (externalSignal?.addEventListener) externalSignal.addEventListener('abort', abortFromExternal, { once: true });
  return {
    signal: controller.signal,
    throwIfAborted(fallback = message) {
      if (controller.signal.aborted) throw controller.signal.reason || digestAbortError(fallback);
    },
    done() {
      unregisterRouteCleanup();
      if (bindRoute) window.removeEventListener('hashchange', abort);
      if (externalSignal?.removeEventListener) externalSignal.removeEventListener('abort', abortFromExternal);
      _activeTextPreviewActionControllers.delete(controller);
    },
  };
}

function abortDigestPreviewActions(reason = '长图预览操作已取消') {
  for (const controller of [..._activeDigestPreviewActionControllers]) {
    if (!controller.signal.aborted) controller.abort(digestAbortError(reason));
  }
  _activeDigestPreviewActionControllers.clear();
}

function abortDigestProgressLog(reason = '运行日志读取已取消') {
  if (_digestProgressLogAbortController && !_digestProgressLogAbortController.signal.aborted) {
    _digestProgressLogAbortController.abort(digestAbortError(reason));
  }
  _digestProgressLogAbortController = null;
}

function digestProgressLogAbortSignal(message = '运行日志读取已取消') {
  abortDigestProgressLog('新的运行日志读取已开始');
  const controller = new AbortController();
  _digestProgressLogAbortController = controller;
  const abort = () => {
    if (!controller.signal.aborted) controller.abort(digestAbortError(message));
  };
  const unregisterRouteCleanup = registerRouteCleanup(() => abort());
  window.addEventListener('hashchange', abort, { once: true });
  return {
    signal: controller.signal,
    isCurrent() {
      return _digestProgressLogAbortController === controller;
    },
    done() {
      unregisterRouteCleanup();
      window.removeEventListener('hashchange', abort);
      if (_digestProgressLogAbortController === controller) _digestProgressLogAbortController = null;
    },
  };
}

function digestPreviewActionAbortSignal(message = '长图预览操作已取消') {
  const controller = new AbortController();
  _activeDigestPreviewActionControllers.add(controller);
  const abort = () => {
    if (!controller.signal.aborted) controller.abort(digestAbortError(message));
  };
  const unregisterRouteCleanup = registerRouteCleanup(() => abort());
  window.addEventListener('hashchange', abort, { once: true });
  return {
    signal: controller.signal,
    throwIfAborted(fallback = message) {
      if (controller.signal.aborted) throw controller.signal.reason || digestAbortError(fallback);
    },
    done() {
      unregisterRouteCleanup();
      window.removeEventListener('hashchange', abort);
      _activeDigestPreviewActionControllers.delete(controller);
    },
  };
}

