const HISTORY_FOCUS_ACTION_ATTRIBUTES = Object.freeze([
  'data-history-open',
  'data-history-open-image',
  'data-history-export-md',
  'data-history-delete',
  'data-history-open-md-source',
  'data-history-regenerate-preview',
]);

function normalizeHistoryFocusAction(value = '') {
  const action = String(value || '').trim();
  return HISTORY_FOCUS_ACTION_ATTRIBUTES.includes(action) ? action : '';
}

function historyFocusActionAttribute(element = null) {
  if (!element) return '';
  return HISTORY_FOCUS_ACTION_ATTRIBUTES.find(attribute => element.hasAttribute?.(attribute)) || '';
}

let _state_history = {
  items: [],
  query: '',
  filterMode: 'ok',
  accountMode: 'current',
  loadedCount: 0,
  scrollY: 0,
  focusKey: '',
  focusAction: '',
  restorePending: false,
};

function discardPersistedHistoryViewState() {
  _historyRouteFocusRestorePending = false;
  try { sessionStorage.removeItem(HISTORY_VIEW_STORAGE_KEY); } catch {}
}

function historyViewScopeIdentity(state = _appState) {
  const projectRoot = normalizePathForUi(state?.project_root || '');
  if (!projectRoot) return '';
  return platformPathIdentityForUi(projectRoot, state?.platform);
}

function normalizePersistedHistoryViewState(value = null, scopeIdentity = historyViewScopeIdentity()) {
  if (!value || typeof value !== 'object' || Number(value.version) !== 3) return null;
  const savedAt = Number(value.saved_at || 0);
  if (!Number.isFinite(savedAt) || savedAt <= 0 || Date.now() - savedAt > HISTORY_VIEW_STORAGE_MAX_AGE_MS) return null;
  const expectedScopeIdentity = String(scopeIdentity || '').trim();
  const savedScopeIdentity = String(value.history_scope_identity || '').trim();
  if (!expectedScopeIdentity || savedScopeIdentity !== expectedScopeIdentity) return null;
  const focusAction = normalizeHistoryFocusAction(value.focus_action);
  return {
    query: String(value.query || '').trim().slice(0, 500),
    filterMode: String(value.filter_mode || '').trim() === 'issues' ? 'issues' : 'ok',
    accountMode: String(value.account_mode || '').trim() === 'all' ? 'all' : 'current',
    loadedCount: Math.max(
      HISTORY_PAGE_SIZE,
      Math.min(HISTORY_VIEW_STORAGE_MAX_LOADED_ITEMS, Number(value.loaded_count || 0) || HISTORY_PAGE_SIZE),
    ),
    scrollY: Math.max(0, Number(value.scroll_y || 0) || 0),
    focusKey: String(value.focus_key || '').trim().slice(0, 320),
    focusAction,
    restorePending: true,
  };
}

function restorePersistedHistoryViewState() {
  let snapshot = null;
  try {
    snapshot = normalizePersistedHistoryViewState(JSON.parse(sessionStorage.getItem(HISTORY_VIEW_STORAGE_KEY) || 'null'));
  } catch {}
  if (!snapshot) {
    discardPersistedHistoryViewState();
    return false;
  }
  Object.assign(_state_history, snapshot);
  _historyRouteFocusRestorePending = !!snapshot.focusKey;
  return true;
}

function persistHistoryViewState({ query = '', filterMode = 'ok', accountMode = 'current', loadedCount = 0, scrollY = 0, focusKey = '', focusAction = '' } = {}) {
  const historyScopeIdentity = historyViewScopeIdentity();
  if (!historyScopeIdentity) return false;
  const snapshot = {
    version: 3,
    saved_at: Date.now(),
    history_scope_identity: historyScopeIdentity,
    query: String(query || '').trim().slice(0, 500),
    filter_mode: String(filterMode || '').trim() === 'issues' ? 'issues' : 'ok',
    account_mode: String(accountMode || '').trim() === 'all' ? 'all' : 'current',
    loaded_count: Math.max(
      HISTORY_PAGE_SIZE,
      Math.min(HISTORY_VIEW_STORAGE_MAX_LOADED_ITEMS, Number(loadedCount || 0) || HISTORY_PAGE_SIZE),
    ),
    scroll_y: Math.max(0, Number(scrollY || 0) || 0),
    focus_key: String(focusKey || '').trim().slice(0, 320),
    focus_action: normalizeHistoryFocusAction(focusAction),
  };
  try {
    sessionStorage.setItem(HISTORY_VIEW_STORAGE_KEY, JSON.stringify(snapshot));
    return true;
  } catch {
    return false;
  }
}
