function clearDigestGroupCache(reason = '群列表缓存上下文已变化', { preserveLease = null } = {}) {
  for (const cache of DIGEST_GROUP_CACHE.values()) {
    if (preserveLease && cache?.promiseLease === preserveLease) continue;
    cache?.promiseLease?.abort?.(reason);
  }
  DIGEST_GROUP_CACHE.clear();
}
const DIGEST_CANVAS_MAX_DEVICE_SIDE = 32767;
const DIGEST_CANVAS_MAX_DEVICE_PIXELS = Math.floor(SAVE_RENDER_UPLOAD_MAX_CANVAS_RGBA_BYTES / 4);
const DIGEST_CANVAS_LOW_MEMORY_RGBA_BYTES = 64 * 1024 * 1024;
const DIGEST_CANVAS_MOBILE_RGBA_BYTES = 96 * 1024 * 1024;
const GROUP_LIST_LOAD_PULSE_STEPS = [
  '已提交读取请求，等待本地服务返回真实群列表阶段',
  '本地服务仍在处理，等待真实群列表阶段更新',
];

function formatGroupLoadElapsed(startedAt = Date.now()) {
  const seconds = Math.max(1, Math.floor((Date.now() - Number(startedAt || Date.now())) / 1000));
  const minutes = Math.floor(seconds / 60);
  const rest = seconds % 60;
  return minutes ? `${minutes}分${String(rest).padStart(2, '0')}秒` : `${seconds}秒`;
}

function formatGroupLoadElapsedMs(elapsedMs = 0) {
  const seconds = Math.max(1, Math.floor(Math.max(0, Number(elapsedMs || 0) || 0) / 1000));
  const minutes = Math.floor(seconds / 60);
  const rest = seconds % 60;
  return minutes ? `${minutes}分${String(rest).padStart(2, '0')}秒` : `${seconds}秒`;
}

function startManualKeySaveStatus(status, {
  accountId = '',
  keyCount = 0,
  signal = null,
  isActive = null,
} = {}) {
  if (!status) return () => {};
  const accountLabel = selectedAccountInfo()?.name || selectedAccountId() || '当前账号';
  const countText = keyCount ? `${keyCount} 条` : '当前输入';
  const stillCurrent = () => status.isConnected
    && !signal?.aborted
    && (typeof isActive !== 'function' || isActive(accountId) !== false);
  return startElapsedStatusProgress(status, {
    signal,
    isCurrent: stillCurrent,
    text: `正在提交 ${accountLabel} 的 ${countText} 手动密钥候选，等待本地服务确认保存结果`,
    warnAfterMs: 30_000,
    warnText: '保存仍未返回；本地数据、账号复核或后台状态更新可能较慢，请不要重复点击',
  });
}

function startElapsedStatusProgress(status, {
  text = '',
  warnText = '',
  warnAfterMs = 30_000,
  signal = null,
  isCurrent = null,
  getText = null,
} = {}) {
  if (!status) return () => {};
  const startedAt = Date.now();
  let stopped = false;
  let timer = null;
  const paint = () => {
    if (stopped || signal?.aborted || (typeof isCurrent === 'function' && !isCurrent())) return;
    const elapsedMs = Date.now() - startedAt;
    const slow = elapsedMs >= Math.max(0, Number(warnAfterMs || 0) || 0);
    let liveText = '';
    try {
      liveText = typeof getText === 'function' ? String(getText({ elapsedMs, slow }) || '').trim() : '';
    } catch {}
    status.className = !liveText && slow && warnText ? 'status warn' : 'status';
    status.textContent = formatDigestElapsedDetail(liveText || (slow && warnText ? warnText : text), startedAt);
  };
  const stop = () => {
    if (stopped) return;
    stopped = true;
    if (timer) clearInterval(timer);
    timer = null;
    signal?.removeEventListener?.('abort', stop);
  };
  paint();
  timer = setInterval(paint, 5_000);
  signal?.addEventListener?.('abort', stop, { once: true });
  return stop;
}

function startStagedStatusProgress(status, steps, { signal = null, isCurrent = null } = {}) {
  if (!status || !Array.isArray(steps) || !steps.length) return () => {};
  const startedAt = Date.now();
  let stopped = false;
  const timers = [];
  const paint = step => {
    if (stopped || signal?.aborted || (typeof isCurrent === 'function' && !isCurrent())) return;
    status.className = step.className || 'status';
    status.textContent = formatDigestElapsedDetail(step.text, startedAt);
  };
  for (const step of steps) {
    const after = Math.max(0, Number(step.after || 0));
    if (after === 0) paint(step);
    else timers.push(setTimeout(() => paint(step), after));
  }
  const stop = () => {
    if (stopped) return;
    stopped = true;
    timers.forEach(timer => clearTimeout(timer));
    signal?.removeEventListener?.('abort', stop);
  };
  signal?.addEventListener?.('abort', stop, { once: true });
  return stop;
}

function startGroupLoadPulse(onPulse, {
  prefix = '正在读取群列表',
  signal = null,
  immediate = true,
  shouldContinue = null,
} = {}) {
  const startedAt = Date.now();
  let tick = 0;
  let stopped = false;
  let timer = null;
  const emit = () => {
    if (stopped || signal?.aborted) return;
    if (typeof shouldContinue === 'function' && !shouldContinue()) {
      stop();
      return;
    }
    const step = GROUP_LIST_LOAD_PULSE_STEPS[tick % GROUP_LIST_LOAD_PULSE_STEPS.length];
    const elapsed = formatGroupLoadElapsed(startedAt);
    tick += 1;
    onPulse?.({
      prefix,
      step,
      elapsed,
      text: `${prefix}：${step}（已用时 ${elapsed}）`,
      startedAt,
      tick,
    });
  };
  const stop = () => {
    stopped = true;
    if (timer) clearInterval(timer);
    signal?.removeEventListener?.('abort', stop);
  };
  if (immediate) emit();
  if (stopped) return stop;
  timer = setInterval(emit, GROUP_LIST_LOAD_PULSE_MS);
  signal?.addEventListener?.('abort', stop, { once: true });
  return stop;
}

function createGroupProgressId() {
  if (window.crypto?.randomUUID) return `grp_${window.crypto.randomUUID().replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 48)}`;
  const bytes = new Uint8Array(8);
  try { window.crypto?.getRandomValues?.(bytes); } catch {}
  const random = [...bytes].map(value => value.toString(16).padStart(2, '0')).join('') || Math.random().toString(16).slice(2, 18);
  return `grp_${Date.now().toString(36)}_${random}`;
}

function createWechatStatusProgressId() {
  if (window.crypto?.randomUUID) return `wst_${window.crypto.randomUUID().replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 48)}`;
  const bytes = new Uint8Array(8);
  try { window.crypto?.getRandomValues?.(bytes); } catch {}
  const random = [...bytes].map(value => value.toString(16).padStart(2, '0')).join('') || Math.random().toString(16).slice(2, 18);
  return `wst_${Date.now().toString(36)}_${random}`;
}

