  // chip 输入
  document.querySelectorAll('.chip-input').forEach(box => {
    const name = box.dataset.name;
    const inp = box.querySelector('input');
    function removeChip(span, value) {
      if (_state_digest.generating) return;
      _state_digest.filters[name] = _state_digest.filters[name].filter(x => x !== value);
      span.remove();
      markDigestResultInputChanged();
    }
    function renderChip(value) {
      const span = document.createElement('span');
      span.className = 'chip';
      span.append(document.createTextNode(value + ' '));
      const close = document.createElement('button');
      close.type = 'button';
      close.className = 'x';
      close.setAttribute('aria-label', `移除筛选：${value}`);
      close.textContent = '×';
      span.append(close);
      close.addEventListener('click', () => removeChip(span, value));
      box.insertBefore(span, inp);
    }
    function addChip(v) {
      if (_state_digest.generating) return false;
      const values = String(v || '').split(/[\s,，;；]+/).map(item => item.trim()).filter(Boolean);
      let changed = false;
      for (const value of values) {
        if (_state_digest.filters[name].includes(value)) continue;
        _state_digest.filters[name].push(value);
        renderChip(value);
        changed = true;
      }
      if (changed) markDigestResultInputChanged();
      return changed;
    }
    function syncChipsFromState() {
      box.querySelectorAll('.chip').forEach(chip => chip.remove());
      (_state_digest.filters[name] || []).forEach(value => renderChip(value));
      inp.value = String(_state_digest.pendingFilters?.[name] || '');
    }
    box._syncDigestDraft = syncChipsFromState;
    syncChipsFromState();
    box._commitPendingChip = () => {
      if (_state_digest.generating) return;
      const value = inp.value.trim();
      if (!value) return;
      inp.value = '';
      _state_digest.pendingFilters[name] = '';
      if (!addChip(value)) markDigestResultInputChanged();
    };
    inp.addEventListener('keydown', e => {
      if (e.isComposing || e.keyCode === 229) return;
      if (e.key === 'Enter' || e.key === ',') {
        e.preventDefault();
        box._commitPendingChip();
      } else if (e.key === 'Backspace' && !inp.value) {
        const last = box.querySelectorAll('.chip');
        if (last.length) {
          const v = last[last.length - 1].textContent.trim().replace(/×$/, '').trim();
          removeChip(last[last.length - 1], v);
        }
      }
    });
    inp.addEventListener('input', () => {
      if (_state_digest.generating) return;
      _state_digest.pendingFilters[name] = inp.value;
      markDigestResultInputChanged();
    });
  });

