        <div class="swatch-row" role="group" aria-labelledby="${id}-accent-label">
          ${DIGEST_ACCENTS.map(item => `<button class="color-swatch ${!selection.accent_color && selection.accent === item.id ? 'selected' : ''}" type="button" data-accent="${item.id}" title="${item.label}" aria-label="${item.label}" aria-pressed="${!selection.accent_color && selection.accent === item.id ? 'true' : 'false'}" style="--swatch:${item.light}"></button>`).join('')}
          ${selection.accent_color ? `<button class="color-swatch selected" type="button" data-accent="${escapeHtml(selection.accent)}" data-accent-color="${escapeHtml(selection.accent_color)}" title="保留原记录强调色 ${escapeHtml(selection.accent_color)}" aria-label="保留原记录强调色 ${escapeHtml(selection.accent_color)}" aria-pressed="true" style="--swatch:${escapeHtml(selection.accent_color)}"></button>` : ''}
        </div>
