function digestAiDirectRetryAllowed(error = {}) {
  const code = String(error?.code || error || '').trim();
  return [
    'ai_timeout',
    'ai_deadline_exceeded',
    'ai_network_failed',
    'ai_provider_unavailable',
    'ai_rate_limited',
    'ai_failed',
    'ai_empty_output',
    'ai_json_parse_failed',
    'ai_quality_failed',
  ].includes(code);
}

function digestAiRequestOutcomeUnknown(value = {}) {
  const meta = value && typeof value === 'object' ? value : {};
  const nestedMeta = meta.meta && typeof meta.meta === 'object' ? meta.meta : {};
  const sources = [
    meta,
    meta.diagnostics,
    meta.ai_diagnostics,
    nestedMeta,
    nestedMeta.diagnostics,
    nestedMeta.ai_diagnostics,
  ].filter(item => item && typeof item === 'object');
  return sources.some(item => item.provider_response_unknown === true
    || String(item.request_outcome || '').trim().toLowerCase() === 'ambiguous');
}

function digestAiRetryNeedsConfirmation(error = {}, retryCandidates = []) {
  return [error, ...(Array.isArray(retryCandidates) ? retryCandidates : [])]
    .some(digestAiRequestOutcomeUnknown);
}

function digestAiRetryAfterMs(error = {}, retryCandidates = []) {
  const direct = Math.max(
    0,
    Number(error?.retry_after_ms || 0) || 0,
    Number(error?.diagnostics?.retry_after_ms || 0) || 0,
    Number(error?.ai_diagnostics?.retry_after_ms || 0) || 0,
  );
  return (Array.isArray(retryCandidates) ? retryCandidates : []).reduce((max, result) => Math.max(
    max,
    Number(result?.meta?.retry_after_ms || 0) || 0,
    Number(result?.meta?.diagnostics?.retry_after_ms || 0) || 0,
    Number(result?.meta?.ai_diagnostics?.retry_after_ms || 0) || 0,
  ), direct);
}

function setProgressAiRecovery(error = {}, tools = null, status = null) {
  if (!tools) return false;
  const first = tools.firstChild;
  const group = digestAiRecoveryGroup(error);
  const code = String(error?.code || '').trim();
  if (code === 'ai_group_generation_in_progress') {
    if (status?.isConnected) {
      status.className = 'status warn';
      status.textContent = '这个群已有一项生成正在进行；本次没有再次请求 AI。请等待原任务结束后再重新生成。';
    }
    return true;
  }
  const target = digestAiSettingsTarget(error);
  if (digestAiDirectRetryAllowed(error)) {
    const previewText = _state_digest.progress?.previewText === true;
    const retryCandidates = digestBatchRetryCandidates(_state_digest.batchResults);
    const retryNeedsConfirmation = digestAiRetryNeedsConfirmation(error, retryCandidates);
    const completedResultExists = (_state_digest.batchResults || []).some(result => result && !digestBatchResultRetryable(result));
    const retryLabel = completedResultExists && retryCandidates.length
      ? (previewText ? '重新预览未完成群' : '重新生成未完成群')
      : (previewText ? '重新预览文本' : '重新生成');
    const retryButton = progressRecoveryButton(
      'progress-retry-ai-generation',
      retryLabel,
      async event => {
        const button = event.currentTarget;
        const recoveryAction = beginDigestProgressRecoveryAction(button, '准备重试...');
        if (!recoveryAction) return;
        try {
          if (retryNeedsConfirmation) {
            const confirmed = await showAppConfirmDialog({
              title: '确认再次请求 AI',
              messages: [
                '上一次请求在超时或网络中断前可能已经到达 AI 服务商，但程序没有收到最终响应。',
                '再次请求可能产生重复调用或重复计费。请先检查服务商请求记录，或确认接受这个风险后再继续。',
              ],
              confirmText: '仍要再次请求',
              cancelText: '先不重试',
              tone: 'err',
            });
            if (!confirmed) {
              if (status?.isConnected) {
                status.className = 'status warn';
                status.textContent = '已取消再次请求 AI；没有发起新的生成。';
              }
              return;
            }
          }
          if (retryCandidates.length && !selectDigestBatchRetryGroups()) {
            if (status?.isConnected) {
              status.className = 'status warn';
              status.textContent = '未完成群不在当前账号群列表中，请先刷新群列表或确认右上角账号。';
            }
            return;
          }
          const generateButton = document.getElementById(previewText ? 'btn-preview-text' : 'btn-generate');
          if (!generateButton || generateButton.disabled) {
            if (status?.isConnected) {
              status.className = 'status warn';
              status.textContent = '当前生成按钮仍在处理上一批任务；请等页面解除锁后再重试。';
            }
            return;
          }
          generateButton.click();
        } finally {
          endDigestProgressRecoveryAction(recoveryAction);
        }
      },
      retryNeedsConfirmation
        ? '上一次请求结果未确认；再次请求可能重复调用或重复计费，点击后会先要求确认'
        : retryCandidates.length
        ? '只重试本批未完成群，保留当前账号、时间范围和筛选条件；已成功群不会重复请求 AI'
        : '保留当前账号、群、时间范围和筛选条件，重新请求 AI；端点恢复后可直接重试',
    );
    const retryAfterMs = digestAiRetryAfterMs(error, retryCandidates);
    tools.insertBefore(retryButton, first);
    armProgressRetryCooldown(retryButton, retryLabel, retryAfterMs);
  }
  const settingsButton = document.createElement('button');
  settingsButton.className = 'btn btn-ghost';
  settingsButton.type = 'button';
  settingsButton.id = 'progress-open-ai-settings';
  settingsButton.dataset.progressRecovery = '1';
  settingsButton.textContent = target.section === 'privacy'
    ? '打开媒体隐私设置'
    : (group === 'settings' ? '打开 AI 设置' : '打开 AI 设置运行基础连通测试');
  settingsButton.addEventListener('click', () => {
    void openSettingsSection(target.section, { focusSelector: target.focusSelector }).then(ok => {
      if (!ok || !status?.isConnected) return;
      status.className = 'status warn';
      status.textContent = target.section === 'privacy'
        ? '已打开隐私与安全设置；可关闭“图片、视频关键帧和语音附给 AI 识别”，或回 AI 设置更换支持媒体的模型。'
        : group === 'content'
        ? '已打开 AI 设置；可换长上下文模型或调整模型后保存，也可以回总结页缩短时间范围后重试。'
        : '已打开 AI 设置；请检查 API Key、Base URL、模型，并点击“获取模型”或“基础连通测试”。';
    });
  });
  tools.insertBefore(settingsButton, first);

  if (group === 'content') {
    const rangeButton = document.createElement('button');
    rangeButton.className = 'btn btn-ghost';
    rangeButton.type = 'button';
    rangeButton.id = 'progress-shorten-digest-range';
    rangeButton.dataset.progressRecovery = '1';
    rangeButton.textContent = '缩短时间范围';
    rangeButton.addEventListener('click', () => {
      const target = document.getElementById('quick-range') || document.getElementById('range-picker') || document.getElementById('custom-range');
      if (target) {
        scrollDigestWorkIntoView(target);
        const focusTarget = target.querySelector?.('button, input, select') || target;
        try { focusTarget.focus?.({ preventScroll: true }); } catch {}
      }
      if (status?.isConnected) {
        status.className = 'status warn';
        status.textContent = '请缩短时间范围、减少群或改用长上下文模型后重新生成。';
      }
    });
    tools.insertBefore(rangeButton, settingsButton.nextSibling);
  }
  return true;
}

function digestAiSettingsFocusSelector(error = {}) {
  const code = String(error?.code || '').trim();
  if (code === 'ai_api_key_missing' || code === 'ai_auth_failed') return '#s-apikey';
  if (code === 'ai_base_url_missing' || code === 'ai_network_failed' || code === 'ai_provider_unavailable' || code === 'ai_timeout') return '#s-baseurl';
  if (code === 'ai_model_media_unsupported') return '#s-attach-media';
  if (code === 'ai_model_not_available') return '#s-list-models';
  if (code === 'ai_model_missing' || code === 'ai_output_truncated' || code === 'ai_json_parse_failed' || code === 'ai_quality_failed' || code === 'ai_empty_output' || code === 'ai_content_filtered' || code === 'ai_call_budget_exceeded' || code === 'ai_request_invalid') return '#s-model-select';
  if (code === 'ai_rate_limited') return '#s-ai-concurrency';
  return '#s-test-llm';
}

function digestAiSettingsTarget(error = {}) {
  const code = String(error?.code || '').trim();
  return {
    section: code === 'ai_model_media_unsupported' ? 'privacy' : 'ai',
    focusSelector: digestAiSettingsFocusSelector(error),
  };
}

function digestMirrorRetryStillCurrent(routeSeq, accountId, statusEl = null) {
  return routeSeq === _routeSeq
    && normalizeAppHash(location.hash || '#/digest') === '#/digest'
    && selectedAccountMatches(accountId)
    && (!statusEl || statusEl.isConnected);
}

function digestKeyRetryStillCurrent(routeSeq, accountId, statusEl = null) {
  return digestMirrorRetryStillCurrent(routeSeq, accountId, statusEl);
}

async function retryDbMirrorForAccount({
  button = null,
  statusEl = null,
  accountId = selectedAccountId(),
  successText = '✓ 本地数据已就绪；请重新点击生成',
  onSuccess = null,
  fullInventory = false,
  forceMirror = true,
} = {}) {
  const previousDisabled = !!button?.disabled;
  const recoveryAction = beginDigestProgressRecoveryAction(button, '刷新本地数据中...');
  if (!recoveryAction) return false;
  const routeSeq = _routeSeq;
  const retryAbort = new AbortController();
  const unregister = registerRouteCleanup(() => {
    if (!retryAbort.signal.aborted) {
        retryAbort.abort(digestAbortError('已离开当前页面，本地数据检查已取消'));
    }
  });
  const stillCurrent = () => digestMirrorRetryStillCurrent(routeSeq, accountId, statusEl);
  const forceMirrorRefresh = fullInventory || forceMirror !== false;
  const setStatus = (className, text) => {
    if (!statusEl || !stillCurrent()) return false;
    statusEl.className = className;
    statusEl.textContent = text;
    return true;
  };
  if (!recoveryAction.tracked && button) button.disabled = true;
  setStatus('status', forceMirrorRefresh
    ? '正在检查本地数据并刷新群列表...'
    : '正在优先复用已验证的群列表本地数据...');
  try {
    clearDigestGroupCache('正在重新检查微信本地数据');
    if (fullInventory) {
      setStatus('status', '正在重新检查完整本地数据...');
      await prepareDbMirrorInventory(accountId, {
        forceMirror: true,
        signal: retryAbort.signal,
        progressSignal: retryAbort.signal,
        progressPrefix: '正在重新检查完整本地数据',
        shouldContinue: stillCurrent,
        onProgress: ({ text }) => {
          setStatus('status', text || '正在重新检查完整本地数据...');
        },
      });
      if (!stillCurrent()) return false;
      setStatus('status', '本地数据已就绪，正在刷新群列表...');
    } else {
      setStatus('status', forceMirrorRefresh
        ? '正在检查群列表所需本地数据...'
        : '正在优先复用已验证的群列表本地数据...');
    }
    const refreshedGroups = await fetchDigestGroups(accountId, {
      force: true,
      forceMirror: forceMirrorRefresh,
      signal: retryAbort.signal,
      progressPrefix: '检查本地数据后刷新群列表',
      shouldContinue: stillCurrent,
      onProgress: ({ text }) => {
        setStatus('status', text || '正在检查本地数据后刷新群列表...');
      },
    });
    if (!stillCurrent()) return false;
    clearDbMirrorAutoFailure(accountId);
    const stateRefreshWarning = await refreshAppStateForVisibleAction({
      signal: retryAbort.signal,
      target: '本机状态',
    });
    if (!stillCurrent()) return false;
    const accountMeta = await refreshTopbarAccounts({
      returnMeta: true,
      preserveMissingSelection: true,
      force: true,
      signal: retryAbort.signal,
    });
    if (!stillCurrent()) return false;
    if (accountMeta?.applied === false) {
      setStatus('status warn', '账号列表已由更新的刷新请求接管；请按当前右上角账号确认后再继续。');
      return false;
    }
    if (accountMeta?.selectionLost || accountMeta?.selectionChanged || accountMeta?.accountContextChanged) {
      setStatus('status warn', `本地数据已就绪${stateRefreshWarning}；账号列表已变化，请先确认右上角账号。`);
      return true;
    }
    if (Array.isArray(refreshedGroups)) {
      _digestGroupListPainter?.({
        nextGroups: refreshedGroups,
        status: '本地数据和群列表已刷新',
      });
    }
    setStatus(stateRefreshWarning ? 'status warn' : 'status ok', `${successText}${stateRefreshWarning}`);
    if (typeof onSuccess === 'function') await onSuccess();
    return true;
  } catch (e) {
    if (retryAbort.signal.aborted || e?.name === 'AbortError' || e?.status === 499) return false;
    if (statusEl && stillCurrent() && setReloadRequiredStatus(statusEl, e, '本地数据检查')) return false;
    if (digestFailureRecoveryKind(e) === 'mirror') {
      rememberDbMirrorAutoFailure(e, accountId);
    } else {
      clearDbMirrorAutoFailure(accountId);
    }
    setStatus('status err', `本地数据检查失败：${compactErrorSummary(e?.message || '未知错误')}`);
    return false;
  } finally {
    unregister();
    endDigestProgressRecoveryAction(recoveryAction);
    if (!recoveryAction.tracked && button?.isConnected) button.disabled = previousDisabled;
  }
}

async function retryDbMirrorFromProgress(button, statusEl) {
  await retryDbMirrorForAccount({ button, statusEl });
}

