            accountId,
            accountFingerprint,
            since,
            until,
            batchId,
            batchToken,
            batchServiceInstanceId,
            batchIndex: i,
            batchTotal: targets.length,
            previewText,
            batchSnapshot,
            signal: controller.signal,
