        status.className = 'status warn';
        status.textContent = recovered
          ? `导出已完成，后续取消未影响已写入文件；但${reason}，${target} 未绑定到当前下载/显示入口，请重新导出。`
          : `导出已完成，但${reason}；${target} 未绑定到当前下载/显示入口，请重新导出。`;
