      syncHistoryMarkdownButtons();
      const versionMissing = textPreviewExportedMarkdownVersionMissing(historyMarkdownExportItem);
      status.className = versionMissing ? 'status warn' : 'status ok';
      const locationHint = exportSourceItem.history_current === false ? '（已保存到当前输出目录）' : '';
      const privacyHint = r.redacted ? '（已按隐私设置脱敏保存）' : '';
