  const canOpenWrittenHistory = outputItemHistoryBound(noticeItem);
  const canOpenWrittenOutputDirectory = !canRevealWrittenFile && outputItemCurrentOutputDirectoryOpenable(noticeItem);
  const afterReason = markdownExportAfterCommitReason({ item: noticeItem });
  const afterUnbound = !!afterReason && afterReason !== 'cancelled_after_commit';
  const targetUnavailableReason = canRevealWrittenFile ? '' : markdownOutputUnusableReasonText(noticeItem);
  const persistSuffix = localActionEvidencePersistSuffix(result, '导出 MD');
