    markMarkdownFloatingNoticeUnbound(notice, {
      reason,
      title: '文本预览 MD 入口已过期',
      message: `${reason}；这条浮层已不再绑定刚导出的文本预览 MD，已移除“显示导出源 MD”入口。请回到总结后重新导出。`,
    });
