  function settingsActionAbortSignal(message = '设置页请求已取消') {
    const controller = new AbortController();
    const abort = event => {
      const eventReason = event?.type === SETTINGS_ACTION_ABORT_EVENT ? event?.detail?.reason : '';
      const abortMessage = typeof eventReason === 'string' && eventReason ? eventReason : message;
      if (!controller.signal.aborted) controller.abort(digestAbortError(abortMessage));
    };
    window.addEventListener(SETTINGS_ACTION_ABORT_EVENT, abort, { once: true });
    return {
      signal: controller.signal,
      abort(reason = message) {
        if (!controller.signal.aborted) controller.abort(digestAbortError(reason));
      },
      done() {
        window.removeEventListener(SETTINGS_ACTION_ABORT_EVENT, abort);
      },
    };
  }
