  async function refreshSettingsAccountsAfterWechatChange({ acceptedIdentityUpgrade = null } = {}) {
    settingsAccountRefreshInFlight += 1;
    syncSchedulerAccountGate({ paintStatus: true });
    try {
      const meta = await refreshTopbarAccounts({
        returnMeta: true,
        preserveMissingSelection: true,
        force: true,
        acceptedIdentityUpgrade,
      }).catch(error => ({ error, selectionChanged: false, selectionLost: true }));
      if (settingsRouteSeq !== _routeSeq || !document.getElementById('s-llm-status')) return meta;
      if (meta?.applied === false) {
        const error = settingsAccountReconcileSupersededError();
        settingsAccountRefreshError = error;
        return { ...meta, reconcile_superseded: true, error };
      }
      settingsAccountRefreshError = meta?.error || null;
      if (meta?.identityUpgraded) {
        settingsPendingAccountIdentityUpgradeSuffix = accountIdentityUpgradeStatusSuffix(meta);
        const upgradedAccountId = currentSettingsRequestAccountId();
        const upgradedAccountFingerprint = accountFingerprintForValue(upgradedAccountId);
        if (settingsValidatedManualDraft
          && accountScopeUniquelyMatches(settingsValidatedManualDraft.account_id, upgradedAccountId)) {
          settingsValidatedManualDraft.account_id = upgradedAccountId;
          settingsValidatedManualDraft.account_data_generation = _accountDataGeneration;
        }
        if (settingsManualKeyAutoSaveIntent
          && accountScopeUniquelyMatches(settingsManualKeyAutoSaveIntent.account_id, upgradedAccountId)) {
          settingsManualKeyAutoSaveIntent.account_id = upgradedAccountId;
          settingsManualKeyAutoSaveIntent.account_fingerprint = upgradedAccountFingerprint;
        }
        settingsAccountId = upgradedAccountId;
        settingsAccountFingerprint = upgradedAccountFingerprint;
      }
      if (meta?.staleAutoSwitchSuppressed) {
        paintSettingsStaleAccountConfirmation(
          document.getElementById('s-privacy-status'),
          '当前账号目录较久未同步；保存后的账号复核保留了提交时账号，没有自动切换。请确认仍使用该账号，或切换到最近同步账号。',
        );
        return meta;
      }
      if (meta?.selectionLost) {
        markSettingsAccountStale('账号列表已变化，原账号暂不可用。请在页面右上角重新选择微信账号后再保存设置，避免写到错误账号。');
        if (meta?.error) attachSettingsAccountRetryToVisibleStatuses();
        return meta;
      }
      if (meta?.selectionChanged) {
        markSettingsAccountStale('账号列表已变化，但设置页不会在保存复核后自动切换账号。请确认右上角账号后再继续，避免把后续设置写到错误账号。');
        return meta;
      }
      if (meta?.accountContextChanged
        || (settingsAccountFingerprint
          && accountFingerprintForValue(settingsAccountId)
          && settingsAccountFingerprint !== accountFingerprintForValue(settingsAccountId))) {
        markSettingsAccountStale('当前账号标识未变，但对应的本地数据身份已变化。为避免把旧草稿或密钥写到新账号，本页已锁定；请重新载入设置页后确认。');
        return meta;
      }
      if (selectedAccountMatches(settingsAccountId)) {
        settingsAccountId = currentSettingsRequestAccountId();
      }
      clearSettingsAccountRetryButtons();
      if (meta?.accountsChanged) {
        reconcileSchedulerOverridesAfterAccountRefresh('账号列表已刷新；已按最新账号范围重新整理每群规则，旧格式无账号规则不会参与后台执行，已隐藏并保留。');
      }
      requestSettingsGroupsLoad({ force: true });
      return meta;
    } finally {
      settingsAccountRefreshInFlight = Math.max(0, settingsAccountRefreshInFlight - 1);
      if (settingsRouteSeq === _routeSeq && document.getElementById('s-scheduler-status')) {
        syncSchedulerAccountGate({ paintStatus: true });
      }
    }
  }
  function peekDurationControlValue(fieldId, fallback, { maxMs = 0 } = {}) {
    const fallbackParts = parseDurationParts(fallback);
    const amountInput = document.getElementById(`${fieldId}-value`);
    const rawAmount = String(amountInput?.value || '').trim();
    const unit = ['m', 'h', 'd'].includes(document.getElementById(`${fieldId}-unit`)?.value)
      ? document.getElementById(`${fieldId}-unit`).value
      : fallbackParts.unit;
    if (!amountInput) return `${fallbackParts.amount}${fallbackParts.unit}`;
    if (!/^\d+$/.test(rawAmount) || !Number.isSafeInteger(Number(rawAmount)) || Number(rawAmount) < 1) {
      return rawAmount ? `${rawAmount}${unit}` : '';
    }
    const amount = Number(rawAmount);
    return `${amount}${unit}`;
  }
  function durationControlClampMessage(fieldId, label, { maxMs = 0 } = {}) {
    if (!maxMs) return '';
    const amountInput = document.getElementById(`${fieldId}-value`);
    const unitInput = document.getElementById(`${fieldId}-unit`);
    const rawAmount = Number.parseInt(String(amountInput?.value || '').trim(), 10);
    if (!Number.isFinite(rawAmount) || rawAmount < 1) return '';
    const unit = ['m', 'h', 'd'].includes(unitInput?.value) ? unitInput.value : 'm';
    const maxAmount = Math.max(1, Math.min(999, Math.floor(maxMs / durationPartScale(unit))));
    if (rawAmount <= maxAmount) return '';
    const unitLabel = unit === 'm' ? '分钟' : unit === 'h' ? '小时' : '天';
    return `${label}最大 ${maxAmount} ${unitLabel}，已自动调整为 ${maxAmount} ${unitLabel}`;
  }

  // AI
