    schedulerOverrides = schedulerOverrides.filter(item => String(item.account_id || '').trim());
    preservedSchedulerOverrides = preservedSchedulerOverrides.filter(item => String(item.account_id || '').trim());
    clearAllWhitelistOnSave = true;
    removeHiddenLegacyWhitelistOnSave = true;
    removeHiddenLegacyOverridesOnSave = true;
