          $st.textContent = '密钥验证请求已取消，正在刷新本机状态...';
          const warning = await refreshAppStateForVisibleSettingsAction({ refresh: true }).catch(err => visibleSettingsStateRefreshWarning(err?.signal || null));
          if (settingsPageStillActive() && selectedAccountMatches(accountId)) {
            $st.className = 'status warn';
            $st.textContent = `密钥验证请求已取消；如果服务端已写入验证记录或旧版密钥迁移，刷新后的本机状态会生效${warning || ''}。请核对后再保存或生成。`;
          }
