    const moduleText = diagnosticsProbeResultLabel('微信模块深扫', diag?.weixin_modules);
    const mediaText = diagnosticsProbeResultLabel('媒体工具探测', diag?.media_tools);
    return `完整诊断：${moduleText}；${mediaText}`;
